// DGA's Essential Digital Transformation Standards (المعايير الأساسية للتحول الرقمي), the standards
// measured by Qiyas: version 5.0, April 2026, document DGA-1-2-1-111. Read from DGA's published PDF.
// DGA publishes the document in Arabic only, so the nodes carry Arabic text and no English.

import type { FrameworkRequirement, HierarchyLevel } from "./types";

type Row = [code: string, ar: string, textAr?: string, evidenceAr?: string];

const ROWS: Row[] = [
  ["P1", "الإستراتيجية والتخطيط"],
  ["5.1", "التخطيط للتحول الرقمي", "يشمل المحور تطوير خطة إستراتيجية للتحول الرقمي وخارطة طريق تضعها الجهة الحكومية لتخطيط مسار تطوير الأنظمة والعمليات الأساسية، للوصول إلى رؤية الجهة والأهداف الإستراتيجية التي ترغب الجهة بتحقيقها من التحول الرقمي."],
  ["5.1.1", "التخطيط الاستراتيجي للتحول الرقمي", "الهدف: تطوير خطة إستراتيجية للتحول الرقمي متوائمة مع إستراتيجية الجهة ورؤية السعودية (2030).\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• قرار مجلس الوزراء رقم (40) وتاريخ 27/2/1427 هـ، البند (16).", "1) إرفاق الخطة الإستراتيجية المعتمدة للتحول الرقمي، التي تتضمن جميع متطلبات تطبيق المعيار، ويكون تاريخ اعتمادها خلال فترة لا تزيد عن (36) شهرًا."],
  ["5.1.1-1", "إعداد إستراتيجية للتحول الرقمي/ للتحول للتعاملات الإلكترونية الحكومية، بحيث تشمل ما يأتي:", "أ. رؤية ورسالة وركائز وأهداف إستراتيجية وربطها بإستراتيجية الجهة.\nب. المبادرات والمشاريع الإستراتيجية ومؤشرات الأداء الإستراتيجية.\nت. نموذج تحقيق التكامل مع الجهات الخارجية ذات العلاقة، لتحقيق المستهدفات.\nث. الكفاءات والقدرات والمهارات اللازمة، لتحقيق مستهدفات الخطة."],
  ["5.1.2", "التخطيط التنفيذي للتحول الرقمي", "الهدف: تطوير خطة تنفيذية للتحول الرقمي وفق أفضل الممارسات بناء على الخطة الإستراتيجية للتحول الرقمي للجهة، وتحديد الآليات والجداول الزمنية للتنفيذ والمتابعة.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البندان (1) و(18).\n• قرار مجلس الوزراء رقم (40) وتاريخ 27/2/1427 هـ، البند (16).", "1) إرفاق الخطة التنفيذية المعتمدة للتحول الرقمي، التي تتضمن جميع متطلبات تطبيق المعيار، ويكون تاريخ اعتمادها خلال فترة لا تزيد عن (12) شهرًا."],
  ["5.1.2-1", "إعداد خطة تنفيذية للتحول الرقمي/ للتحول للتعاملات الإلكترونية الحكومية مبنية على الخطة الإستراتيجية بحيث تشمل:", "أ. حصر تفصيلي للمبادرات والمشاريع الخاصة بالتحول الرقمي.\nب. تحديد الجدول الزمني لتنفيذ هذه المبادرات والمشاريع ومراحل التنفيذ.\nت. وضع أهداف مرحلية (تنفيذية).\nث. تحديد مؤشرات الأداء للخطة التنفيذية."],
  ["5.1.3", "تأسيس وحدة لإدارة مشاريع التحول الرقمي", "الهدف: إنشاء وحدة لإدارة مشاريع التحول الرقمي لتحقيق كفاءة المشاريع الرقمية، ومتابعة التقدم في التحول الرقمي.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البنود (1) و(10) و(18).\n• قرار مجلس الوزراء رقم (40) وتاريخ 27/2/1427 هـ، البند (22).", "1) إرفاق وثيقة تثبت أن الجهة أنشأت وحدة لإدارة مشاريع التحول الرقمي.\n2) إرفاق الهيكلية المعتمدة لوحدة إدارة مشاريع التحول الرقمي، بحيث توضح حدود الصلاحيات والمسؤوليات.\n3) إرفاق (3) عينات تثبت أن الجهة لديها منهجية وسياسات وعمليات معتمدة لإدارة المشاريع.\n4) تقديم نسخة حديثة من صفحات التقرير التي تثبت أنَّالجهة قد ضمَّنت تقرير قياس التحول الرقمي في تقريرها السنوي."],
  ["5.1.3-1", "إنشاء وحدة لإدارة مشاريع التحول الرقمي في الجهة."],
  ["5.1.3-2", "وجود هيكلية واضحة لوحدة إدارة مشاريع التحول الرقمي وحدود الصلاحيات والمسؤوليات."],
  ["5.1.3-3", "استخدام منهجية ووضع سياسات وعمليات لإدارة المشاريع."],
  ["5.1.3-4", "متابعة مدى التقدم في التحول الرقمي/ التحول للتعاملات الإلكترونية بشكل دوري، وتضمين النتائج ضمن التقرير السنوي للجهة."],
  ["5.2", "حوكمة التحول الرقمي", "يشمل المحور معايير تطبيق نظام يعمل على حوكمة العلاقات بين الأطراف الرئيسية ومتطلباتها؛ التي تؤثر في الأداء وتحديد المسؤوليات في الجهات الحكومية، كما تضّمن المحور أهم المقومات لتمكين الجهة الحكومية من حوكمة التحول الرقمي على المدى البعيد."],
  ["5.2.1", "اعتماد إطار لحوكمة التحول الرقمي", "الهدف: وضع إطار عام لحوكمة التحول الرقمي يهدف إلى متابعة تنفيذ خطط التحول الرقمي وضمان تحقيق المستهدفات.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البند (11).\n• تعميم الديوان الملكي رقم (58071) وتاريخ 9/8/1445 هـ، البند (رابعًا).\n• الأمر السامي رقـم (8189/م ب) وتاريـخ 19/6/1426 هـ.\n• الأمر السامي رقم (7732) وتاريخ 12/2/1440 هـ.، البند (رابعًا).\n• قرار مجلس الوزراء رقم (240) وتاريخ 23/7/1428 هـ، الفقرات (أولًا) و(ثانيًا) و(ثالثًا).\n• قرار مجلس الوزراء رقم (40) وتاريخ 27/2/1427 هـ، البند (17).\n• قرار مجلس الوزراء رقم (252) وتاريخ 16/7/1431 هـ،الفقرة (ثانيًا).\n• تعميم هيئة الحكومة الرقمية رقم (1189) وتاريخ 13/4/1446هـ.", "1) إرفاق إطار حوكمة التحول الرقمي معتمد، بحيث يغطي جميع المبادرات والعمليات المتعلقة بالتحول الرقمي.\n2) إرفاق وثيقة آلية المتابعة والقياس، ونماذج حديثة للتقارير الدورية وفق متطلبات تطبيق هذا المعيار.\n3) إرفاق ما يثبت تحديد الجهة للإدارات واللجان المسؤولة عن عمليات الحوكمة وعمليات التغيير، بما في ذلك حوكمة وإدارة المنتجات والخدمات المشتركة.\n4) إرفاق الهيكل التنظيمي للجهة، يوضح توحيد الإدارات المشرفة على تقنية المعلومات تحت إدارة عامة واحدة مرتبطة بالمسؤول الأول أو من ينيبه، وقرار تعيين مدير عام لهذه الوحدة أو إفادة من نظام إدارة الموارد المؤسسية تفيد بتعيين كفاءة سعودية في هذا المنصب.\n5) إرفاق الأوصاف الوظيفية المعتمدة لمنسوبي إدارة تقنية المعلومات متضمنة الوصف الوظيفي للمسؤول الأول عن تقنية المعلومات.\n6) تقديم قرار تشكيل لجنة داخلية معنية بكل ما يتعلق بالتعاملات الإلكترونية الحكومية أو التحول الرقمي وفق متطلبات تطبيق هذا المعيار."],
  ["5.2.1-1", "وضع إطار لحوكمة التحول الرقمي يغطي جميع المبادرات والعمليات المتعلقة بالتحول الرقمي."],
  ["5.2.1-2", "تحديد آلية المتابعة والقياس، ونماذج التقارير الدورية، التي سُيقاس عن طريقها التقدم في عمليات تنفيذ مبادرات ومشاريع التحول الرقمي."],
  ["5.2.1-3", "تحديد الإدارات واللجان المسؤولة عن عمليات الحوكمة وعمليات التغيير، بما في ذلك حوكمة وإدارة المنتجات والخدمات المشتركة."],
  ["5.2.1-4", "توحيد الإدارات المشرفة على تقنية المعلومات تحت إدارة عامة بمسمى الإدارة العامة لتقنية المعلومات ومرتبطة بالمسؤول الأول أو من ينيبه، وتخصيص منصب مدير عام يُراَعى فيه التأهيل المناسب."],
  ["5.2.1-5", "تحديد وتوثيق الأدوار والمسؤوليات لكافة المستويات الوظيفية المتعلقة بتقنية المعلومات بما يشمل المسؤول الأول عن تقنية المعلومات."],
  ["5.2.1-6", "تكوين لجنة التعاملات الإلكترونية/ التحول الرقمي برئاسة المسؤول الأول بالجهة أو من ينيبه وعضوية الإدارات/ الوكالات ذات العلاقة، وتوضيح المناصب الإدارية لأعضاء اللجنة وعضوية المسؤول الأول عن كل إدارة معنية بالتعاملات الإلكترونية الحكومية، والمسؤول الأول عن تقنية المعلومات والتطوير الإداري، على أن تشمل في مهامها الإشراف على تنفيذ خطة التعاملات الإلكترونية الحكومية الخاصة بها، ومتابعتها، والتنسيق مـع الهيئة في هذا الشأن والإشراف على أعمال حوكمة تقنية المعلومات."],
  ["5.2.2", "تطبيق إطار لحوكمة التحول الرقمي", "الهدف: تنفيذ إطار حوكمة التحول الرقمي ومراقبة التقدم في عمليات التنفيذ واتخاذ الإجراءات التصحيحية اللازمة.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البند (10).\n• تعميم الديوان الملكي رقم (58071) وتاريخ 9/8/1445 هـ، البند (رابعًا).", "1) (3) عينات من بطاقات المبادرات الحالية.\n2) (3) عينات حديثة من تقارير الأداء الدورية.\n3) (3) عينات حديثة من محاضر الاجتماعات.\n4) (3) عينات حديثة من القرارات والإجراءات التصحيحية.\n5) (3) عينات حديثة توضح استخدام النماذج الخاصة بإدارة المشاريع، التي تحقق متطلبات تطبيق هذا المعيار."],
  ["5.2.2-1", "وضع بطاقة لكل مبادرة من مبادرات التحول الرقمي."],
  ["5.2.2-2", "إصدار تقارير الأداء الدورية لمبادرات ومشاريع التحول الرقمي توضح نسبة الإنجاز في مراحل التنفيذ."],
  ["5.2.2-3", "عقد اجتماعات دورية للإدارات واللجان المسؤولة عن مراقبة وحوكمة التحول الرقمي."],
  ["5.2.2-4", "إصدار قرارات وإجراءات تصحيحية بناًء على نتائج التقارير الدورية للمتابعة والحوكمة."],
  ["5.2.2-5", "استخدام نماذج خاصة بإدارة مشاريع التحول الرقمي تتضمن بحد أدنى ما يأتي:", "أ. ميثاق المشروع.\nب. نطاق المشروع.\nت. الجدول الزمني للمشروع.\nث. خطة تكلفة المشروع.\nج. تقرير تقدم المشروع. إرفاق الوثائق والعينات من إدارات/وحدات مختلفة التي تثبت التزام الجهة بمتطلبات تطبيق هذا المعيار بحيث تشمل:"],
  ["5.2.3", "تعزيز التعاون في مجال حوكمة التحول الرقمي", "الهدف: تطبيق آليات لحوكمة المبادرات والمشاريع المشتركة بين الجهات، لتحقيق المستهدفات في التحول الرقمي ومراقبة التقدم في عمليات التنفيذ واتخاذ الإجراءات التصحيحية اللازمة.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (58071) وتاريخ 9/8/1445 هـ، البند (سابعًا).", "1) إرفاق وثيقة آلية الحوكمة المشتركة، وفق متطلبات تطبيق هذا المعيار.\n2) إرفاق عينة من قرارات تشكيل اللجان المشتركة.\n3) إرفاق (3) عينات حديثة من تقارير متابعة الأداء الدورية، توضح مدى التقدم في تنفيذ التعاون مع الجهات الحكومية المستهدفة.\n4) إرفاق (3) عينات حديثة من محاضر الاجتماعات."],
  ["5.2.3-1", "الاتفاق على آلية مشتركة لحوكمة مبادرات ومشاريع التحول الرقمي والمنتجات المشتركة بين الجهات الحكومية، بحيث توضح الآلية الجهات المستهدفة، ونوع التعاون المطلوب وأهدافه، والجدول الزمني لمراحل التنفيذ."],
  ["5.2.3-2", "تشكيل اللجان المشتركة اللازمة لمتابعة عمليات حوكمة المشاريع والمبادرات المشتركة."],
  ["5.2.3-3", "إصدار تقارير متابعة الأداء الدورية للمبادرات والمشاريع المشتركة توضح مدى التقدم في تنفيذ التعاون مع الجهات الحكومية المستهدفة."],
  ["5.2.3-4", "عقد اجتماعات دورية للجان المشتركة المسؤولة عن مراقبة وحوكمة المبادرات والمشاريع المشتركة."],
  ["5.3", "البنية المؤسسية", "يشمل المحور ممارسات وضوابط لدراسة الوضع الحالي للجهة الحكومية، وبناء خارطة الطريق للتحول إلى الوضع المستقبلي، لتحقيق المواءمة بين الأعمال (الخدمات والإجراءات)، وتقنية المعلومات (البيانات، والتطبيقات، والبنية التحتية)، والأهداف الإستراتيجية للجهة الحكومية."],
  ["5.3.1", "تأسيس وحدة تنظيمية للبنية المؤسسية", "الهدف: تأسيس وحدة تنظيمية داخل الجهة تختص بإدارة أعمال وممارسات البنية المؤسسية وتطويرها والإشراف عليها، لدعم تحقيق الأهداف الإستراتيجية والتحول الرقمي.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البند (9).", "1) وثيقة معتمدة تثبت تأسيس وحدة تنظيمية خاصة بالبنية المؤسسية، أو الهيكل التنظيمي المعتمد للجهة الذي يوضح تأسيس الوحدة التنظيمية.\n2) وثيقة معتمدة توضح أهداف البنية المؤسسية متوائمة مع إستراتيجية الأعمال وإستراتيجية التحول الرقمي.\n3) وثيقة معتمدة تثبت تشكيل فريق عمل الوحدة التنظيمية، وتوضيح الأدوار والمسؤوليات والمهارات التخصصية لكل مجال وفق متطلبات تطبيق هذا المعيار.\n4) دليل الخدمات والإجراءات لوحدة البنية المؤسسية.\n5) وثيقة معتمدة لنموذج التفاعل بين وحدة البنية المؤسسية والوحدات الإدارية/ التنظيمية الأخرى للجهة.\n6) وثيقة معتمدة تثبت تشكيل لجنة لحوكمة البنية المؤسسية وآلية عملها، وتضمين ممثلي الوحدات التنظيمية ذات العلاقة."],
  ["5.3.1-1", "تأسيس وحدة تنظيمية ضمن الهيكل التنظيمي للجهة على أن تتولى مهام ومسؤوليات الإدارة والتطوير والإشراف على أعمال وممارسات البنية المؤسسية."],
  ["5.3.1-2", "بناء أهداف البنية المؤسسية بالمواءمة مع إستراتيجية الأعمال وإستراتيجية التحول الرقمي."],
  ["5.3.1-3", "تشكيل فريق عمل الوحدة التنظيمية، وتوثيق الأدوار والمسؤوليات، على أن تُغّطى مجالات البنية المؤسسية الأساسية (الأعمال، والتطبيقات، والبيانات، والتقنية)، وتحديد المهارات التخصصية لكل مجال."],
  ["5.3.1-4", "تحديد خدمات الوحدة التنظيمية للبنية المؤسسية، وبناء دليل إجراءات عمل ممارسة البنية المؤسسية."],
  ["5.3.1-5", "إعداد أو تبني نموذج لتفاعل الوحدة التنظيمية للبنية المؤسسية مع الوحدات الإدارية/ التنظيمية الأخرى."],
  ["5.3.1-6", "تشكيل لجنة لحوكمة البنية المؤسسية، وتضمين ممثلي الوحدات التنظيمية ذات العلاقة. وثيقة شهادة الاعتماد في حال حصول الجهة على شهادة اعتماد البنية المؤسسية الوطنية (المستوى الثالث أو الرابع أو الخامس) خلال مدة لا تزيد عن سنتين من تاريخ صدورها، ويمكن قبول الشهادة كمستند إثبات بحد أقصى خلال (ثلاثة) أشهر من تاريخ نهايتها. في حال عدم توفر شهادة اعتماد البنية المؤسسية الوطنية يتوجب على الجهة تقديم الآتي:"],
  ["5.3.2", "تطبيق ممارسة البنية المؤسسية", "الهدف: تطبيق ممارسة البنية المؤسسية وتعزيز العمل المؤسسي عن طريق الاستفادة من منهجيات البنية المؤسسية في عملية التحول الرقمي.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البند (9).\n• تعميم الديوان الملكي رقم (58071) وتاريخ 9/8/1445 هـ، البند (ثالثًا).", "1) ميثاق دورة تطوير البنية المؤسسية المعتمد وفق متطلبات تطبيق هذا المعيار.\n2) وثيقة مبادئ البنية المؤسسية بجميع مجالاتها متضمنة مبررات تطبيق المبادئ والتبعات المترتبة على ذلك.\n3) وثيقة النموذج العام لمكونات البنية المؤسسية وفق متطلبات تطبيق هذا المعيار.\n4) وثيقة مناظير البنية المؤسسية، وفق متطلبات تطبيق هذا المعيار.\n5) سجل متطلبات البنية المؤسسية الصادرة عن الوحدات التنظيمية ذات العلاقة، بحيث يوضح متابعة حالة المتطلبات من وقت إنشائها إلى إغلاقها.\n6) وثائق الوضع الحالي لبنية الأعمال وبنية التطبيقات وبنية البيانات والبنية التقنية في الجهة وفق متطلبات تطبيق هذا المعيار.\n7) وثائق الوضع المستقبلي لبنية الأعمال وبنية التطبيقات وبنية البيانات والبنية التقنية وفق متطلبات تطبيق هذا المعيار.\n8) وثيقة تحليل الفجوات بين الوضع الحالي والمستقبلي.\n9) وثيقة خارطة طريق التحول الرقمي في الجهة وفق متطلبات تطبيق هذا المعيار."],
  ["5.3.2-1", "تطبيق دورة تطوير مكونات البنية المؤسسية وفق المنهجية الوطنية للبنية المؤسسية (NORA)، بما يتضمن تحديد نطاق دورة التطوير، والمراحل التي سُتتَبع، وقائمة بأصحاب العلاقة، والمجالات، ووحدات البناء، والمناظير المشمولة ضمن نطاق الدورة."],
  ["5.3.2-2", "تحديد المبادئ المرتبطة بمجالات البنية المؤسسية التي تضمن كفاءة توثيق وتطوير مكونات ومناظير مجالات البنية المؤسسية بما يتواءم مع توجهات الجهة ومستهدفاتها الإستراتيجية والتوجهات الوطنية مع تفصيل مبررات تطبيق المبادئ والتبعات المترتبة على ذلك."],
  ["5.3.2-3", "إعداد وثيقة النموذج العام لمكونات البنية المؤسسية، بحيث تكون متوائمة مع أعمال الجهة ومستهدفاتها، تشمل تعريف وحدات البناء، وسمات كل وحدة بناء، والعلاقات الخاصة بينها."],
  ["5.3.2-4", "تطوير مناظير البنية المؤسسية بأنواعها المختلفة (قائمة، ومصفوفة، ورسم مرئي)، بحيث تغطي هذه المناظير مختلف مجالات البنية المؤسسية وفقًا للنموذج العام عبر تحليل احتياجات أصحاب العلاقة، وتحديد الهدف من المنظور، ومستوى التفصيل."],
  ["5.3.2-5", "بناء سجل متطلبات البنية المؤسسية الصادرة عن الوحدات التنظيمية ذات العلاقة، ومتابعة حالة المتطلبات من وقت نشأتها إلى إغلاقها."],
  ["5.3.2-6", "توثيق الوضع الحالي لبنية الأعمال وبنية التطبيقات وبنية البيانات والبنية التقنية في الجهة، ومستوى التوثيق المطلوب (مستوى مفاهيمي، ومستوى منطقي، ومستوى فيزيائي)."],
  ["5.3.2-7", "تطوير وثائق الوضع المستقبلي لبنية الأعمال وبنية التطبيقات وبنية البيانات والبنية التقنية في الجهة بناًء على الأهداف الإستراتيجية للتحول الرقمي للجهة، وبالاستفادة من المرجعيات العالمية الملائمة لطبيعة عمل الجهة والخدمات التي تقِّدمها."],
  ["5.3.2-8", "دراسة الفجوات بين الوضع المستقبلي المستهدف الوصول إليه والوضع الراهن للبنية المؤسسية."],
  ["5.3.2-9", "تطوير خارطة طريق للتحول الرقمي تتضمن مجموعة المبادرات والمشاريع اللازمة لسد الفجوات، وتحقيق مستهدفات الوضع المستقبلي للبنية المؤسسية، بحيث تتضمن النقاط التالية:", "أ. البطاقات التفصيلية للمبادرات والمشاريع.\nب. تحديد أولويات تنفيذ المبادرات والمشاريع وفق معايير معينة.\nت. مؤشرات الأداء التي يتم من خلالها تقييم التقدم في عمليات التنفيذ.\nث. الجدول الزمني لعملية التنفيذ.\nج. آليات المتابعة والقياس لمؤشرات الأداء. وثيقة شهادة الاعتماد في حال حصول الجهة على شهادة اعتماد البنية المؤسسية الوطنية (المستوى الثالث أو الرابع أو الخامس) خلال مدة لا تزيد عن سنتين من تاريخ صدورها، ويمكن قبول الشهادة كمستند إثبات بحد أقصى خلال (ثلاثة) أشهر من تاريخ نهايتها. في حال عدم توفر شهادة اعتماد البنية المؤسسية الوطنية يتوجب على الجهة تقديم الآتي:"],
  ["5.3.3", "تفعيل وحوكمة البنية المؤسسية", "الهدف: تفعيل وحوكمة أعمال البنية المؤسسية لضمان نجاح جهود إدارة وتنفيذ ممارسات وأعمال البنية المؤسسية في الجهة.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (58071) وتاريخ 9/8/1445 هـ، البند (ثالثًا).", "1) سياسة تبني وحوكمة ممارسة البنية المؤسسية وفق متطلبات تطبيق هذا المعيار.\n2) عينات كافية من نماذج معدة لدراسة الامتثال، محاضر اجتماعات تنفيذ وانعقاد جلسات المراجعة للمشاريع والمبادرات الرقمية، تقارير توثيق نتائج التحليل والتوصيات (والإعفاءات إن وُِجدت).\n3) (3) عينات من أداة البنية المؤسسية تثبت عكس النموذج العام ومكونات الممارسة ووجود لوحات أداء.\n4) (3) عينات من أداة البنية المؤسسية تثبت نسبة حصر وعكس مكونات البنية المؤسسية على الأداة.\n5) تقرير يوضح تتبع نسبة الإنجاز على مبادرات ومشاريع خارطة التحول الرقمي.\n6) (3) عينات حديثة من محاضر ووثائق رسمية توضح عقد اللجان بشكل دوري خلال العام، واتخاذ القرارات والإجراءات الوقائية والتصحيحية اللازمة."],
  ["5.3.3-1", "تطوير سياسة ممكنة لتبني وحوكمة ممارسة البنية المؤسسية، مع مراعاة شموليتها ووضوح صياغتها وطريقة عرضها على أن تتضمن السياسة المواضيع الآتية:", "أ. حوكمة ممارسة البنية المؤسسية.\nب. إدارة متطلبات البنية المؤسسية.\nت. تبني مخرجات البنية المؤسسية.\nث. امتثال المبادرات والمشاريع لمبادئ البنية المؤسسية."],
  ["5.3.3-2", "التحقق من امتثال المبادرات والمشاريع الإستراتيجية ذات العلاقة بالبنية المؤسسية المعرفة من قِبل الوحدات التنظيمية الأخرى مع مبادئ البنية المؤسسية."],
  ["5.3.3-3", "توفير وتهيئة أداة البنية المؤسسية وعكس النموذج العام للمكونات على الأداة."],
  ["5.3.3-4", "متابعة مكونات البنية المؤسسية والعمل على تحديثها بشكل مستمر على الأداة."],
  ["5.3.3-5", "متابعة تنفيذ مبادرات ومشاريع التحول الرقمي بالمواءمة مع الإدارات المعنية."],
  ["5.3.3-6", "تفعيل العمل بمهام أعضاء لجنة حوكمة البنية المؤسسية مدة سنة واحدة على الأقل بدءًا من تاريخ تشكيل اللجنة، واتخاذ القرارات والإجراءات الوقائية والتصحيحية اللازمة. وثيقة شهادة الاعتماد في حال حصول الجهة على شهادة اعتماد البنية المؤسسية الوطنية (المستوى الثالث أو الرابع أو الخامس) خلال مدة لا تزيد عن سنتين من تاريخ صدورها، ويمكن قبول الشهادة كمستند إثبات بحد أقصى خلال (ثلاثة) أشهر من تاريخ نهايتها. في حال عدم توفر شهادة اعتماد البنية المؤسسية الوطنية يتوجب على الجهة تقديم التالي:"],
  ["5.3.4", "تعزيز دور البنية المؤسسية في التحول الرقمي وقياس الأثر", "الهدف: تعزيز دور وحدة البنية المؤسسية في استدامة التحول الرقمي والمشاركة في التخطيط المالي وتحقيق الأهداف الاستراتيجية.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (58071) وتاريخ 9/8/1445 هـ، البند (ثالثًا).", "1) تقارير دورية لمؤشرات الأداء التشغيلية لآخر ربعين، وفق متطلبات تطبيق هذا المعيار.\n2) تقرير يوضح دراسة حالات استخدم التقنيات الحديثة والناشئة، وفق متطلبات تطبيق هذا المعيار.\n3) تقرير دوري من قَِبل الوحدة التنظيمية المسؤولة عن البنية المؤسسية، يوضح نتائج قياس الأثر من تطبيق ممارسة البنية المؤسسية، وفق متطلبات تطبيق هذا المعيار.\n4) صور حديثة من الشاشات التي توضح الربط التقني بين مستودع البنية المؤسسية المفعلة في الجهة مع الأدوات والمنصات الرقمية، وفق متطلبات تطبيق هذا المعيار."],
  ["5.3.4-1", "إصدار التقارير الدورية لنتائج مؤشرات الأداء التشغيلية لأعمال وخدمات البنية المؤسسية."],
  ["5.3.4-2", "إعداد تقرير يوضح دراسة حالات استخدم التقنيات الحديثة والناشئة وتضمينها في مشاريع خارطة التحول الرقمي."],
  ["5.3.4-3", "إعداد تقرير دوري من قَِبل الوحدة التنظيمية المسؤولة عن البنية المؤسسية، يوضح نتائج قياس الأثر من تطبيق ممارسة البنية المؤسسية على المستوى :الاستراتيجي والمالي والتحول الرقمي."],
  ["5.3.4-4", "تنفيذ الربط التقني بين أداة البنية المؤسسية المفعلة في الجهة مع الأدوات والمنصات الرقمية التي يمكن أن تغذي الأداة بمعلومات وحدات البناء لمجالات البنية المؤسسية. وثيقة شهادة الاعتماد في حال حصول الجهة على شهادة اعتماد البنية المؤسسية الوطنية (المستوى الثالث أو الرابع أو الخامس) خلال مدة لا تزيد على سنتين من تاريخ صدورها، ويمكن قبول الشهادة كمستند إثبات بحد أقصى خلال (ثلاثة) أشهر من تاريخ نهايتها. في حال عدم توفر شهادة اعتماد البنية المؤسسية الوطنية يتوجب على الجهة تقديم الآتي:"],
  ["P2", "المنظمة والثقافة"],
  ["5.4", "الثقافة والبيئة الرقمية", "يتضّمن المحور الممارسات والبرامج التي ترفع مستوى الإلمام بمفاهيم التحول الرقمي، وتبّنيها في الجهة الحكومية؛ للمساهمة في تعزيز الثقافة الرقمية لدى المنسوبين."],
  ["5.4.1", "إعداد الدراسات والبرامج الخاصة بتعزيز الثقافة والبيئة الرقمية", "الهدف: تحديد مستوى الوعي لدى منسوبي الجهات الحكومية بعملية التحول الرقمي، وإعداد الدراسات والبرامج اللازمة لزيادة هذا الوعي.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البند (3).\n• قرار مجلس الوزراء رقم (555) وتاريخ 23/9/1440 هـ، الفقرات (1-4) من البند (تاسعًا).", "1) إرفاق دراسة حديثة لتحديد مستوى وعي منسوبي الجهة بالتحول الرقمي وفق متطلبات تطبيق هذا المعيار.\n2) إرفاق وثيقة حديثة توضح البرامج التوعوية التي أعدتها الجهة، لزيادة وعي منسوبيها بالتحول الرقمي، وفق متطلبات تطبيق هذا المعيار."],
  ["5.4.1-1", "إعداد دراسة لتحديد مستوى وعي منسوبي الجهة بالتحول الرقمي ومدى أهميته، ومجالات التحول الرقمي،ثمَّتحديد الفجوات في هذا الصدد على مختلف المستويات في الجهة."],
  ["5.4.1-2", "إعداد برامج توعوية لمنسوبي الجهة الحكومية بأهمية عمليات التحول الرقمي بحيث تشمل:", "أ. تحديد الفئات المستهدفة والمستهدفات لزيادة الوعي بالتحول الرقمي من منسوبي الجهة بمختلف الوحدات والمستويات الإدارية.\nب. اختيار الوسائل والقنوات التي سُتستخدم في برامج زيادة الوعي بالتحول الرقمي والجدول الزمني لتنفيذ هذه البرامج."],
  ["5.4.2", "تنفيذ برامج رفع الوعي بالتحول الرقمي وقياس أثرها وتحسينها", "الهدف: تنفيذ البرامج المعتمدة لزيادة وعي منسوبي الجهة بعملية التحول الرقمي والعمل على قياس الأثر المترتب على تنفيذ هذه البرامج.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البندان (2)،(3).\n• قرار مجلس الوزراء رقم (40) وتاريخ 27/2/1427 هـ، البند (16).\n• قرار مجلس الوزراء رقم (555) وتاريخ 23/9/1440 هـ، الفقرة (4) من البند (تاسعًا).", "1) إرفاق التقارير والعينات الحديثة التي تثبت توعية منسوبي الجهة بأهمية التحول الرقمي حسب البرامج التوعوية المعتمدة، وفق متطلبات تطبيق هذا المعيار.\n2) إرفاق عينات من الآليات المعتمدة التي تثبت توعية منسوبي الجهة بضرورة الالتزام بالأنظمة واللوائح ذات العلاقة بضوابط استخدام تقنية المعلومات والاتصالات.\n3) إرفاق التقارير والعينات الحديثة التي تثبت مشاركة القادة في الأنشطة التوعوية.\n4) إرفاق عينات حديثة من تقارير الإنجاز ومحاضر اللجان والقرارات التصحيحية المتعلقة ببرامج رفع الوعي بالتحول الرقمي، وفق متطلبات تطبيق هذا المعيار."],
  ["5.4.2-1", "تنفيذ البرامج التوعوية لمنسوبي الجهة الحكومية بأهمية عمليات التحول الرقمي واطلاعهم على خطط ومبادرات التحول الرقمي ونسب إنجازها عبر القنوات المختلفة، وإقامة الأنشطة والفعاليات اللازمة لذلك."],
  ["5.4.2-2", "وضع الآليات المناسبة لضمان توعية منسوبي الجهة بضرورة الالتزام بالأنظمة واللوائح ذات العلاقة بضوابط استخدام تقنية المعلومات والاتصالات."],
  ["5.4.2-3", "تنفيذ أنشطة توعوية يشارك فيها القادة، تهدف إلى زيادة تبني المنسوبين لعملية التحول الرقمي والمساهمة الفاعلة."],
  ["5.4.2-4", "إعداد تقارير دورية عن الأنشطة والفعاليات المنفذة، لزيادة الوعي ومتابعتها من قَِبل لجنة التعاملات الإلكترونية الحكومية –لجنة التحول الرقمي– في الجهة أو مَن ينوب عنهم من لجان أخرى، واتخاذ الإجراءات التصحيحية."],
  ["5.4.3", "استخدام الأدوات التقنية المساعدة في أداء أعمال الجهة", "الهدف: تعزيز تبِّني الأدوات التقنية، لتحسين أعمال منسوبي الجهة اليومية أو الاعتيادية.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• قرار مجلس الوزراء رقم (555) وتاريخ 23/9/1440 هـ، الفقرة (1) من البند (تاسعًا).", "1) إرفاق آلية طلبات المنسوبين لأي برمجيات أو رخص داعمة للأدوات الرقمية، وصور من الشاشات التي تثبت تطبيق هذه الآلية.\n2) إرفاق صور وتقارير إنجاز حديثة للورش والدورات وما يثبت تهيئة المنسوبين على استخدام هذه الأدوات الرقمية."],
  ["5.4.3-1", "توفير آلية لطلبات المنسوبين لأي برمجيات أو رخص داعمة للأدوات الرقمية التي يستخدمها منسوبو الجهة في أعمالهم اليومية."],
  ["5.4.3-2", "تنظيم ورش تدريبية أو دورات قصيرة لمنسوبي الجهة على استخدام هذه الأدوات الرقمية."],
  ["5.5", "تطوير قيادات التحول الرقمي", "يشمل المحور مفهوم تطوير المهارات القيادية والتنفيذية في مجال التحول الرقمي؛ بما يعّزز الممّكنات البشرية والتقنية والعملياتية للجهة الحكومية."],
  ["5.5.1", "التخطيط لتأهيل قيادات التحول الرقمي", "الهدف: تأهيل قيادات التحول الرقمي، وبناء قدرات قيادية في الجهة الحكومية.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البند (2).\n• قرار مجلس الوزراء رقم (555) وتاريخ 23/9/1440 هـ، الفقرتان (1) و(3) من البند (تاسعًا).\n• قرار مجلس الوزراء رقم (418) وتاريخ 25/7/1442 هـ، الفقرة (11) من المادة (الرابعة).", "1) إرفاق الدراسة التحليلية للوضع الراهن وفق متطلبات تطبيق هذا المعيار.\n2) إرفاق وثيقة خطة تطوير قيادات التحول الرقمي في الجهة، ورفع مستواهم في مجالات أعمال الحكومة الرقمية وفق متطلبات تطبيق هذا المعيار."],
  ["5.5.1-1", "إعداد دراسة تحليلية للوضع الراهن، وتحديد الاحتياجات التدريبية لقيادات التحول الرقمي في الجهة، والاحتياجات من الكفاءات القيادية الرقمية والكفاءات الوطنية المتخصصة في مجالات أعمال الحكومة الرقمية."],
  ["5.5.1-2", "إعداد خطة حديثة لتطوير قيادات التحول الرقمي في الجهة، ورفع مستواهم في مجالات أعمال الحكومة الرقمية بحيث تشمل ما يأتي:", "أ. تحديد البرامج والدورات والأنشطة اللازمة لتطوير قيادات التحول الرقمي، بحيث تكون هذه البرامج ذات طابع نظري وتطبيقي ميداني وطويلة الأمد.\nب. وضع معايير ومنهجية لاختيار قادة التحول الرقمي لتأهيلهم، وتشمل القيادات المستقبلية للاستثمار بتأهيلها للمستقبل، وتكون القيادات من مختلف القطاعات والإدارات والأقسام والمجالات لدعم التحول الرقمي، ولا تقتصر فقط على إدارات تقنية المعلومات.\nت. تحديد أسماء قيادات التحول الرقمي المشاركين في هذه البرامج والأنشطة ومراكزهم.\nث. وضع الجدول الزمني لتنفيذ هذه البرامج."],
  ["5.5.2", "تنفيذ ومتابعة خطة تأهيل قيادات التحول الرقمي", "الهدف: تنفيذ خطة تأهيل قيادات التحول الرقمي بما يضمن تحقيق مستهدفاتها وقياس الأثر منها.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البند (2).\n• قرار مجلس الوزراء رقم (555) وتاريخ 23/9/1440 هـ، الفقرة (3) من البند (تاسعًا).", "1) إرفاق الآلية المعتمدة لمتابعة وقياس الأثر لبرامج تأهيل قيادات التحول الرقمي، ونماذج تقارير المتابعة الدورية، وتشمل قائمة البرامج التدريبية المنفذة و(3) عينات حديثة من الدعوات المرسلة للمشاركين و(3) عينات حديثة من الشهادات.\n2) إرفاق عينات حديثة من تقارير المتابعة الدورية، لتنفيذ خطة تأهيل قيادات التحول الرقمي.\n3) إرفاق الدراسة التحليلية لتقارير المتابعة الدورية وعينات حديثة من المحاضر التي تثبت متابعة لجنة التعاملات الإلكترونية الحكومية -لجنة التحول الرقمي- التنفيذ واتخاذ القرارات التصحيحية."],
  ["5.5.2-1", "تحديد واعتماد آلية للمتابعة والقياس وإعداد نماذج تقارير المتابعة الدورية للخطة على أن تشمل ما يأتي:", "أ. قائمة تفصيلية بالبرامج التدريبية المعتمدة المنفَّذة (الجهات المقدَّمة وتواريخ التنفيذ).\nب. شهادات الدورات التدريبية."],
  ["5.5.2-2", "إصدار تقارير المتابعة الدورية للخطة من قبل لجنة التعاملات الإلكترونية الحكومية -لجنة التحول الرقمي- في الجهة أو من ينوب عنهم من لجان أخرى."],
  ["5.5.2-3", "دراسة التقارير الدورية وتحليلها وإصدار قرارات وإجراءات تصحيحية بناًء على نتائج التقارير الدورية للمتابعة."],
  ["5.5.3", "إشراك قيادات التحول الرقمي", "الهدف: إشراك القادة المؤهلين في عملية التحول الرقمي وتحفيزهم لاتخاذ القرارات في الجهة بصورة فعّالة.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البندان (1) و(18).\n• قرار مجلس الوزراء رقم (555) وتاريخ 23/9/1440 هـ، البند (تاسعًا).", "1) إرفاق عينات حديثة من قرارات تكوين اللجان الفاعلة في عملية التحول الرقمي مع تحديد أسماء الأعضاء من القادة المؤهلين والمشاركين في دعم التحول الرقمي.\n2) إرفاق (3) عينات من التقارير الدورية الصادرة من الأدوات الرقمية المخصصة لدعم القادة تقيس تنفيذ المبادرات الإستراتيجية في التحول الرقمي.\n3) إرفاق (3) عينات من تحليل التقارير الدورية، ومحاضر الإجتماعات أو القرارات أو التعاميم التي توضح استخدام نتائج التحليل في دعم القرارات القيادية."],
  ["5.5.3-1", "إشراك القادة المؤهلين في مجال التحول الرقمي في اللجان الفاعلة في عملية التحول الرقمي وعمليات صنع القرار، والاستفادة من خبراتهم ومؤهلاتهم في تنفيذ المبادرات الإستراتيجية في التحول الرقمي."],
  ["5.5.3-2", "استخدام الأدوات الرقمية لتوفير تقارير دورية تُمّكن القادة من متابعة تنفيذ المبادرات الإستراتيجية في التحول الرقمي."],
  ["5.5.3-3", "تحليل التقارير الدورية، واستخدام نتائج التحليل في دعم القرارات القيادية."],
  ["5.5.4", "التعاون والاستقطاب على مستوى قيادات التحول الرقمي", "الهدف: تفعيل تبادل الخبرات بين القيادات داخل الجهة أو مع الجهات الخارجية، واستقطاب الكفاءات الوطنية المتخصصة في مجالات أعمال الحكومة الرقمية.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البند (2).\n• قرار مجلس الوزراء رقم (555) وتاريخ 23/9/1440 هـ، الفقرتان (1) و(3) من البند (تاسعًا).", "1) إرفاق قائمة حديثة بأسماء القيادات التي جرى استقطابهم/ إعارتهم من/ إلى جهات أخرى.\n2) إرفاق عينات حديثة من ورش العمل والمؤتمرات التي أُقيمت مع جهات حكومية أخرى."],
  ["5.5.4-1", "استقطاب الكفاءات الوطنية المتخصصة لسد الاحتياج من الكفاءات القيادية الرقمية، أو مشاركة القيادات المتميزة في جهات أخرى كالندب والإعارة."],
  ["5.5.4-2", "عقد ورش عمل ومؤتمرات لقيادات التحول الرقمي على مستوى الجهة أو مع الجهات الخارجية الأخرى."],
  ["5.6", "بناء الكفاءات", "يتضّمن المحور معايير ومتطلبات تطوير عملية بناء القدرات والكفاءات البشرية ومنح القوى العاملة القدرة على التعامل مع التقنيات والحلول الرقمية؛ التي تعّزز لديهم قدرات الابتكار لتطوير المهام والأعمال والخدمات باستخدام أحدث الحلول الرقمية والتقنيات."],
  ["5.6.1", "إعداد خطة لبناء الكفاءات في مجالات التحول الرقمي", "الهدف: تعزيز الكفاءات في الجهات الحكومية في مجال التحول الرقمي عن طريق تطوير قدرات منسوبيها في المستويات الوظيفية المتوسطة والدنيا أو عبر استقطاب الكفاءات اللازمة.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البند (2).\n• قرار مجلس الوزراء رقم (555) وتاريخ 23/9/1440 هـ، الفقرتان (1) و(3) من البند (تاسعًا).\n• تعميم هيئة الحكومة الرقمية رقم (1189) وتاريخ 13/4/1446هـ.", "1) إرفاق الدراسة التحليلية للوضع الراهن وفق متطلبات تطبيق هذا المعيار.\n2) إرفاق خطة حديثة لبناء الكفاءات وتطوير مهارات منسوبي الجهة وفق متطلبات تطبيق هذا المعيار."],
  ["5.6.1-1", "إعداد دراسة تحليلية للوضع الراهن لمستويات وقدرات منسوبي الجهة في مجالات أعمال الحكومة الرقمية."],
  ["5.6.1-2", "إعداد خطة بناء الكفاءات لتطوير مهارات منسوبي الجهة، ورفع مستواهم في مجالات أعمال الحكومة الرقمية وتقنية المعلومات وتحديثها دورًّيا بحيث تشمل:", "أ. أهداف خطة بناء الكفاءات بحيث تكون متوائمًة مع إستراتيجية الجهة ومع خطتها للتحول الرقمي.\nب. البرامج والمجالات التدريبية ومستوياتها (أساسية، ومتوسطة، ومتقدمة) علمًا أنَّالدورات القصيرة وورش العمل غير مناسبة في هذا المجال.\nت. المستهدفون من هذه البرامج، وتخصصاتهم الوظيفية، وأعدادهم من موظفي التحول الرقمي وتقنية المعلومات.\nث. الجدول الزمني لهذه البرامج ومؤشرات الأداء."],
  ["5.6.2", "تنفيذ خطة بناء الكفاءات في مجالات التحول الرقمي وقياسها وتحسينها", "الهدف: تنفيذ خطة بناء الكفاءات في مجال التحول الرقمي بما يحقق الأثر المطلوب منها، وقياسها وتحسين هذه البرامج بناًء على التقارير الدورية.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البند (2).\n• قرار مجلس الوزراء رقم (555) وتاريخ 23/9/1440 هـ، الفقرتان (1) و(3) من البند (تاسعًا).", "1) إرفاق عينات من تقارير المتابعة الدورية لتنفيذ خطة بناء الكفاءات في مجال التحول الرقمي، وتشمل قائمًة تفصيليًة بالبرامج التدريبية المنفَّذة و (3) عينات من الشهادات، و (3) عينات من الدعوات المرسلة للمشاركين.\n2) إرفاق الدراسة التحليلية لتقارير المتابعة الدورية وعينات حديثة من المحاضر التي تثبت متابعة لجنة التعاملات الإلكترونية الحكومية -لجنة التحول الرقمي- التنفيذ واتخاذ القرارات التصحيحية."],
  ["5.6.2-1", "إصدار تقارير المتابعة الدورية لتنفيذ خطة بناء الكفاءات في مجال التحول الرقمي من قَِبل لجنة التعاملات الإلكترونية الحكومية –لجنة التحول الرقمي– في الجهة أو من ينوب عنهم من لجان أخرى، على أن تشمل ما يأتي:", "أ. قائمة تفصيلية بالبرامج التدريبية المنفَّذة بحيث تشمل الجهات المقدَّمة وتواريخ التنفيذ، وطريقة التدريب (حضوري أو عن بُعد) والخبرات الموظ فَّة بحسب خطة بناء الكفاءات المعتمدة.\nب. عينات من شهادات البرامج التدريبية، موضحًا بها طبيعة تقديم البرنامج أو الدورة (حضوري أو عن بُعد) والسير الذاتية وإفادة الانتساب للخبرات الموظ فَّة."],
  ["5.6.2-2", "دراسة التقارير الدورية وتحليلها من قَبل لجنة التعاملات الإلكترونية الحكومية -لجنة التحول الرقمي- في الجهة أو من ينوب عنهم من لجان أخرى، وإصدار قرارات وإجراءات تصحيحية بناء على نتائج التقارير الدورية للمتابعة."],
  ["5.6.3", "التعاون في مجال بناء الكفاءات في مجال التحول الرقمي", "الهدف: تفعيل التعاون مع الجهات الحكومية الأخرى، لبناء كفاءات منسوبي الجهة في المستويات الوظيفية المتوسطة والدنيا.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البندان (1) و(18).", "1) إرفاق عينات من مذكرات التفاهم أو اتفاقيات التعاون القائمة مع جهات حكومية أخرى؛ لتحقيق التكامل في إنجاز الجهة لبرامج بناء الكفاءات.\n2) إرفاق عينة من تقارير المتابعة الدورية لبرامج بناء الكفاءات المشتركة، وفق متطلبات تطبيق هذا المعيار."],
  ["5.6.3-1", "توقيع مذكرات تفاهم أو اتفاقيات تعاون مع جهات حكومية أخرى، لتحقيق التكامل في إنجاز الجهة لبرامج بناء الكفاءات."],
  ["5.6.3-2", "إعداد تقارير المتابعة التي توضح البرامج المشتركة المنفَّذة لبناء الكفاءات في مجال التحول الرقمي، وأسماء المتدربين وأماكن وتواريخ التنفيذ، علمًا أّن ورش العمل التعاونية لا تُعّد ضمن البرامج المشتركة."],
  ["P3", "العمليات والتشغيل"],
  ["5.7", "إجراءات العمل", "يشمل المحور معايير ومتطلبات العملية التي يجري عن طريقها تصميم إجراءات العمل والعمليات في الجهة الحكومية وتوثيقها؛ بحيث تنفذ في تسلسل واضح بحسب الأنظمة واللوائح والمسؤوليات المحددة في الهيكل التنظيمي لدى الجهة؛ بهدف تمكين عملية الأتمتة والتحول الرقمي."],
  ["5.7.1", "حصر جميع عمليات وإجراءات العمل", "الهدف: حصر جميع العمليات والإجراءات الخاصة بالجهة الحكومية، وتحديث قوائم الحصر بشكل مستمر.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البنود (1) و(6) و(18).\n• قرار مجلس الوزراء رقم (40) وتاريخ 27/2/1427 هـ، البندان (10) و(11).", "1) إرفاق وثيقة حصر العمليات والاجراءات وفق متطلبات تطبيق هذا المعيار."],
  ["5.7.1-1", "حصر جميع العمليات والإجراءات في الجهة بحيث تشمل بحد أدنى ما يأتي:", "أ. اسم العملية أو الإجراء والوصف الموجز له.\nب. تحديد الإدارة/ الوحدة المالكة للإجراء.\nت. تصنيف كل إجراء (رئيسي، وداعم، وإداري).\nث. تحديد درجة أهمية كل إجراء وفقًا لآلية تضعها الجهة.\nج. تحديد مستوى الأتمتة من خلال أحد المستويات الآتية:(مؤتمت كلًّيا، أو مؤتمت جزئًّيا، أو غير مؤتمت)."],
  ["5.7.2", "توثيق وقياس أداء العمليات والإجراءات", "الهدف: القيام بعمليات التوثيق الشاملة وقياس الأداء للعمليات والإجراءات بصورة فعّالة.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البند (6).\n• قرار مجلس الوزراء رقم (40) وتاريخ 27/2/1427 هـ، البند (10).", "1) إرفاق آلية ترقيم الإصدارات والنسخ المحدثة للعمليات والإجراءات.\n2) إرفاق (3) عينات متنوعة من إدارات مختلفة (خارج عمليات وإجراءات إدارة تقنية المعلومات) لبطاقات توثيق العمليات والإجراءات وفق متطلبات تطبيق هذا المعيار.\n3) إرفاق (3) عينات متنوعة وحديثة من التقارير التي توضح قيام الجهة بقياس مؤشرات الأداء المعتمدة.\n4) إرفاق (3) عينات متنوعة وحديثة من تقارير المتابعة الدورية توضح التحسينات التي تمت على العمليات أو الإجراءات."],
  ["5.7.2-1", "وضع آلية لترقيم الإصدارات والنسخ المحدثة للعمليات والإجراءات."],
  ["5.7.2-2", "توثيق العمليات والاجراءات عن طريق تطوير بطاقات بشكل واضح ودقيق، واعتمادها من المسؤول الأول في الجهة أو من ينوبه بحيث تتضمن هذه البطاقات العناصر الآتية:", "أ. اسم العملية والإجراء.\nب. رمز موحد وفريد للعملية أو الإجراء.\nت. وصف موجز للعملية أو الإجراء.\nث. المسؤول عن العملية أو الإجراء (الجهة/ الإدارة/ القطاع).\nج. تصنيف العملية أو الإجراء (رئيسي، أو إداري، أو داعم).\nح. مستوى الأهمية.\nخ. مخطط تدفق الإجراء يوضح الوظائف والأدوار (BPMN) أو أحد أساليب التوثيق.\nد. مؤشرات الأداء للعملية أو الإجراء على مستوى الأنشطة داخل الإجراء."],
  ["5.7.2-3", "قياس أداء الإجراءات عبر المؤشرات المعتمدة لكل عملية أو إجراء في البطاقة المطوَّرة."],
  ["5.7.2-4", "المتابعة الدورية لأداء الإجراءات وتحديد فرص التحسين."],
  ["5.7.3", "إعادة هندسة العمليات والإجراءات", "الهدف: العمل المستمر على تحسين وتطوير العمليات والإجراءات وإعادة هندستها بما يضمن كفاءة التشغيل.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• قرار مجلس الوزراء رقم (40) وتاريخ 27/2/1427 هـ، البند (11).", "1) إرفاق (5) عينات متنوعة وحديثة من العمليات أو الإجراءات المعاد هندستها وفق متطلبات تطبيق هذا المعيار."],
  ["5.7.3-1", "إعادة تصميم العمليات والإجراءات الإدارية الخاصة بخدمات وأعمال الجهة، وتحسينها بشكل مستمر، بحيث تشمل ما يأتي:", "أ. تحديد مبررات التحسينات التي تتم على كل عملية أو إجراء وفقًا للتحليل النوعي والكمي.\nب. توثيق مواضع التحسين المنفَّذة على العملية أو الإجراء، والأثر المتوقَّع من هذا التحسين وآلية قياسه عبر تحديث مؤشرات الأداء وآلية متابعتها.\nت. إشراك الإدارات والوحدات ذات العلاقة في عمليات تحسين العمليات أو الإجراءات وإعادة تصميمها.\nث. توضيح الخدمات الرقمية المرتبطة بالإجراءات المحسنة."],
  ["5.7.4", "أتمتة العمليات والإجراءات", "الهدف: أتمتة العمليات والإجراءات بما يحقق تقليل تدخل العامل البشري وزيادة كفاءة العمل.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البند (7).", "1) إرفاق (5) عينات متنوعة وحديثة من شاشات العمليات والاجراءات المؤتمتة مع توضيح اسم الإجراء لكل شاشه مرفقة.\n2) إرفاق ما يثبت أن الجهة استخدمت التقنيات الحديثة لأتمتة العمليات والإجراءات.\n3) إرفاق (3) عينات متنوعة وحديثة من شاشات المتابعة التي تقيس مؤشرات الأداء لحظًّيا.\n4) إرفاق (3) عينات من تقارير المراقبة الدورية التي تتابع نسب نجاح العمليات والإجراءات المؤتمتة."],
  ["5.7.4-1", "أتمتة العمليات والإجراءات على أن تتضمَّن عملية الأتمتة مؤشرات الأداء الخاصة بكل عملية."],
  ["5.7.4-2", "توظيف جميع التقنيات الحديثة المتاحة لأتمتة العمليات والإجراءات (مثل:(RPA)، تقنيات (Low-Code)، وغيرها)."],
  ["5.7.4-3", "تطوير شاشات المتابعة التي تصدر التقارير الدورية لمراقبة تنفيذ العمليات والإجراءات المؤتمتة، وتقيس مؤشرات الأداء لحظًّيا."],
  ["5.7.4-4", "إصدار تقارير دورية توضح نسب نجاح العمليات والإجراءات المؤتمتة جزئًّيا أو كلًّيا للتعرف على مستويات التقدم في أتمتة العمليات والإجراءات."],
  ["5.8", "المشتريات الرقمية", "يشمل المحور معايير ومتطلبات لضمان الامتثال بالأساليب والإجراءات والأحكام الواردة في نظام المنافسات والمشتريات الحكومية ولائحته التنفيذية والاستخدام الأمثل لميزانيات الجهات الحكومية، وترشيد كفاءة الإنفاق على الدوائر الرقمية، واستخدام البنود المخصصة للدوائر الرقمية ونفقات الاتصالات."],
  ["5.8.1", "طرح وتصحيح المنافسات لخدمات الاتصالات على منصة اعتماد", "الهدف: ضمان الامتثال بالأساليب والإجراءات والأحكام الواردة في نظام المنافسات والمشتريات الحكومية والاستخدام الأمثل لميزانيات الجهات الحكومية، بما يسهم في رفع كفاءة المشتريات الرقمية. متطلبـات على جميع الجهـات الحكوميـة مـاعـدا الجهـات المســـتثنـاة من نظـام المنـافســــات والمشـــتريـات الحكومية، والمسـتثناة من اسـتخدام الاتفاقية الإطارية (من قبل هيئة كفاءة الإنفاق والمشـروعات الحكومية أو بخضوعها نظامًا لأحد حالات أساليب الشراء بحسب نظام المنافسات والمشتريات الحكومية)\n\nالنطاق: جميع الجهات الحكومية التي يسري عليها تطبيق نظام المنافسات والمشتريات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• المرسوم الملكي رقم (م/128) وتاريخ 13/11/1440 هـ.\n• تعميم معالي وزير المالية رقم (49989) وتاريخ 2/12/1442 هـ، البند (أولًا).\n• تعميم معالي وزير المالية رقم (46973) وتاريخ 05/12/1443 هـ.\n• تعميم معالي وزير المالية رقم (1748) وتاريخ 14/01/1445هـ.", "1) لا يتطلب إرفاق مستند إثبات، وسيتم التحقق من خلال منصة \"رقمي\".\n2) إرفاق صورة من السوق الإلكتروني لمنصة اعتماد توضح الرقم المرجعي لأمر الشراء وحالته؛ حيث يجب أن تكون إحدى الحالات الآتية :(تم إكمال الطلب، أو بانتظار التوريد، أو بانتظار دفع الرسوم). مســـتنـدات مطلوبـة من الجهـات الحكوميـة المســـتثنـاة من الاتفـاقيـة الإطـاريـة (من قبـل هيئـة كفـاءة الإنفـاق والمشـــروعـات الحكوميـة أو بخضـــوعهـا نظـامـًا لأحـد حـالات أســـاليـب الشـــراء بحســـب نظـام المنـافســـات والمشتريات الحكومية)\n3) لا يتطلب إرفاق مستند إثبات، وسيتم التحقق من خلال منصة \"رقمي\".\n4) إرفاق ما يثبت الموافقة على الاستثناء من الاتفاقية الاطارية من قبل هيئة كفاءة الإنفاق والمشروعات الحكومية، أو ما يثبت موافقة صاحب الصلاحية في الجهة الحكومية على طرح المنافسة أو الشراء المباشر مع ذكر الحالة الخاضعة لها الجهة الحكومية.\n5) إرفاق صورة من منصة \"اعتماد\" توضح الرقم المرجعي للمنافسة المطروحة وحالتها.\n6) إرفاق صورة من منصة \"اعتماد\" توضح الرقم المرجعي للعقد واسم العقد ورقم المنافسة المرتبط بالعقد المشار إليه.\nمستندات مطلوبة من الجهات الحكومية المستثناة من نظام المنافسات والمشتريات الحكومية ولائحته التنفيذية:\n7) إرفاق ما يثبت الموافقة على الاستثناء من نظام المنافسات والمشتريات الحكومية."],
  ["5.8.1-1", "ربط جميع الدوائر الرقمية القائمة لدى الجهة والمضافة في خدمة حصر الدوائر الرقمية بأرقام أوامر الشراء التي تمت من الاتفاقية الإطارية لخدمات الإنترنت والدوائر الرقمية عن طريق السوق الإلكتروني لمنصة \"اعتماد\"."],
  ["5.8.1-2", "قيام الجهة الحكومية بتأمين احتياجاتها الجديدة من خدمات الإنترنت والدوائر الرقمية عبر الاتفاقية الإطارية لخدمات الإنترنت والدوائر الرقمية عن طريق السوق الإلكتروني لمنصة \"اعتماد\" على أن تكون الخدمات ساريه لعام (2026م)."],
  ["5.8.1-3", "ربط جميع الدوائر الرقمية القائمة لدى الجهة والمضافة في خدمة حصر الدوائر الرقمية بأرقام العقود التي طُِرحت.", "متطلبات على الجهات الحكومية المستثناة من الاتفاقية الإطارية (من قبل هيئة كفاءة الإنفاق والمشروعات الحكومية أو بخضوعها نظامًا لأحد حالات أساليب الشراء بحسب نظام المنافسات والمشتريات الحكومية)"],
  ["5.8.1-4", "الحصول على استثناء من الاتفاقية الاطارية من قبل هيئة كفاءة الإنفاق والمشروعات الحكومية، أو موافقة صاحب الصلاحية بطرح المنافسة أو الشراء المباشر وتوضيح الحالة التي خضعت لها الجهة.", "متطلبات على الجهات الحكومية المستثناة من الاتفاقية الإطارية (من قبل هيئة كفاءة الإنفاق والمشروعات الحكومية أو بخضوعها نظامًا لأحد حالات أساليب الشراء بحسب نظام المنافسات والمشتريات الحكومية)"],
  ["5.8.1-5", "قيام الجهة الحكومية بطرح منافساتها لخدمات الاتصالات سواًء أكانت نفقات عامة أم برامج أم مشاريع على منصة \"اعتماد\".", "متطلبات على الجهات الحكومية المستثناة من الاتفاقية الإطارية (من قبل هيئة كفاءة الإنفاق والمشروعات الحكومية أو بخضوعها نظامًا لأحد حالات أساليب الشراء بحسب نظام المنافسات والمشتريات الحكومية)"],
  ["5.8.1-6", "قيام الجهة الحكومية بتسجيل عقودها المتعلقة بخدمات الاتصالات سواًء أكانت نفقات عامة أم برامج أم مشاريع على منصة \"اعتماد\".", "متطلبات على الجهات الحكومية المستثناة من الاتفاقية الإطارية (من قبل هيئة كفاءة الإنفاق والمشروعات الحكومية أو بخضوعها نظامًا لأحد حالات أساليب الشراء بحسب نظام المنافسات والمشتريات الحكومية)"],
  ["5.8.1-7", "الحصول على استثناء من نظام المنافسات والمشتريات الحكومية. مســتندات مطلوبة من جميع الجهات الحكومية ماعدا الجهات المســتثناة من اســتخدام الاتفاقية الإطارية (من قبل هيئة كفاءة الإنفاق والمشـروعات الحكومية أو بخضـوعها نظامًا لأحد حالات أسـاليب الشـراء بحسـب نظام المنافسات والمشتريات الحكومية)", "متطلبات على الجهات الحكومية المستثناة من نظام المنافسات والمشتريات الحكومية ولائحته التنفيذية"],
  ["5.8.2", "حصر وتحديث بيانات الدوائر الرقمية", "الهدف: ترشيد كفاءة الإنفاق على الدوائر الرقمية بتفصيل الاحتياج الفعلي والعادل لسعات هذه الدوائر، وتخفيض السعات الزائدة عن حاجتها، وإلغاء الدوائر الرقمية التي يمكن الاستغناء عنها.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• توجيه مجلس الوزراء والمبلغ بموجب برقية معالي رئيس الديوان الملكي رقم (8102) وتاريخ 3/2/1444هـ.\n• تعميم معالي وزير المالية رقم (49989) وتاريخ 2/12/1442 هـ، البند (ثانيًا).\n• تعميم هيئة الحكومة الرقمية رقم (916) وتاريخ 15/1/1443 هـ.", "1) لا يتطلب إرفاق مستند إثبات، وسيتم التحقق من خلال منصة \"رقمي\"."],
  ["5.8.2-1", "رفع حصر لجميع دوائر الاتصالات لهيئة الحكومة الرقمية وفقًا لخدمة إضافة بيانات الدوائر الرقمية على موقع الهيئة منصة \"رقمي\"، والتحديث عليها بما يتواءم مع السنة الحالية، وإضافة بياناتها التفصيلية المطلوبة كافة."],
  ["5.8.3", "استخدام البنود المخصصة للدوائر الرقمية ونفقات الاتصالات", "الهدف: التزام الجهة الحكومية باستخدام البنود المخصصة للدوائر الرقمية ونفقات الاتصالات لعمليات الشراء المحددة نظامًا فقط، وذلك دعمًا لرحلة التحول الرقمي ورفع معدل الرقابة وضمان استخدام التطبيقات والأنظمة التي تدعم الأعمال الاعتيادية..\n\nالنطاق: جميع الجهات الحكومية التي يسري عليها تطبيق نظام المنافسات والمشتريات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• المرسوم الملكي رقم (م/128) وتاريخ 13/11/1440 هـ.\n• تعميم معالي وزير المالية رقم (49989) وتاريخ 2/12/1442 هـ، البند (أولًا).\n• تعميم معالي وزير المالية رقم (46973) وتاريخ 5/12/1443 هـ.\n• تعميم معالي وزير المالية رقم (1748) وتاريخ 14/1/1445هـ.", "1) إرفاق صورة من السوق الإلكتروني لمنصة \"اعتماد\" توضح الرقم المرجعي لأمر الشراء وحالته؛ حيث يجب أن تكون إحدى الحالات الآتية:(تم إكمال الطلب أو بانتظار التوريد أو بانتظار دفع الرسوم). مســـتنـدات مطلوبـة من الجهـات الحكوميـة المســـتثنـاة من الاتفـاقيـة الإطـاريـة (من قبـل هيئـة كفـاءة الإنفـاق والمشروعات الحكومية أو أحد حالات أساليب الشراء بحسب نظام المنافسات والمشتريات الحكومية)\n2) إرفاق ما يثبت الموافقة على الاستثناء من الاتفاقية الاطارية من قبل هيئة كفاءة الإنفاق والمشروعات الحكومية أو ما يثبت موافقة صاحب الصلاحية في الجهة الحكومية على طرح المنافسة أو الشراء المباشر مع ذكر الحالة الخاضعة لها الجهة الحكومية.\n3) إرفاق صورة من منصة \"اعتماد\" توضح الرقم المرجعي للعقد واسم العقد ورقم المنافسة المرتبط بالعقد الُمشار إليه مع توضيح رقم البند المرتبط بالعقد.\nمستندات مطلوبة من الجهات الحكومية المستثناة من نظام المنافسات والمشتريات الحكومية:\n4) إرفاق ما يثبت الموافقة على الاستثناء من نظام المنافسات والمشتريات الحكومية."],
  ["5.8.3-1", "استخدام الجهة الحكومية البند الخاص بالاتفاقية الإطارية الموحد رقم (339000113).", "متطلبات على جميع الجهات الحكومية ماعدا الجهات المســتثناة من اســتخدام الاتفاقية الإطارية (من قبل هيئة كفاءة الإنفاق والمشــروعات الحكومية أو بخضــوعها نظامًا لأحد حالات أســاليب الشــراء بحســب نظام المنافسات والمشتريات الحكومية)"],
  ["5.8.3-2", "الحصول على استثناء من الاتفاقية الاطارية من قبل هيئة كفاءة الإنفاق والمشروعات الحكومية أو موافقة صاحب الصلاحية بطرح المنافسة أو الشراء المباشر وتوضيح الحالة التي خضعت لها الجهة.", "متطلبات على الجهات الحكومية المستثناة من الاتفاقية الإطارية (من قبل هيئة كفاءة الإنفاق والمشروعات الحكومية أو بخضوعها نظامًا لأحد حالات أساليب الشراء بحسب نظام المنافسات والمشتريات الحكومية)"],
  ["5.8.3-3", "استخدام الجهة الحكومية بند خدمات الاتصالات لما خُصصت له نظامًا، وهي خدمات الدوائر الرقمية ذي التصنيف الاقتصادي رقم (221136) أو خدمات الإنترنت ذي التصنيف الاقتصادي رقم (221134).", "متطلبات على الجهات الحكومية المستثناة من الاتفاقية الإطارية (من قبل هيئة كفاءة الإنفاق والمشروعات الحكومية أو بخضوعها نظامًا لأحد حالات أساليب الشراء بحسب نظام المنافسات والمشتريات الحكومية)"],
  ["5.8.3-4", "الحصول على الاستثناء من نظام المنافسات والمشتريات الحكومية. مســتندات مطلوبة من جميع الجهات الحكومية ماعدا الجهات المســتثناة من اســتخدام الاتفاقية الإطارية (من قبل هيئة كفاءة الإنفاق والمشـروعات الحكومية أو بخضـوعها نظامًا لأحد حالات أسـاليب الشـراء بحسـب نظام المنافسات والمشتريات الحكومية)", "متطلبات على الجهات الحكومية المستثناة من نظام المنافسات والمشتريات الحكومية"],
  ["P4", "إدارة المخاطر واستمرارية الأعمال"],
  ["5.9", "إدارة المخاطر", "يشمل المحور معايير ومتطلبات لتعزيز قدرة الجهة على تحديد المخاطر التي من شأنها التأثير على استمرارية الخدمات الحكومية الرقمية وعلى فهم هذه المخاطر وتحليلها ومعالجتها؛ للتأكد من ضمان استمرارية الأعمال لدى الجهات الحكومية، واستباقية تحديد المخاطر."],
  ["5.9.1", "بناء سياسة وحوكمة نظام إدارة المخاطر", "الهدف: إنشاء مكونات وعناصر حوكمة نظام إدارة المخاطر، وتحديد أدوار ومسؤوليات وصلاحيات المعنيين، لدعم تنفيذ نظام إدارة المخاطر داخل الجهة بفاعلية، وبالمواءمة مع الأهداف الإستراتيجية للجهة.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البند (19).\n• تعميم هيئة الحكومة الرقمية رقم (2044) وتاريخ 28/12/1443 هـ.", "1) إرفاق الهيكل التنظيمي المعتمد متضمنًا الوحدة الإدارية المسؤولة عن نظام إدارة المخاطر.\n2) إرفاق تعريف الموظف المسؤول عن إدارة نظام إدارة المخاطر.\n3) إرفاق مستند توثيق الأدوار والمسؤوليات للوحدة الإدارية المسؤولة عن نظام إدارة المخاطر.\n4) إرفاق تعريف موظفي نظام إدارة المخاطر بما يثبت تعيين فريق يتولى الأدوار والمسؤوليات في نظام إدارة المخاطر.\n5) إرفاق قرار إنشاء اللجنة التوجيهية المسؤولة عن الإشراف على أعمال نظام إدارة المخاطر، وفق متطلبات تطبيق هذا المعيار.\n6) إرفاق ميثاق اللجنة التوجيهية المسؤولة عن الإشراف على أعمال نظام إدارة المخاطر المعتمد، وفق متطلبات تطبيق هذا المعيار.\n7) إرفاق سياسة إدارة المخاطر موث قَّة ومعتمدة.\n8) إرفاق إطار إدارة المخاطر موث قَّ ومعتمد.\n9) إرفاق الوثائق التي توضح إجراءات إدارة المخاطر الموث قَّة والمعتمدة.\n10) إرفاق نموذج سجل المخاطر المستخدم في الجهة، وفق متطلبات تطبيق هذا المعيار.\n11) إرفاق الخطة السنوية المعتمدة، لتقييم مخاطر جميع الوحدات الإدارية في الجهة.\n12) إرفاق إستراتيجية إدارة المخاطر موث قَّة ومعتمدة، وفق متطلبات تطبيق هذا المعيار.\n13) إرفاق وثيقة رواد المخاطر المعتمدة، وفق متطلبات تطبيق هذا المعيار.\n14) إرفاق وثيقة الإبلاغ عن المخاطر المعتمدة، متضمنًة آلية الإبلاغ عن المخاطر ونماذج وقناة موحدة للإبلاغ عنها.\n15) إرفاق وثيقة مستويات تقبل وتحمل المخاطر المعتمدة، وفق متطلبات تطبيق هذا المعيار."],
  ["5.9.1-1", "إنشاء وحدة إدارية مسؤولة عن نظام إدارة المخاطر في الجهة بما يتناسب مع الهيكل التنظيمي المعتمد."],
  ["5.9.1-2", "تعيين مسؤول لإدارة نظام إدارة المخاطر يمتلك الجدارات والصلاحيات الكافية."],
  ["5.9.1-3", "تحديد الأدوار والمسؤوليات لنظام إدارة المخاطر."],
  ["5.9.1-4", "تعيين فريق يتولى تنفيذ الأدوار والمسؤوليات والمهام في نظام إدارة المخاطر، بناًء على احتياجات وأعمال الجهة."],
  ["5.9.1-5", "إنشاء لجنة توجيهية للإشراف على أعمال نظام إدارة المخاطر في الجهة، يرأسها المسؤول الأول في الجهة أو من ينوبه."],
  ["5.9.1-6", "وضع ميثاق اللجنة التوجيهية المسؤولة عن نظام إدارة المخاطر، واعتماده من قبل الإدارة العليا للجهة."],
  ["5.9.1-7", "إنشاء واعتماد سياسة إدارة المخاطر بالمواءمة مع أهداف الجهة."],
  ["5.9.1-8", "إنشاء واعتماد وثيقة إطار إدارة المخاطر."],
  ["5.9.1-9", "إنشاء واعتماد إجراءات إدارة المخاطر."],
  ["5.9.1-10", "إنشاء نموذج سجل المخاطر لجميع الوحدات الإدارية في الجهة وتحديثه دورًّيا، بحيث يشمل ما يأتي: أ.معِّرف الخطر.", "ب. مالك الخطر.\nت. وصف الخطر.\nث. الأسباب الجذرية والعواقب المترتبة على الخطر.\nج. تقييم الخطر الكامن (الأثر الكامن، والاحتمالية الكامنة، ودرجة الخطورة الكامنة).\nح. الضوابط المطبقة لتقليل أثر واحتمالية حدوث الخطر.\nخ. تقييم فعالية الضوابط المطبقة.\nد. تقييم الخطر المتبقي (درجة الخطورة الكامنة وفعالية الضوابط المطبقة).\nذ. إستراتيجية معالجة المخاطر.\nر. خطط المعالجة المخط طَّ تنفيذها للتعامل مع الخطر.\nز. مالك خطط المعالجة للخطر.\nس. تاريخ انتهاء تنفيذ خطط المعالجة للخطر.\nش. نسبة وحالة التنفيذ لخطط المعالجة للخطر."],
  ["5.9.1-11", "إعداد خطة سنوية لتقييم مخاطر جميع الوحدات الإدارية في الجهة، واعتمادها من صاحب الصلاحية."],
  ["5.9.1-12", "إنشاء واعتماد إستراتيجية إدارة المخاطر."],
  ["5.9.1-13", "إنشاء وثيقة رواد المخاطر في الجهة، لتوضيح الأدوار والمسؤوليات، وذلك لتنسيق وتنفيذ ومتابعة أعمال إدارة المخاطر ورفع التقارير ذات العلاقة."],
  ["5.9.1-14", "إنشاء وثيقة الإبلاغ عن المخاطر على أن تشمل آلية الإبلاغ عن المخاطر ونماذج وقناة موحدة للإبلاغ عنها."],
  ["5.9.1-15", "إنشاء واعتماد وثيقة مستويات تقبل وتحمل المخاطر للجهة بالمواءمة مع توجهات وأهداف الجهة الإستراتيجية ومشاركتها مع المعنيين."],
  ["5.9.2", "تحديد وتحليل وتقييم ومعالجة المخاطر", "الهدف: تحديد وتقييم المخاطر الداخلية والخارجية، وتحديد احتمالية وقوعها وأثرها المتوقع على تحقيق الأهداف والاستراتيجيات، ووضع الحلول المناسبة لمعالجة المخاطر، لتقليل احتمالية حدوثها و/أو تخفيف الآثار المترتبة عليها.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البند (19).\n• تعميم هيئة الحكومة الرقمية رقم (2044) وتاريخ 28/12/1443 هـ.", "1) إرفاق عينة من مستندات تثبت عقد ورش العمل مع مّلاك المخاطر، وفق متطلبات تطبيق هذا المعيار.\n2) إرفاق عينات من سجل المخاطر المحدث، بما يشمل المخاطر المتعلقة بالخدمات الحكومية الرقمية وفق متطلبات تطبيق هذا المعيار.\n3) إرفاق عينة من المستندات التي تثبت مشاركة واعتماد سجل المخاطر للوحدات الإدارية من قَِبل ملاك المخاطر والمسؤول الأول للوحدة الإدارية.\n4) إرفاق سجل المخاطر الرئيسية، بحيث يوضح خطط المعالجة المناسبة على مستوى الجهة وتواريخ الانتهاء من تنفيذها.\n5) إرفاق وثيقة مؤشرات المخاطر الرئيسية (KRIs).\n6) إرفاق ما يثبت اعتماد اللجنة التوجيهية لتقرير المخاطر الرئيسية."],
  ["5.9.2-1", "تحديد المخاطر والتهديدات الداخلية والخارجية على مستوى الجهة والوحدات الإدارية عن طريق عقد ورش العمل مع ملاك المخاطر."],
  ["5.9.2-2", "إصدار سجل المخاطر وتوثيقه بحيث يشمل:", "أ. تحديد المخاطر والتهديدات الداخلية والخارجية وعكسها في سجل مخاطر الجهة.\nب. تحليل وتقييم المخاطر والتهديدات الداخلية والخارجية وعكسها في سجل مخاطر الجهة.\nت. تحديد خطط المعالجة المناسبة لكل خطر."],
  ["5.9.2-3", "مشاركة واعتماد سجل المخاطر للوحدة الإدارية ذات العلاقة من قَِبل ملاك المخاطر والمسؤول الأول للوحدة الإدارية."],
  ["5.9.2-4", "تحديد وتحليل وتقييم ومعالجة أهم المخاطر أو المخاطر الرئيسية على مستوى الجهة."],
  ["5.9.2-5", "تحديد مؤشرات المخاطر الرئيسية (KRIs) على مستوى الجهة."],
  ["5.9.2-6", "اعتماد اللجنة التوجيهية للمخاطر الرئيسية."],
  ["5.9.3", "المراجعة والمتابعة والتواصل حول المخاطر", "الهدف: مراقبة المخاطر ومتابعتها، لضمان تحسين جودة وفعالية عملية تقييم ومعالجة المخاطر.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البند (19).\n• تعميم هيئة الحكومة الرقمية رقم (2044) وتاريخ 28/12/1443 هـ.", "1) إرفاق المستندات التي تثبت التحديث الدوري لسجل المخاطر، وفق متطلبات تطبيق هذا المعيار.\n2) إرفاق عينات كافية من تقارير حالة المخاطر الشاملة المرفوعة إلى اللجنة التوجيهية لنظام إدارة المخاطر، وفق متطلبات تطبيق هذا المعيار.\n3) إرفاق عينات من مستندات تثبت التحديث الدوري لأهم المخاطر.\n4) إرفاق عينات من مستندات تثبت التحديث الدوري لمؤشرات المخاطر الرئيسية (KRIs)."],
  ["5.9.3-1", "تحديث سجل مخاطر الجهة من قَِبل المسؤولين عن إدارة المخاطر، بحيث يشمل ما يأتي:", "أ. مراقبة ومتابعة حالة المخاطر المحددة الداخلية والخارجية للجهة بشكل دوري.\nب. مراقبة الضوابط وخطط المعالجة وتقييم فعاليتها بشكل دوري.\nت. متابعة نسب تنفيذ خطط المعالجة للمخاطر في المدة الزمنية المحددة بشكل دوري."],
  ["5.9.3-2", "رفع تقارير المخاطر إلى اللجنة التوجيهية لنظام إدارة المخاطر، بحيث تشمل على سبيل المثال لا الحصر ما يأتي:", "أ. تقرير حالة المخاطر الشاملة.\nب. تقرير أهم المخاطر.\nت. تقرير مؤشرات المخاطر الرئيسية."],
  ["5.9.3-3", "تحديث أهم المخاطر أو المخاطر الرئيسية."],
  ["5.9.3-4", "تحديث مؤشرات المخاطر الرئيسية (KRIs) بشكل دوري."],
  ["5.9.4", "التدريب والتوعية بإدارة المخاطر", "الهدف: تدريب جميع الموظفين وأصحاب المصلحة ورفع الوعي بإدارة المخاطر، لضمان تحقيق أهداف وإستراتيجيات الجهة.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البند (19).\n• تعميم هيئة الحكومة الرقمية رقم (2044) وتاريخ 28/12/1443 هـ.", "1) إرفاق وثيقة تحليل الاحتياجات التدريبية بالتعاون مع الموارد البشرية، وخطة التدريب المعتمدة لمنسوبي إدارة المخاطر للعام الحالي.\n2) إرفاق ما يثبت تنفيذ خطة التدريب المعتمدة لمنسوبي إدارة المخاطر.\n3) إرفاق البرنامج التوعوي المحّدث بإدارة المخاطر لمنسوبي الجهة، وعينات من المستندات التي تثبت تنفيذه.\n4) إرفاق خطة التدريب لرواد إدارة المخاطر وعينات من المستندات التي تثبت تنفيذها."],
  ["5.9.4-1", "تحليل الاحتياجات التدريبية بالتعاون مع الموارد البشرية لوضع متطلبات التدريب بما يتناسب مع الأدوار والمسؤوليات في نظام إدارة المخاطر، ووضع خطة التدريب لمنسوبي إدارة المخاطر."],
  ["5.9.4-2", "تنفيذ خطة التدريب لمنسوبي إدارة المخاطر."],
  ["5.9.4-3", "وضع وتنفيذ خطة لحملات التوعية بإدارة المخاطر لمنسوبي الجهة، لتعزيز ثقافة المخاطر، باستخدام أحد الأنشطة الآتية:(الرسائل التوعوية عبر قنوات التواصل المختلفة، أو ورش العمل التوعوية والاجتماعات والنقاشات المفتوحة، أو الأسبوع التوعوي بالمخاطر)."],
  ["5.9.4-4", "وضع وتنفيذ خطة التدريب لرواد المخاطر تتناسب مع الأدوار والمسؤوليات في نظام إدارة المخاطر لدى الجهة."],
  ["5.9.5", "التطوير والتحسين المستمر لإدارة المخاطر", "الهدف: مراجعة إجراءات وعمليات إدارة المخاطر لتحسين قدرة الجهة، والرفع من مستوى فعالية نظام إدارة المخاطر وتطبيق أفضل الممارسات والمعايير.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البند (19).\n• تعميم هيئة الحكومة الرقمية رقم (2044) وتاريخ 28/12/1443 هـ.\n• تعميم هيئة الحكومة الرقمية رقم (1189) وتاريخ 13/4/1446هـ.", "1) إرفاق المستندات التي تثبت مراجعة وتحديث وثائق نظام إدارة المخاطر، وفق متطلبات تطبيق هذا المعيار.\n2) إرفاق التقرير السنوي لنتائج مراجعة فاعلية تنفيذ وتطبيق نظام إدارة المخاطر، وفق متطلبات تطبيق هذا المعيار.\n3) ارفاق ما يثبت رفع تقارير نتائج قياس التحول الرقمي لمعايير إدارة المخاطر إلى اللجنة التوجيهية.\n4) إرفاق وثيقة توّضح آلية حفظ وتخزين بيانات ووثائق نظام إدارة المخاطر في الجهة.\n5) إرفاق الحصر المعتمد من المسؤول الأول في الجهة أو من ينوب عنه بقائمة الشركات المزمع التعاقد معها بصورة مباشرة أو غير مباشرة لتقديم خدمات تقنية، مع التأكيد على توقيع كل شركة على نموذج الفحص النافي للجهالة، وعينة موقعة وفق النموذج المعتمد.\n6) إرفاق حصر معتمد من المسؤول الأول في الجهة أو من ينوب عنه بقائمة الشركات المقدمة لخدمات الإسناد مع التأكيد على توقيع كل شركة على اتفاقية عدم الإفصاح وفق متطلبات تطبيق هذا المعيار، وعينة موقعة حسب النموذج المعتمد."],
  ["5.9.5-1", "مراجعة وتحديث الوثائق الخاصة بنظام إدارة المخاطر بشكل دوري وفق آلية المراجعة المعتمدة لكل وثيقة، أو عند حدوث تغيير جوهري لأهداف الجهة الإستراتيجية أو التشغيلية بحيث تشمل ما يأتي:", "أ. سياسة إدارة المخاطر.\nب. إطار إدارة المخاطر.\nت. إجراءات إدارة المخاطر."],
  ["5.9.5-2", "مراجعة فاعلية تنفيذ وتطبيق نظام إدارة المخاطر بشكل سنوي باستخدام إحدى طرق المراجعة الآتية: (التقييم الذاتي، أو تقييم مؤشرات الأداء الرئيسية، أو التدقيق/المراجعة الداخلية أو الخارجية)."],
  ["5.9.5-3", "رفع تقارير نتائج قياس التحول الرقمي لمعايير إدارة المخاطر إلى اللجنة التوجيهية وضمان اتخاذ الإجراءات التصحيحية المناسبة."],
  ["5.9.5-4", "إعداد آلية لحفظ وتخزين بيانات ووثائق نظام إدارة المخاطر، لضمان استمرارية أعمال الوحدة الإدارية."],
  ["5.9.5-5", "إعداد نموذج الفحص النافي للجهالة بالتنسيق مع الإدارات ذات الصلة داخل الجهة وتوقيعه من الشركات المزمع التعاقد معها بصورة مباشرة أو غير مباشرة لتقديم خدمات تقنية المعلومات وتحديثه بشكل سنوي، بحيث تشمل البيانات التعريفية بالشركة، الهيكل الإداري والملكية، بيانات الاتصال وبما يتوافق مع ضوابط حوكمة تقنية المعلومات الصادرة عن الهيئة."],
  ["5.9.5-6", "توقيع اتفاقيات عدم الإفصاح (NDAs) مع مقدمي خدمات الإسناد المتعلقة بتقنية المعلومات للمحافظة على سرية البيانات والمعلومات، ووضع إجراءات وآليات للمراجعة والتدقيق الدوري على مقدمي خدمات الإسناد للتحقق من فعالية الضوابط الداخلية وضمان مستوى الامتثال المطلوب."],
  ["5.10", "استمرارية الأعمال", "يشمل المحور معايير ومتطلبات مواصلة تقديم الجهة الحكومية أنشطتها ذات الأولوية على مستويات محّددة سلفًا بعد حدوث انقطاع، وتعزيز مرونة استجابتها لأي حوادث انقطاع تواجهها، وتمكينها من استعادة منتجاتها وخدماتها ذات الأولوية بوقت زمني محدد."],
  ["5.10.1", "إنشاء نظام استمرارية الأعمال", "الهدف: وضع الإطار العام وتحديد أدوار ومهام الأشخاص المعنيين والأقسام المعنية لتخطيط وتنفيذ ومراجعة وتطوير نظام إدارة استمرارية الأعمال.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البند (19).\n• تعميم هيئة الحكومة الرقمية رقم (1878) وتاريخ 24/9/1443هـ.", "1) إرفاق تعريف الموظف المسؤول عن إدارة استمرارية الأعمال.\n2) إرفاق تعريف موظفي نظام إدارة استمرارية الأعمال، بما يثبت تعيين فريق يتولى الأدوار والمسؤوليات في نظام إدارة استمرارية الأعمال.\n3) إرفاق قرار إنشاء اللجنة التوجيهية المسؤولة عن الإشراف على أعمال نظام استمرارية الأعمال.\n4) إرفاق ميثاق اللجنة التوجيهية موثقًا ومعتمدًا، وفق متطلبات تطبيق هذا المعيار.\n5) إرفاق سياسة إدارة استمرارية الأعمال موث قَّة ومعتمدة، وما يثبت مراجعتها بشكل دوري، وفق متطلبات تطبيق هذا المعيار.\n6) إرفاق وثيقة إطار إدارة استمرارية الأعمال المعتمدة، وفق متطلبات تطبيق هذا المعيار.\n7) إرفاق ما يثبت تعيين رواد استمرارية الأعمال."],
  ["5.10.1-1", "تعيين مسؤول لإدارة نظام استمرارية الأعمال يمتلك الجدارات والصلاحيات الكافية."],
  ["5.10.1-2", "تعيين فريق يتولى تنفيذ الأدوار والمسؤوليات في نظام إدارة استمرارية الأعمال، بناًء على احتياجات وأعمال الجهة."],
  ["5.10.1-3", "إنشاء لجنة توجيهية للإشراف على أعمال نظام استمرارية الأعمال في الجهة، يرأسها المسؤول الأول في الجهة أو من ينوبه."],
  ["5.10.1-4", "وضع ميثاق اللجنة التوجيهية المسؤولة عن نظام استمرارية الأعمال مع توضيح اختصاصاتها وصلاحياتها وعضويتها واعتماده من قَِبل الإدارة العليا للجهة."],
  ["5.10.1-5", "إعداد واعتماد سياسة استمرارية الأعمال ومراجعتها بشكل دوري، أو عند حدوث تغيير جوهري في بيئة التشغيل أو الأهداف الإستراتيجية للجهة."],
  ["5.10.1-6", "إنشاء واعتماد إطار إدارة استمرارية الأعمال بالجهة."],
  ["5.10.1-7", "تعزيز نظام إدارة استمرارية الأعمال من خلال تخصيص المسؤوليات وتعيين رواد استمرارية الأعمال."],
  ["5.10.2", "التدريب والتوعية بنظام إدارة استمرارية الأعمال", "الهدف: توعية جميع الموظفين والأطراف ذوي العلاقة باستمرارية الأعمال، وتعزيز تدريبهم على أدوارهم ومسؤولياتهم ضمن نطاق نظام إدارة استمرارية الأعمال.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البند (19).\n• تعميم هيئة الحكومة الرقمية رقم (1878) وتاريخ 24/9/1443هـ..", "1) إرفاق وثيقة تحليل الاحتياجات التدريبية بالتعاون مع الموارد البشرية، وخطة التدريب المعتمدة لمنسوبي إدارة استمرارية الأعمال للعام الحالي.\n2) إرفاق ما يثبت تنفيذ خطة التدريب لمنسوبي إدارة استمرارية الأعمال.\n3) إرفاق خطط للتعاقب الوظيفي، لتجنب نقاط الفشل المفردة لأنشطة نظام استمرارية الأعمال.\n4) إرفاق ما يثبت إقامة البرامج التوعوية التدريبية الخاصة للمعنيين والمشاركين في نظام استمرارية الأعمال، وفق متطلبات تطبيق هذا المعيار.\n5) إرفاق ما يثبت مشاركة سياسة استمرارية الأعمال المعتمدة مع جميع موظفي الجهة.\n6) إرفاق ما يثبت تنفيذ ورش عمل توعوية بإدارة استمرارية الأعمال للإدارة العليا على مستوى الجهة.\n7) إرفاق ما يثبت تنفيذ ورش عمل توعوية لرواد استمرارية الأعمال على مستوى الجهة."],
  ["5.10.2-1", "تحليل الاحتياجات التدريبية بالتعاون مع الموارد البشرية لوضع متطلبات التدريب بما يتناسب مع الأدوار والمسؤوليات في نظام إدارة استمرارية الأعمال، ووضع خطة التدريب لمنسوبي إدارة استمرارية الأعمال."],
  ["5.10.2-2", "تنفيذ خطة التدريب لمنسوبي استمرارية الأعمال."],
  ["5.10.2-3", "إعداد خطط للتعاقب الوظيفي لتجنب نقاط الفشل المفردة لأنشطة نظام استمرارية الأعمال."],
  ["5.10.2-4", "تنفيذ برنامج لنشر ثقافة استمرارية الأعمال في الجهة؛ عن طريق التدريب وورش عمل تخصصية لجميع الأطراف المشاركة في نظام استمرارية الأعمال مرة واحدة في السنة على الأقل، وعند حدوث تغيير جوهري في العمليات التشغيلية لدى الجهة."],
  ["5.10.2-5", "مشاركة سياسة استمرارية الأعمال المعتمدة مع جميع موظفي الجهة."],
  ["5.10.2-6", "تنفيذ ورش عمل توعوية بإدارة استمرارية الأعمال للإدارة العليا على مستوى الجهة."],
  ["5.10.2-7", "تنفيذ ورش عمل توعوية لرواد استمرارية الأعمال على مستوى الجهة."],
  ["5.10.3", "تحليل أثر انقطاع الأعمال وتقييم المخاطر والتهديدات بنظام استمرارية الأعمال", "الهدف: تحليل الأثر الناتج عن انقطاع العمليات والإجراءات التي تقدم المنتجات والخدمات بالجهة، وتحديد الوقت المستهدف للتعافي بعد حدوث انقطاع للخدمات الرئيسية، وتقييم المخاطر والتهديدات الداخلية والخارجية ونقاط الفشل الحرجة التي قد تؤثر على الأنشطة ذات الأولوية، وتحديد أثرها المتوقَّع في حالة حدوث انقطاع أو اضطراب، ووضع الحلول لمعالجتها أو تخفيف آثارها.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البند (19).\n• تعميم هيئة الحكومة الرقمية رقم (1878) وتاريخ 24/9/1443هـ.", "1) إرفاق قائمة أو سجل معتمد يثبت حصر جميع العمليات والإجراءات الداخلية والخارجية في تحليل أثر انقطاع الأعمال.\n2) إرفاق مصفوفة تقييم أثر الانقطاع المعتمدة، وفق متطلبات تطبيق هذا المعيار.\n3) إرفاق عينات من التقارير التي توضح نتائج تحليل أثر انقطاع الأعمال بما يشمل تحديد أوقات الاسترجاع المستهدفة (RTO)، وتحديد نقاط الاسترجاع المستهدف (RPO) للعمليات والإجراءات المتعلقة بالخدمات الحكومية الرقمية وفق متطلبات تطبيق هذا المعيار.\n4) إرفاق عينات من التقارير التي توضح الموارد البشرية واللوجستية والتقنية والبنية التحتية والإجراءات البديلة اللازمة لتنفيذ العمليات والإجراءات المتعلقة بالخدمات الحكومية الرقمية وفق نتائج تحليل أثر انقطاع الأعمال.\n5) إرفاق ما يثبت اعتماد اللجنة التوجيهية للتقرير الشامل لنتائج تحليل أثر انقطاع الأعمال.\n6) إرفاق التقارير التي توضح مراجعة تحليل أثر انقطاع الأعمال.\n7) إرفاق (3) عينات من نتائج تقييم المخاطر والتهديدات التي تؤثر على استمرارية أعمال الجهة للعمليات والإجراءات المتعلقة بالخدمات الحكومية الرقمية وفق متطلبات تطبيق هذا المعيار.\n8) إرفاق ما يثبت رفع تقارير نتائج تحديد وتقييم المخاطر والتهديدات التي تؤثر على استمرارية أعمال الجهة إلى اللجنة التوجيهية.\n9) إرفاق عينات من التقارير التي توضح نتائج تحليل أثر انقطاع الأعمال بما يشمل الفترة الزمنية القصوى المسموح بها (MTPD)، والحد الأدنى من أهداف استمرارية الأعمال (MBCO).\n10) لا يتطلب إرفاق مستند إثبات وسيتم التحقق داخليًا من منصة \"رقمي\"."],
  ["5.10.3-1", "تضمين جميع العمليات والإجراءات الداخلية والخارجية التي تقوم بها الجهة، وتحديد الاعتمادات الداخلية والخارجية عند حدوث انقطاع للأعمال، وتحديد الاعتمادات الداخلية والخارجية، وتعيين ملاك للعمليات والإجراءات المضمَّنة."],
  ["5.10.3-2", "إنشاء مصفوفة تقييم أثر الانقطاع للجهة واعتمادها، على أن تشمل كحد أدنى الفئات الآتية:(الأثر التشغيلي، والأثر المالي، والآثار القانونية والتنظيمية والإستراتيجية، والأثر على السمعة)."],
  ["5.10.3-3", "تحديد أوقات الاسترجاع المستهدفة (RTO) ونقاط الاسترجاع المستهدفة RPO() بناء على نتائج تحليل أثر انقطاع الأعمال للعمليات والإجراءات المتعلقة بالخدمات الحكومية الرقمية."],
  ["5.10.3-4", "تحديد الموارد البشرية واللوجستية والتقنية والبنية التحتية والإجراءات البديلة اللازمة لتنفيذ العمليات والإجراءات المتعلقة بالخدمات الحكومية الرقمية."],
  ["5.10.3-5", "اعتماد اللجنة التوجيهية للتقرير الشامل لنتائج تحليل أثر انقطاع الأعمال."],
  ["5.10.3-6", "مراجعة تحليل أثر انقطاع الأعمال بشكل سنوي على الأقل، أو عند حدوث تغيير جوهري في عمليات الجهة التشغيلية أو أهدافها الاستراتيجية."],
  ["5.10.3-7", "تحديد وتقييم المخاطر والتهديدات التي تؤثر على استمرارية أعمال الجهة للعمليات والإجراءات المتعلقة بالخدمات الحكومية الرقمية بشكل مستمر، ومواءمتها مع منهجية إدارة المخاطر المعتمدة لدى الجهة."],
  ["5.10.3-8", "رفع تقارير نتائج تحديد وتقييم المخاطر والتهديدات التي تؤثر على استمرارية أعمال الجهة إلى اللجنة التوجيهية."],
  ["5.10.3-9", "تحديد الفترة الزمنية القصوى المسموح بها (MTPD) لانقطاع الأعمال للمنتجات، والخدمات والعمليات والأنشطة، والحد الأدنى من مستوى تقديم الخدمة (MBCO)."],
  ["5.10.3-10", "تصنيف مستوى أهمية الخدمات الحكومية الرقمية والمنصات والتطبيقات والالتزام بأوقات الاسترجاع المستهدفة لكل مستوى وفق مصفوفة تصنيف الخدمات والمنصات والتطبيقات الصادرة من هيئة الحكومة الرقمية عبر منصة \"رقمي\"."],
  ["5.10.4", "تحديد إستراتيجية استمرارية الأعمال", "الهدف: تحديد إستراتيجيات التعافي لاستمرارية الأعمال التي تقِّدم حلولًا وفق مُخرجات تحليل أثر انقطاع الأعمال، وتقييم المخاطر والتهديدات، ووضع خارطة طريق للارتقاء بدرجة كفاءة خطط استمرارية الأعمال المختلفة.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البند (19).\n• تعميم هيئة الحكومة الرقمية رقم (1878) وتاريخ 24/9/1443هـ.", "1) إرفاق عينات كافية من إستراتيجيات التعافي وفق متطلبات تطبيق هذا المعيار.\n2) إرفاق ما يثبت تحليل التكاليف والمنافع لإستراتيجيات استمرارية الأعمال وعرضها على اللجنة التوجيهية لاستمرارية الأعمال.\n3) إرفاق ما يثبت اعتماد اللجنة التوجيهية لاستمرارية الأعمال لإستراتيجيات التعافي.\n4) إرفاق ما يثبت مراجعة استراتيجيات التعافي المعتمدة لدى الجهة.\n5) إرفاق العقود المبرمة أو اتفاقيات مستوى الخدمة مع الموردين الأساسيين للخدمات الحرجة بالجهة بما يوضح تضمين أوقات ونقاط الاسترجاع المستهدفة للخدمات الحرجة."],
  ["5.10.4-1", "تحديد إستراتيجيات التعافي بما يشمل الأنظمة التقنية والخدمات الرقمية والاتصالات، وأنظمة النسخ الاحتياطي وحلول العمل عن بُعد، سواء داخل الجهة أو مستضافة على الحوسبة السحابية أو مُدارة من قَِبل أطراف خارجية."],
  ["5.10.4-2", "تحليل التكاليف والمنافع لقياس فاعلية إستراتيجيات وحلول إدارة استمرارية الأعمال وتحديد أولوياتها، وعرضها على اللجنة التوجيهية لاستمرارية الأعمال."],
  ["5.10.4-3", "اعتماد استراتيجيات التعافي من قَِبل اللجنة التوجيهية لاستمرارية الأعمال."],
  ["5.10.4-4", "مراجعة استراتيجيات التعافي بشكل سنوي على الأقل، أو عند حدوث تغيير جوهري للأهداف التشغيلية أو الإستراتيجية لدى الجهة."],
  ["5.10.4-5", "تحديد أوقات الاسترجاع المستهدفة (RTO)، ونقاط الاسترجاع المستهدفة (RPO) في العقود المبرمة مع الموردين الأساسيين للخدمات الحرجة بالجهة."],
  ["5.10.5", "بناء خطط استمرارية الأعمال وتوفير مراكز احتياطية بديلة لحفظ البيانات", "الهدف: تحديد وتوثيق الإجراءات بناًء على مُخرجات الإستراتيجيات والحلول المختارة، بما يسهم في بناء خطط التعافي من كوارث تقنية المعلومات بالإضافة إلى خطط الاستجابة للحوادث، وخطط استمرارية الأعمال، بما يسهم في ضمان قدرة الجهة على الاستجابة للأزمات والانقطاعات أو حالات الطوارئ التي تؤثر عليها، وبالتالي تقليل التأثير على عملياتها.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البند (19).\n• تعميم الديوان الملكي رقم (7546) وتاريخ 1/2/1445 هـ.\n• قرار مجلس الوزراء رقم (82) وتاريخ 22/3/1431هـ، التوصية (الرابعة عشرة).\n• تعميم هيئة الحكومة الرقمية رقم (1878) وتاريخ 24/9/1443هـ.\n• تعميم هيئة الحكومة الرقمية رقم (1533) وتاريخ 23/5/1443هـ.", "1) إرفاق عينات كافية من خطط استمرارية الأعمال المعتمدة للجهة وفق متطلبات تطبيق هذا المعيار.\n2) إرفاق ما يثبت مراجعة خطط استمرارية الأعمال بشكل سنوي، وفق متطلبات تطبيق هذا المعيار.\n3) إرفاق تقارير نتائج اختبارات خطط استمرارية الأعمال بشكل سنوي، وفق متطلبات تطبيق هذا المعيار.\n4) إرفاق عقود الصيانة والتشغيل التي تشمل بنود المراكز الاحتياطية البديلة (DR) لحفظ البيانات، ومراكز للأنظمة الحساسة لحفظ وتشغيل البيانات وإجراءات اختبارها وفق المعايير الدولية لدى الجهة، أو ما يثبت توفير مراكز البيانات الاحتياطية داخل الجهة.\n5) إرفاق خطط التعافي من الكوارث لتقنية المعلومات والاتصالات المرتبطة بالمنصات والتطبيقات والخدمات الرقمية والبيانات المعتمدة لدى الجهة، وفق متطلبات تطبيق هذا المعيار.\n6) إرفاق وثيقة إجراءات النسخ الاحتياطي وإجراءات الاسترجاع للعمليات المعرفة ضمن تأثير انقطاع الأعمال.\n7) لا يتطلب إرفاق مستند إثبات، وسيتم التحقق داخليًا من منصة \"رقمي\".\n8) إرفاق عينة من تقارير ما بعد الحادث، وفق متطلبات تطبيق هذا المعيار.\n9) إرفاق عينات كافية من التقارير التي توضح اختبار خطط التعافي من الكوارث التقنية والاتصالات بشكل سنوي.\n10) إرفاق ما يثبت مراجعة خطط التعافي من الكوارث التقنية والاتصالات بشكل سنوي، وفق متطلبات تطبيق هذا المعيار.\n11) إرفاق العقود، أو الاتفاقيات، أو أوامر الشراء التي تتضمن توفير دوائر الاتصال الاحتياطية والبديلة لدوائر الاتصالات التي تخدم الأنظمة والخدمات الحساسة للجهة من مقدمي خدمة مختلفين.\n12) إرفاق ما يثبت عمل الاختبارات الدورية لدوائر الاتصال الاحتياطية والبديلة بما يضمن فعاليتها واستمرارية الخدمات الرقمية.\n13) إرفاق وثيقة خطة الاستجابة الإعلامية المعتمدة لدى الجهة من صاحب الصلاحية، وفق متطلبات تطبيق هذا المعيار."],
  ["5.10.5-1", "إعداد واعتماد خطط استمرارية الأعمال بناًء على إستراتيجيات إدارة استمرارية الأعمال المعتمدة."],
  ["5.10.5-2", "مراجعة خطط استمرارية الأعمال مرة واحدة في السنة على الأقل، أو عند حدوث تغيير جوهري لدى الجهة."],
  ["5.10.5-3", "اختبار خطط استمرارية الأعمال مرة واحدة في السنة على الأقل، أو عند حدوث تغيير جوهري لدى الجهة."],
  ["5.10.5-4", "توفير مراكز البيانات الاحتياطية للمنصات والتطبيقات الحرجة والحساسة لدى الجهة، وفق نتائج تحليل أثر انقطاع الأعمال."],
  ["5.10.5-5", "إعداد واعتماد خطط التعافي لتقنية المعلومات والاتصالات، لاستعادة المنصات والتطبيقات والخدمات الرقمية والبيانات في الوقت المناسب، لتحقيق وقت الاسترجاع المستهدف للجهة."],
  ["5.10.5-6", "تحديد طرق وإجراءات النسخ الاحتياطي والاسترجاع لاستعادة عمليات النظام بسرعة وفعالية بعد انقطاع الخدمة."],
  ["5.10.5-7", "التواصل مع هيئة الحكومة الرقمية في حال وجود انقطاع للخدمات الرقمية حسب دليل المستخدم للإبلاغ عن انقطاع الخدمات الحكومية الرقمية على منصة \"رقمي\"."],
  ["5.10.5-8", "توثيق الأحداث في حال وجود انقطاع للعمليات موضَّحة المسؤوليات والصلاحيات المتعلقة بجمع واعتماد وتحديث سجلات الأنشطة، والدروس المستفادة وإصدار تقرير ما بعد الحادث."],
  ["5.10.5-9", "اختبار خطط التعافي من كوارث تقنية المعلومات والاتصالات بما يشمل تفعيل مراكز البيانات الاحتياطية واستعادة المنصات والتطبيقات الحرجة والحساسة لدى الجهة مرة واحدة في السنة على الأقل، أو عند حدوث تغيير جوهري لبنية تقنية المعلومات لدى الجهة."],
  ["5.10.5-10", "مراجعة خطط التعافي من كوارث تقنية المعلومات والاتصالات مرة واحدة في السنة على الأقل، أو عند حدوث تغيير جوهري لبنية تقنية المعلومات لدى الجهة."],
  ["5.10.5-11", "توفير دوائر الاتصال الاحتياطية والبديلة لدوائر الاتصالات التي تخدم الأنظمة والخدمات الحساسة للجهة من مقدمي خدمة مختلفين."],
  ["5.10.5-12", "عمل الاختبارات الدورية لدوائر الاتصال الاحتياطية والبديلة بما يضمن فعاليتها واستمرارية الخدمات الرقمية."],
  ["5.10.5-13", "إعداد واعتماد خطة التواصل والاستجابة الإعلامية، بما يشمل إجراءات التعامل مع الأطراف الخارجية ذات العلاقة."],
  ["5.10.6", "التمارين والاختبارات ذات العلاقة باستمرارية الأعمال", "الهدف: قياس فاعلية خطة أو خطط استمرارية الأعمال وهيكل الاستجابة للحوادث، لضمان تطبيق سياسة استمرارية الأعمال وتحقيق أهداف إدارة استمرارية الأعمال.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البند (19).\n• تعميم هيئة الحكومة الرقمية رقم (1878) وتاريخ 24/9/1443هـ..", "1) إرفاق برنامج أو جدول الاختبارات والتمارين السنوي المعتمد من قَِبل اللجنة التوجيهية لاستمرارية الأعمال.\n2) إرفاق عينة من تقارير الاختبارات أو التمارين المعتمدة التي توضح تنفيذ برنامج أو جدول الاختبارات والتمارين المعتمد من قَِبل اللجنة التوجيهية لاستمرارية الأعمال.\n3) إرفاق ما يثبت مشاركة تقارير الاختبارات أو التمارين مع اللجنة التوجيهية لاستمرارية لأعمال."],
  ["5.10.6-1", "إنشاء برنامج أو جدول لجميع الاختبارات والتمارين لخطط نظام استمرارية الأعمال المختلفة، واعتماده من اللجنة التوجيهية لاستمرارية الأعمال بشكل سنوي."],
  ["5.10.6-2", "تنفيذ برنامج الاختبارات والتمارين المعتمد من قَِبل اللجنة التوجيهية لاستمرارية الأعمال."],
  ["5.10.6-3", "مشاركة تقارير الاختبارات والتمارين مع اللجنة التوجيهية لاستمرارية الأعمال."],
  ["5.10.7", "التوثيق والتحسين المستمر لنظام استمرارية الأعمال", "الهدف: توثيق الدروس المستفادة من تنفيذ نظام إدارة استمرارية الأعمال والحوادث الفعلية والتمارين والاختبارات ونتائج عمليات المراجعة، وإجراء أنشطة الصيانة الروتينية للحفاظ على نظام إدارة استمرارية الأعمال وتحسينه بعد إنشائه، وتحسين صمود الجهة، والرفع من مستوى فعالية نظام الإدارة من خلال تطبيق طرق مراجعة متعددة، ومعالجة حالات عدم المطابقة بفعالية، وتنفيذ الإجراءات التصحيحية لمعالجة هذه الحالات.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البند (19).\n• تعميم هيئة الحكومة الرقمية رقم (1878) وتاريخ 24/9/1443هـ.", "1) إرفاق تقرير يوضح نتائج مراجعة نظام إدارة استمرارية الأعمال.\n2) إرفاق ما يثبت مشاركة نتائج مراجعة نظام إدارة استمرارية الأعمال مع لجنة استمرارية الأعمال.\n3) إرفاق ما يثبت تطوير وتحديث نظام استمرارية الأعمال، بناء على نتائج عمليات التدقيق الداخلي والخارجي ومخرجات مرحلة التحقق."],
  ["5.10.7-1", "مراجعة نظام إدارة استمرارية الأعمال بشكل دوري (سنوًّيا على الأقل) عبر مدقق داخلي أو خارجي يمتلك المؤهلات والخبرات الكافية."],
  ["5.10.7-2", "مشاركة نتائج عمليات التدقيق الداخلي والخارجي مع لجنة استمرارية الأعمال؛ لضمان اتخاذ الإجراءات التصحيحية."],
  ["5.10.7-3", "التأكد من تطوير وتحديث نظام استمرارية الأعمال بناء على نتائج عمليات التدقيق الداخلي والخارجي ومخرجات مرحلة التحقق."],
  ["P5", "تقنية المعلومات"],
  ["5.11", "الأنظمة الداعمة للتحول الرقمي", "يشمل المحور معايير ومتطلبات بنية التطبيقات والأنظمة المؤسسية التي تدعم الأعمال الاعتيادية وأعمال التحول الرقمي."],
  ["5.11.1", "استخدام أنظمة الموارد الحكومية", "الهدف: دعم وتمكين الجهات الحكومية على إدارة وتخصيص مواردها بصورة فعالة وتعزيز الشفافية، وأتمتة عمليات وخدمات الدعم عبر استخدام جميع وحدات أنظمة الموارد الحكومية المتاحة.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• قرار مجلس الوزراء رقم (40) وتاريخ 27/2/1427 هـ، البند (12).", "1) إرفاق عينة واحدة حديثة من الشاشات وأدلة المستخدمين لكل جزء من نظم الموارد (نظام إدارة الموارد البشرية، والنظام المالي، ونظام التوريد والمشتريات، ونظام إدارة العهد والمخزون، ونظام إدارة الموردين).\n2) إرفاق (3) عينات حديثة من التقارير الدورية الصادرة من الأنظمة الرئيسية لتخطيط الموارد الحكومية.\n3) إرفاق (3) عينات حديثة من الخدمات الذاتية المقدَّمة للمستفيدين الداخليين والخارجيين وأدلة المستخدمين.\n4) إرفاق (3) عينات وشرح لإجراءات كاملة توضح عملية الربط والتكامل بين أنظمة إدارة الموارد والنظم الداخلية في الجهة، والنظم ذات العلاقة في الجهات الخارجية."],
  ["5.11.1-1", "تطبيق الأنظمة الرئيسية لتخطيط الموارد الحكومية وإصدار أدلة المستخدمين."],
  ["5.11.1-2", "إصدار تقارير دورية من الأنظمة الرئيسية لتخطيط الموارد الحكومية."],
  ["5.11.1-3", "تقديم جميع الخدمات الذاتية للمستفيد الداخلي والخارجي من خلال البوابة الإلكترونية أو تطبيقات الأجهزة الذكية، وإصدار أدلة المستخدمين."],
  ["5.11.1-4", "التعاون والمشاركة مع الإدارات الداخلية لتحقيق التكامل بين نظم الموارد الحكومية والنظم ذات العلاقة في الجهات الخارجية."],
  ["5.11.2", "استخدام الأنظمة الرقمية الخاصة بإدارة المشاريع", "الهدف: استخدام الأنظمة الرقمية الخاصة بإدارة المشاريع في جميع التعاملات المتعلقة بالمشاريع الرقمية.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البند (10).", "1) إرفاق (4) عينات حديثة من شاشات النظم الرقمية الخاصة بإدارة المشاريع (طلب مشروع، والتخطيط، والمتابعة والتقارير، والتسليمات)، وفق متطلبات تطبيق هذا المعيار.\n2) إرفاق عينة واحدة توضح جميع عمليات الربط والتكامل بين نظام إدارة المشاريع والأنظمة الداخلية الأخرى.\n3) إرفاق (3) عينات حديثة من النظام التقني توضح ضبط الصلاحيات الخاصة بفريق إدارة المشروع والإدارات الأخرى.\n4) إرفاق (3) عينات حديثة من التقارير الدورية التي توضح مراقبة معالم ومخرجات المشاريع في الجهة يتم من خلالها توضيح نسبة إنجاز كل معلم ومخرج."],
  ["5.11.2-1", "استخدام الجهة للأنظمة والأدوات الرقمية الخاصة بإدارة المشاريع ورقمنة عمليات طلب وتخطيط وضبط ومراقبة ومتابعة المشاريع والمهام والجداول الزمنية."],
  ["5.11.2-2", "ربط الأنظمة والأدوات الرقمية لإدارة المشاريع مع أنظمة متابعة الخطط الإستراتيجية والمبادرات، والأنظمة المالية والمشتريات، والأنظمة الرقابية والمحاسبية، وأنظمة الموارد البشرية في الجهة."],
  ["5.11.2-3", "ضبط الصلاحيات الخاصة بفريق إدارة المشروع والإدارات الأخرى التي ينتمون لها من خلال النظام التقني المستخدم."],
  ["5.11.2-4", "إصدار تقارير دورية تظهر مراقبة معالم ومخرجات المشاريع في الجهة يتم من خلالها توضيح نسبة إنجاز كل معلم ومخرج."],
  ["5.11.3", "استخدام نظم إدارة الوثائق والأرشفة الرقمية", "الهدف: ربط واستخدام نظم إدارة الوثائق والأرشفة لجميع التعاملات، وضمان حفظ الوثائق والبيانات وسرعة الوصول إليها.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• الأمر السامي رقم (57231) وتاريخ 10/11/1439 هـ، البند (أولًا).\n• قرار مجلس الوزراء رقم (40) وتاريخ 27/2/1427 هـ، البند (3).\n• قرار مجلس الوزراء رقم (555) وتاريخ 23/9/1440 هـ، الفقرة الفرعية (أ) من الفقرة (1) من البند (خامسا).", "1) إرفاق ما يثبت اعتماد سياسات الحفظ والإتلاف في الجهة، والمتوائمة مع سياسات المركز الوطني للوثائق والمحفوظات وما يثبت مشاركتها مع منسوبي الجهة.\n2) إرفاق (3) عينات حديثة من شاشات أنظمة حفظ الوثائق والأرشفة المستخدمة في الجهة.\n3) إرفاق عينات كافية توضح جميع عمليات الربط والتكامل بين نظام إدارة الوثائق والأرشفة وجميع الأنظمة الرقمية الأساسية والداعمة، وضبط الصلاحيات.\n4) إرفاق تقارير حديثة من نظام إدارة الوثائق والأرشفة تظهر نسب استفادة الإدارات من النظام."],
  ["5.11.3-1", "اعتماد سياسات الحفظ والإتلاف الخاصة بالمركز الوطني للوثائق والمحفوظات، وتطوير ما يلزم لضمان توافقها مع الأنظمة والإجراءات المتبعة في الجهة."],
  ["5.11.3-2", "حفظ وأرشفة وثائق الجهة ومستنداتها وعقودها وقراراتها وخطاباتها وبياناتها إلكترونًّيا."],
  ["5.11.3-3", "ربط نظام إدارة الوثائق والأرشفة بجميع الأنظمة الرقمية الأساسية والداعمة، وضبط الصلاحيات."],
  ["5.11.3-4", "إصدار تقارير دورية من نظم إدارة الوثائق والأرشفة تظهر نسب استفادة الإدارات من النظام."],
  ["5.11.4", "استخدام النظم الرقمية لإدارة العلاقة مع المستفيدين", "الهدف: تطوير وتوثيق عمليات التواصل مع المستفيدين عبر القنوات المختلفة ومتابعة سير تلك الطلبات والملاحظات لمعالجتها في أسرع وقت.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البند (17).", "1) إرفاق (3) عينات حديثة من شاشات نظم إدارة العلاقة مع المستفيدين.\n2) إرفاق (3) عينات حديثة لتذاكر فُِتحت عبر عدة قنوات مختلفة.\n3) إرفاق (3) عينات حديثة من الأدوات الرقمية للتفاعل مع المستفيد.\n4) إرفاق (3) عينات حديثة من قاعدة المعرفة المستخدمة في دعم وصول مسؤول العلاقة إلى المعلومة بطريقة سلسة وسريعة."],
  ["5.11.4-1", "استخدام نظم إدارة العلاقة مع المستفيدين بجميع مكوناتها وتفعيل مراكز الاتصال والدعم الفني، بما يضمن رفع مستوى الاستجابة السريعة لمتطلبات وشكاوى ومقترحات المستفيدين باختلاف شرائحهم، ورفع مستوى الرضا لديهم."],
  ["5.11.4-2", "ربط نظم إدارة العلاقة مع المستفيدين بنظم إدارة البنية التحتية وقنوات التواصل مع المستفيدين، ونظم تجارب العملاء."],
  ["5.11.4-3", "تفعيل الأدوات الرقمية لأتمتة عمليات الدعم والاستجابة السريعة."],
  ["5.11.4-4", "تفعيل أدوات إدارة المعرفة، لدعم وصول مسؤول العلاقة إلى المعلومة بطريقة سلسة وسريعة."],
  ["5.11.5", "استخدام البريد الإلكتروني", "الهدف: تفعيل دور التعاملات والمراسلات الرقمية في أعمال الجهات الحكومية الاعتيادية والمخاطبات، وضمان سريتها.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• قرار مجلس الوزراء رقم (40) وتاريخ 27/2/1427 هـ، البند (13).\n• قرار مجلس الوزراء رقم (555) وتاريخ 23/9/1440 هـ، الفقرات (1،3،4،5،6) من البند (ثالثًا).\n• تعميم هيئة الحكومة الرقمية رقم (2026) وتاريخ 14/9/1445 هـ، البند (ثانيًا).", "1) تقديم تقرير حديث لآخر (6) أشهر من خادم البريد الإلكتروني الخاص بالجهة يوضح عدد الرسائل.\n2) تقديم صورة حديثة من بيان إخلاء المسؤولية الذي ضُِّمن في رسائل البريد الإلكتروني الخاصة بمنسوبي الجهة.\n3) لا يتطلب إرفاق مستند إثبات، وسيتم التحقق داخلًّيا من حالة الاستضافة."],
  ["5.11.5-1", "رفع نسب استخدام البريد الإلكتروني في المراسلات اليومية."],
  ["5.11.5-2", "تضمين رسائل البريد الإلكتروني بيان إخلاء المسؤولية المتعلقة بمحتويات البريد الإلكتروني الحكومي العام أو الخاص."],
  ["5.11.5-3", "استضافة خوادم البريد الإلكتروني الحكومي داخل المملكة."],
  ["5.12", "البنية التحتية للخدمات التقنية", "يشمل المحور معايير ومتطلبات تطبيق منهجية مؤسسية تتضّمن مجموعة من السياسات والإجراءات والأساليب الخاصة بتقديم الخدمات التقنية للمستفيدين."],
  ["5.12.1", "تطوير إدارة الخدمات التقنية", "الهدف: تطوير السياسات والمعايير والأهداف والعمليات المتعلقة بإدارة الخدمات التقنية وإدارة البنية التحتية، وضمان الاستخدام الأمثل للموارد التقنية.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• الأمر السامي رقم (48310) وتاريخ 26/11/1435 هـ، الفقرة (1).\n• قرار مجلس الوزراء رقم (555) وتاريخ 23/9/1440 هـ، البند (خامسًا) والفقرة (1) من البند (سادسًا).\n• تعميم هيئة الحكومة الرقمية رقم (1189) وتاريخ 13/4/1446هـ.", "1) إرفاق الوثائق التي تثبت أن الجهة التزمت بتطوير الأهداف ونطاق العمل لنظام إدارة الخدمات التقنية والبنية التحتية.\n2) إرفاق سياسات تقنية المعلومات المعتمدة التي تحقق متطلبات تطبيق هذا المعيار، وما يثبت مشاركتها مع المنسوبين.\n3) إرفاق الهيكل التنظيمي المعتمد للإدارة العامة لتقنية المعلومات يوضح إنشاء وحدة مختصة بالجودة الشاملة.\n4) إرفاق وثيقة اتفاقيات مستوى الخدمة التشغيلية المعتمدة التي تحقق متطلبات تطبيق هذا المعيار، و (3) عينات من صور الشاشات التي توضح تطويرها ضمن أنظمة الجهة، وفق متطلبات تطبيق هذا المعيار.\n5) إرفاق سياسات ضبط استعمال المنسوبين للأصول التقنية في الجهة، وما يثبت مشاركتها مع الموظفين.\n6) إرفاق وثيقة ضوابط وقواعد استخدام المنسوبين لأجهزتهم الشخصية لأغراض العمل، وما يثبت مشاركتها مع المنسوبين."],
  ["5.12.1-1", "تطوير الأهداف ونطاق العمل لنظام إدارة الخدمات التقنية والبنية التحتية بما يحقق الأهداف الإستراتيجية للجهة في عملية التحول الرقمي."],
  ["5.12.1-2", "إصدار سياسات تقنية المعلومات وحوكمتها وفق أفضل الممارسات العالمية مثل:(ISO20000)،(ITIL)؛ بما يشمل إدارة الخدمات التقنية والبنية التحتية، واعتمادها وتعميمها على مستوى الجهة."],
  ["5.12.1-3", "إنشاء وحدة إدارية للجودة الشاملة تختص بقياس ومراقبة جودة عمليات تقنية المعلومات وإدارة البنية التحتية."],
  ["5.12.1-4", "تحديد واعتماد اتفاقيات مستوى الخدمة التشغيلية بما يشمل الاتفاقيات مع الأطراف الخارجية ومزودي الخدمات، وتحديد المستهدفات ومؤشرات الأداء، والأدوار والمسؤوليات ذات العلاقة؛ لضمان خضوعها للمتابعة والتقويم الدوري عبر وحدة الجودة أو الإدارات المختصة."],
  ["5.12.1-5", "اعتماد سياسات رسمية وفنية لضبط استعمال الموظفين للأصول التقنية في الجهة ومشاركتها مع منسوبي الجهة."],
  ["5.12.1-6", "اعتماد ضوابط وقواعد لاستخدام منسوبي الجهة لأجهزتهم الشخصية لأغراض العمل ومشاركتها مع منسوبي الجهة."],
  ["5.12.2", "تنفيذ ومتابعة أعمال إدارة الخدمات التقنية", "الهدف: متابعة ومراقبة تطبيق المعايير والسياسات لإدارة الخدمات التقنية.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• قرار مجلس الوزراء رقم (555) وتـاريخ 23/9/1440 هـــــــ، الفقرة (3) من البنـد (ثـانيـًا) والفقرة (2) من البنـد (سادسًا).\n• تعميم هيئة الحكومة الرقمية رقم (2026) وتاريخ 14/9/1445 هـ، البند (ثانيًا).\n• تعميم هيئة الحكومة الرقمية رقم (1189) وتاريخ 13/4/1446هـ.", "1) إرفاق الوثائق والعينات الكافية من شاشات الأنظمة التي تثبت التزام الجهة بأتمتة جميع عمليات إدارة الخدمات التقنية والبنية التحتية، مع توضيح التقنيات والأنظمة الحديثة المستخدمة.\n2) إرفاق الوثائق التي توضح توثيق نتائج جميع مراحل تطوير التقنيات الداعمة لأعمال الحكومة الرقمية ومخرجاتها، وحفظها لتكون مرجعًا لأي تطوير لاحق.\n3) ارفاق مؤشرات الأداء الرئيسية المعتمدة والتقارير الدورية التي تقيس أداء عمليات إدارة الخدمات التقنية والبنية التحتية وتوضح دراستها وتحليلها.\n4) إرفاق ما يثبت متابعة فعالية اتفاقيات مستوى الخدمة التشغيلية الداخلية وقياسها وتقييمها بشكل دوري.\n5) لا يتطلب إرفاق مستند إثبات، وسيتم التحقق داخلًّيا من حالة الاستضافة.\n6) إرفاق الآلية المعتمدة، ومايثبت مشاركتها مع المنسوبين وصورة من شاشات الأنظمة المستخدمة في الجهة، التي تضمن من خلالها التزام المستخدمين بالضوابط المعتمدة فيما يتعلق باستخدام الأصول التقنية وأجهزة الحاسب الآلي في الجهة، ومنع استخدام البرامج غير المرخصة.\n7) إرفاق خطط التدقيق المعتمدة، وفق متطلبات تطبيق هذا المعيار."],
  ["5.12.2-1", "أتمتة جميع عمليات إدارة الخدمات التقنية والبنية التحتية بالاستفادة من التقنيات والأنظمة الحديثة في هذا المجال."],
  ["5.12.2-2", "توثيق نتائج جميع مراحل تطوير التقنيات الداعمة لأعمال الحكومة الرقمية والاحتفاظ بها كمرجعية لعمليات التطوير والتحسين المستمر."],
  ["5.12.2-3", "متابعة مؤشرات قياس الأداء الرئيسية لحوكمة تقنية المعلومات المطورة وفق ضوابط حوكمة تقنية المعلومات الصادرة من الهيئة، وإصدار تقارير الأداء الدورية."],
  ["5.12.2-4", "متابعة فعالية اتفاقيات مستوى الخدمة التشغيلية الداخلية وقياسها وتقييمها بشكل دوري (سنويًا على الأقل)."],
  ["5.12.2-5", "استضافة مواقع الجهة الإلكترونية ونطاقاتها وأنظمتها ومعلوماتها وخدماتها داخل المملكة."],
  ["5.12.2-6", "وضع الضوابط والقيود الإلكترونية التي تحد من تحميل منسوبي الجهة ملفات شخصية كبيرة، أو برامج غير معتمدة إلا حسب ما يتوافق مع اللوائح ذات العلاقة، ومشاركتها مع منسوبي الجهة."],
  ["5.12.2-7", "تطوير وتنفيذ خطة تدقيق داخلي على تقنية المعلومات وفقًا لضوابط حوكمة تقنية المعلومات الصادرة من الهيئة ووضع خطة معالجة بشأنها واعتمادها من أصحاب الصلاحية فـي الجهـة."],
  ["5.12.3", "تكامل إدارة الخدمات التقنية مع الأنظمة الأخرى", "الهدف: تحقيق التكامل بين أنظمة إدارة الخدمات التقنية والبنية التحتية والأنظمة الداخلية في الجهة.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البندان (1) و(18).\n• قرار مجلس الوزراء رقم (40) وتاريخ 27/2/1427 هـ، البند (5).", "1) إرفاق الوثائق والعينات اللازمة من شاشات الأنظمة والتقارير الدورية التي تثبت أن الجهة قد التزمت بتحقيق التكامل بين أنظمة إدارة الخدمات التقنية والأنظمة الأخرى في الجهة.\n2) إرفاق الوثائق والعينات اللازمة من شاشات الأنظمة والتقارير الدورية التي تثبت أن الجهة قد التزمت بتحقيق التكامل الداخلي بين الأنظمة التقنية، وتوضح مراقبة مؤشرات الأداء لعملية التكامل.\n3) إرفاق الوثائق التي توضح أن الجهة قامت بتحقيق التكامل مع الجهات الحكومية الأخرى في أعمال الحكومة الرقمية، وفق متطلبات تطبيق هذا المعيار."],
  ["5.12.3-1", "تحقيق التكامل بين السياسات والعمليات في أنظمة إدارة الخدمات التقنية والبنية التحتية وأنظمة الإدارات الأخرى مثل: إدارات الجودة، وأمن المعلومات، واستمرارية الأعمال، والبيانات."],
  ["5.12.3-2", "تحقيق التكامل الداخلي بين الأنظمة التقنية والعمل على مراقبة مؤشرات الأداء والتقارير الدورية لعملية التكامل."],
  ["5.12.3-3", "العمل بشكل مترابط ومتكامل مع الجهات الحكومية الأخرى، لتحقيق التكامل بين أعمال الحكومة الرقمية، وبما يتوافق مع متطلبات واحتياجات المستفيدين ويتواءم مع التنظيمات الصادرة عن الهيئة."],
  ["5.12.4", "تطبيق قواعد تنظيم البرمجيات الحكومية الحرة ومفتوحة المصدر", "الهدف: تعزيز فرص إعادة استخدام البرمجيات الحكومية، مع إتاحة فرصة الاطلاع على الشفرة المصدرية ونشرها، بما يفتح مجال التعاون بين الجهات الحكومية، ويوحد المعايير فيما بينها، ويزيد الشفافية، ويحد من احتكار الموّردين، ويقلل صعوبات دمج البرمجيات من أكثر من مصدر.\n\nالنطاق: جميع الجهات الحكومية. بحسب ما هو مقرر في أنظمتها أو تنظيماتها أو لوائحها الداخلية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• قرار مجلس الوزراء رقم (14) وتاريخ 2/1/1443هـ.", "مستندات مطلوبة من جميع الجهات الحكومية:\n1) إرفاق وثيقة حصر البرمجيات المستخدمة لدى الجهة بما فيها البرمجيات الحكومية الحرة ومفتوحة المصدر، وفق متطلبات تطبيق هذا المعيار.\nمستندات مطلوبة من جميع الجهات الحكومية – باستثناء الجهات الأمنية والعسكرية التي تخضع لأحكام خاصة بها- بحسب ما هو مقرر في أنظمتها أو تنظيماتها أو لوائحها الداخلية.:\n2) لا يتطلب ارفاق مستند اثبات وسيتم التحقق داخليًا.\n3) إرفاق خطة الإيداع للبرمجيات الحكومية مفتوحة المصـدر بصـيغة \"اكسـل\" بحيث تشـمل اسـم البرمجية، ووصف البرمجية، وتاريخ الإيداع المستهدف.\n4) لا يتطلـب إرفـاق مســـتنـد إثبـات، وســـيتم التحقق داخليـًا من نســـبـة الإيـداع في مســـتودع البرمجيـات الحكومية.\n5) إرفاق تقرير بقائمة البرمجيات مفتوحة المصــدر المعاد اســتخدامها وفق متطلبات تطبيق هذا المعيار مدعومًا بـصور الشاشات، مع توضيح مستوى الانتفاع والأثر المحقق لكل برمجية.\n6) إرفاق تقرير بالبرمجيات مغلقة المصـــدر التي تم اســـتبدالها مع تحديد المنتج مفتوح المصـــدر الحالي وفق متطلبات تطبيق هذا المعيار مدعومًا بصور الشاشات وتوضيح مستوى أثر الاستبدال المحقق.\n7) إرفاق سياسات الشراء الرقمي المعتمدة، موضحة بها الإجراءات المتعلقة بشراء أو تطوير البرمجيات.\n8) إرفاق ما يثبت تطبيق الآلية والإجراءات لشــراء أو تطوير البرمجيات عبر الخدمات المتاحة على المنصــة الرقمية لإيداع البرمجيات الحكومية وفق متطلبات تطبيق هذا المعيار.\n9) إرفاق عينة للعقود المبرمة لبناء البرمجيات الحكومية متضـمنة الاشـتراطات والبنود المطلوبة بصـيغة تعاقدية واضحة وفق متطلبات تطبيق المعيار.\n10) إرفاق قرارات التكليف التي توضـح اسـتعداد الجهة وتهيئتها لإداراتها للتفاعل مع مجتمع المعلومات من خلال عدد المساهمين من الجهة الحكومية لمستودع البرمجيات الحكومية.\n11) إرفاق ما يثبت إتاحة الجهة للشفرة المصدرية عبر منصة مستودع البرمجيات الحكومية وفق متطلبات تطبيق هذا المعيار.\n12) لا يتطلب ارفاق مستند اثبات، وسيتم التحقق داخليا من خلال قوائم التحقق الداخلية."],
  ["5.12.4-1", "حصر قائمة أصول البرمجيات لدى الجهة الحكومية بما فيها البرمجيات مفتوحة المصدر، بحيث تشمل بيانات الحصر العناصر التالية: اسم البرمجيات، نوع البرمجيات (مفتوح المصدر، ومغلق المصدر)، والوصف، ولغة البرمجة، ورخص الاستخدام، وإمكانية المشاركة مع مستودع البرمجيات الحكومية، والجدولة لرفعها للمستودع في حال أنها مفتوحة المصدر.", "متطلبات على جميع الجهات الحكومية"],
  ["5.12.4-2", "إصدار الرخصة الحكومية للبرمجيات الحرة ومفتوحة المصدر.", "متطلبات على جميع الجهات الحكومية – باستثناء الجهات الأمنية والعسكرية التي تخضع لأحكام خاصة بها بحسب ما هو مقرر في أنظمتها أو تنظيماتها أو لوائحها الداخلية."],
  ["5.12.4-3", "إعداد خطة إيداع البرمجيات مفتوحة المصدر للسنوات الثلاث القادمة، لكافة البرمجيات التي طورت داخليا أو تعاقدت الجهة أو الشركات المملوكة لها على تطويرها عن طريق مورد محلي أو دولي.", "متطلبات على جميع الجهات الحكومية – باستثناء الجهات الأمنية والعسكرية التي تخضع لأحكام خاصة بها بحسب ما هو مقرر في أنظمتها أو تنظيماتها أو لوائحها الداخلية."],
  ["5.12.4-4", "إيداع مالا يقل عن (20%) من البرمجيات المحصورة في مستودع البرمجيات الحكومية.", "متطلبات على جميع الجهات الحكومية – باستثناء الجهات الأمنية والعسكرية التي تخضع لأحكام خاصة بها بحسب ما هو مقرر في أنظمتها أو تنظيماتها أو لوائحها الداخلية."],
  ["5.12.4-5", "إعادة استخدام البرمجيات الحكومية الحرة مفتوحة المصدر المودعة من جهات حكومية أخرى وتوثيق ذلك من خلال مستودع البرمجيات الحكومية، بحيث لا تكون مكررة ولم يتم تقديمها في دورات قياس السابقة.", "متطلبات على جميع الجهات الحكومية – باستثناء الجهات الأمنية والعسكرية التي تخضع لأحكام خاصة بها بحسب ما هو مقرر في أنظمتها أو تنظيماتها أو لوائحها الداخلية."],
  ["5.12.4-6", "استبدال برمجيات مغلقة المصدر (منتج يتطلب رخص) بمنتجات مفتوحة المصدر أو لمزودي خدمة محليين أو منتجات حكومية سحابية.", "متطلبات على جميع الجهات الحكومية – باستثناء الجهات الأمنية والعسكرية التي تخضع لأحكام خاصة بها بحسب ما هو مقرر في أنظمتها أو تنظيماتها أو لوائحها الداخلية."],
  ["5.12.4-7", "تقديم سياسات الشراء الرقمي المعتمدة، موضَّحة بها الإجراءات المتعلقة بشراء أو تطوير البرمجيات.", "متطلبات على جميع الجهات الحكومية – باستثناء الجهات الأمنية والعسكرية التي تخضع لأحكام خاصة بها بحسب ما هو مقرر في أنظمتها أو تنظيماتها أو لوائحها الداخلية."],
  ["5.12.4-8", "تطبيق الآلية المعتمدة لشراء أو تطوير البرمجيات الحكومية، وذلك حسب الخطوات الآتية:", "أ. الخطوة الأولى: تقييم ودراسة البرمجيات الحكومية المتوفرة في المستودع لاستخدامها، بالتنسيق مع الهيئة.\nب. الخطوة الثانية: في حال أفاد التقييم والدراسة بعدم توفر برمجيات تلبي الحاجة؛ فإن للجهة الحكومية البحث عن برمجيات بالتنسيق مع الهيئة.\nت. الخطوة الثالثة: إن لم يكن هناك ما يلبي الحاجة؛ فبإمكان الجهة الحكومية بناء برمجيات خاصة بها.\nمتطلبات على جميع الجهات الحكومية – باستثناء الجهات الأمنية والعسكرية التي تخضع لأحكام خاصة بها بحسب ما هو مقرر في أنظمتها أو تنظيماتها أو لوائحها الداخلية."],
  ["5.12.4-9", "تطبيق الأحكام والقواعد المتعلقة بالتعاقد لبناء البرمجيات الحكومية، مع مراعاة النقاط الآتية عند التعاقد:", "أ. يجب على المورد تسليم الشفرة المصدرية والمستندات المتعلقة بها إلى الجهة الحكومية.\nب. يجب ضمان حقوق غير محدودة للشفرة المصدرية ومتعلقاتها، بما يتيح إعادة الاستخدام والنسخ والتعديل والتوزيع بين الجهات الحكومية، دون الحاجة إلى المورد الأصلي، مع توفير مصدر مفتوح للاستفادة العامة من الشفرة المصدرية لجميع الجهات الحكومية.\nت. يجب أن يكون المورد حاصلًا على شهادات ذات مستوى عاٍل في الجودة في مجال العمل المطلوب لبناء البرمجيات.\nث. ينبغي إعطاء الأولوية في التعاقد للموردين الوطنيين الذين يتوافر لديهم الطلبات والشروط الفنية للجهة الحكومية.\nج. عند إجراء تطوير إضافي على البرمجيات التجارية التي تم شراؤها، يجب على الجهات الحكومية التأكيد في العقد على أن تؤول ملكية أو حق استخدام هذا التطوير للحكومة.\nمتطلبات على جميع الجهات الحكومية – باستثناء الجهات الأمنية والعسكرية التي تخضع لأحكام خاصة بها بحسب ما هو مقرر في أنظمتها أو تنظيماتها أو لوائحها الداخلية."],
  ["5.12.4-10", "تكليف الإدارات المعنية بالبرمجيات مفتوحة المصدر للتفاعل مع منصة مستودع البرمجيات الحكومية.", "متطلبات على جميع الجهات الحكومية – باستثناء الجهات الأمنية والعسكرية التي تخضع لأحكام خاصة بها بحسب ما هو مقرر في أنظمتها أو تنظيماتها أو لوائحها الداخلية."],
  ["5.12.4-11", "عند إتاحة أي جهة حكومية للشفرة المصدرية عبر منصة مستودع البرمجيات الحكومية العمل بالآتي:", "أ. استقبال مقترحات التعديل والإضافة على تلك الشفرة المصدرية.\nب. طرح التحديات والمشكلات المتعلقة بالأنظمة التي تستخدمها الجهات الحكومية لمجتمع البرمجيات الحرة ومفتوحة المصدر.\nت. تشجيع الموظفين في الجهات الحكومية للمساهمة في تطوير البرمجيات الحكومية.\nمتطلبات على جميع الجهات الحكومية – باستثناء الجهات الأمنية والعسكرية التي تخضع لأحكام خاصة بها بحسب ما هو مقرر في أنظمتها أو تنظيماتها أو لوائحها الداخلية."],
  ["5.12.4-12", "نشر (100%) من البرمجيات المودعة في منصة مستودع البرمجيات الحكومية، بما يتوافق مع متطلبات النشر في المنصة.", "متطلبات على جميع الجهات الحكومية – باستثناء الجهات الأمنية والعسكرية التي تخضع لأحكام خاصة بها بحسب ما هو مقرر في أنظمتها أو تنظيماتها أو لوائحها الداخلية."],
  ["5.13", "البنية السحابية", "يشمل المحور معايير ومتطلبات استخدام الموارد والتطبيقات والعمليات السحابية الملائمة لأعمال الجهة الحالية والمستقبلية."],
  ["5.13.1", "تأسيس وتمكين وحدة للحوسبة السحابية", "الهدف: تأسيس وحدة للحوسبة السحابية لقيادة الجهة خلال عملية تبني خدمات الحوسبة السحابية والانتقال إليها، إضافًة إلى تمكينها لإدارة جميع العمليات ذات الصلة.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البندان (1) و(18).\n• تعميم الديوان الملكي رقم (58071) وتاريخ 9/8/1445 هـ، البند (ثانيًا).\n• قرار مجلس الوزراء رقم (555) وتاريخ 23/9/1440هـ، البند (رابعًا).\n• تعميم هيئة الحكومة الرقمية رقم (2026) وتاريخ 14/9/1445 هـ، البند (ثانيًا).", "مستندات مطلوبة من جميع الجهات الحكومية:\n1) إرفاق قرار معتمد من المسؤول الأول بالجهة بإنشاء وحدة للحوسبة السحابية أو الهيكل التنظيمي المعتمد يوضح إنشاء الوحدة، وقرار تعيين المسؤول لها.\n2) إرفاق وثيقة الإطار التنظيمي للوحدة وفق متطلبات تطبيق هذا المعيار.\nمستندات مطلوبة من جميع الجهات الحكومية باستثناء الجهات الأمنية والعسكرية:\n3) إرفاق قرار معتمد لتعيين أعضاء فريق العمل يشمل المسمى الوظيفي لكل عضو.\n4) إرفاق قرار معتمد لتشكيل لجنة حوكمة وحدة الحوسبة السحابية وآلية عملها وفق متطلبات تطبيق هذا المعيار.\n5) إرفاق وثيقة السياسات والإجراءات المعتمدة لإدارة وتشغيل وحدة الحوسبة السحابية وفق متطلبات تطبيق هذا المعيار.\n6) إرفاق تقارير دورية معتمدة توضح مؤشرات الأداء الرئيسية والتشغيلية للوحدة ومستوى التقدم.\n7) إرفاق خطة التدريب المعتمدة لأعضاء فريق العمل في وحدة الحوسبة السحابية وفق متطلبات تطبيق هذا المعيار."],
  ["5.13.1-1", "تأسيس وحدة للحوسبة السحابية في الجهة وتعيين مسؤول لها.", "متطلبات على جميع الجهات الحكومية"],
  ["5.13.1-2", "إعداد إطار تنظيمي للوحدة بحيث يشمل الوصف التفصيلي للهيكل التنظيمي والتسلسل الإداري، ويحدد الأدوار والمسؤوليات للوحدة، بما يشمل:", "أ. تحديد المسميات الوظيفية لوحدة الحوسبة السحابية.\nب. إعداد نموذج التفاعل بين وحدة الحوسبة السحابية والوحدات الإدارية/التنظيمية الأخرى للجهة عبر تحديد الإجراءات التشغيلية المشتركة.\nمتطلبات على جميع الجهات الحكومية"],
  ["5.13.1-3", "تعيين أعضاء فريق العمل لوحدة الحوسبة السحابية وفقًا للمسميات المعتمدة في الإطار التنظيمي.", "متطلبات على جميع الجهات الحكومية باستثناء الجهات الأمنية والعسكرية"],
  ["5.13.1-4", "تشكيل لجنة حوكمة وحدة الحوسبة السحابية وتوضيح آلية عملها في إدارة وتفعيل أعمال تبني الحوسبة السحابية بما يشمل مراجعة واعتماد خطط التحول السحابي، إقرار سياسات الحوكمة السحابية، تقييم الأداء الدوري لأعمال ومهام التبني السحابي.", "متطلبات على جميع الجهات الحكومية باستثناء الجهات الأمنية والعسكرية"],
  ["5.13.1-5", "إعداد سياسات وإجراءات إدارة وتشغيل مهام وحدة الحوسبة السحابية بما يتواءم مع التنظيمات الصادرة من هيئة الحكومة الرقمية والجهات ذات العلاقة بالحوسبة السحابية بما يشمل بحد أدنى:", "أ. تصنيف البيانات وحوكمتها على البيئة السحابية.\nب. الأمن السيبراني على البيئة السحابية.\nت. الإنفاق ومراقبة الميزانية السحابية.\nث. إنشاء وتخصيص الموارد السحابية.\nج. تشغيل وإدارة البيئة السحابية.\nمتطلبات على جميع الجهات الحكومية باستثناء الجهات الأمنية والعسكرية"],
  ["5.13.1-6", "تحديد ومتابعة مؤشرات الأداء الرئيسية والتشغيلية لأعمال وحدة الحوسبة السحابية وإصدار تقارير دورية بحالة التقدم.", "متطلبات على جميع الجهات الحكومية باستثناء الجهات الأمنية والعسكرية"],
  ["5.13.1-7", "إعداد خطة تدريب أعضاء فريق العمل في الوحدة السحابية بما يشمل مسارات التطوير المهني في مجالات الحوسبة السحابية، والجدول الزمني للتدريب، والأعضاء المستهدفين، ومستوى الإنجاز.", "متطلبات على جميع الجهات الحكومية باستثناء الجهات الأمنية والعسكرية"],
  ["5.13.2", "إعداد وتنفيذ خطة لتبني الحوسبة السحابية", "الهدف: تعزيز وترسيخ تبني الخدمات السحابية ودمج مراكز البيانات من قَِبل الجهات الحكومية.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (58071) وتاريخ 9/8/1445 هـ، البند (ثانيًا).\n• قرار مجلس الوزراء رقم (555) وتاريخ 23/9/1440هـ، البند (رابعًا).\n• تعميم هيئة الحكومة الرقمية رقم (2026) وتاريخ 14/9/1445 هـ، البند (ثانيًا).\n• تعميم هيئة الحكومة الرقمية رقم (102) وتاريخ 9/2/1444 هـ بشأن العمل على إعداد خطة للتحول نحو الحلول السحابية.", "مستندات مطلوبة من جميع الجهات الحكومية:\n1) إرفاق التقارير التي تثبت تحقيق مستهدف نسبة التبني لعام (2025م) بما لا يقل عن (50%).\n2) إرفاق خطة معتمدة ومحدثة لتبني الحوسبة السحابية لمدة لا تقل عن سنتين، وفق متطلبات تطبيق هذا المعيار.\nمستندات مطلوبة من جميع الجهات الحكومية باستثناء الجهات الأمنية والعسكرية:\n3) إرفاق قائمة معتمدة بمشاريع تنفيذ خطة التحول السحابي لسنة (2026م –2027م)، وفق متطلبات تطبيق هذا المعيار.\n4) إرفاق التقارير التي توضح نسبة الإنجاز في تنفيذ خطة تبني الحوسبة السحابية وفق متطلبات تطبيق هذا المعيار.\n5) إرفاق وثيقة دراسة وتحليل مخاطر خطة تبني الحوسبة السحابية وفق متطلبات تطبيق هذا المعيار.\n6) لا يتطلب إرفاق مستند إثبات، وسيتم التحقق من حصر الاحتياج الحكومي للخدمات السحابية من خلال منصة \"رقمي\"."],
  ["5.13.2-1", "إعداد تقرير تفصيلي يوضح تحقيق النسبة المستهدفة للتحول السحابي لعام (2025م) بما لا يقل عن (%50).", "متطلبات على جميع الجهات الحكومية"],
  ["5.13.2-2", "إعداد أو تحديث خطة تبني الحوسبة السحابية (الانتقال الى السحابة/ تحسين وتطوير الخدمات على السحابة) لمدة لا تقل عن سنتين (2026م –2027م)، بحيث تشمل ما يأتي:", "أ. تحديد نطاق العمل، ومؤشرات قياس الأهداف الإستراتيجية للتحول السحابي, على سبيل المثال لا الحصر، تحسين الكفاءة التشغيلية وتقليل التكاليف، المرونة والقدرة على التوسع، تعزيز الأمان والامتثال، تسريع تقديم الخدمات ورفع جودة تجربة المستخدم.\nب. حصر قائمة بكافة أعباء العمل للجهة وحالة استضافتها في (البيئات الداخلية أو على البيئات السحابية) مع توضيح حجم الموارد المخصصة لها من وحدات معالجة وذاكرة عشوائية وتخزين.\nت. إعداد خطة ترحيل لنقل أعباء العمل إلى بيئة الحوسبة السحابية موضحًا فيها المدة الزمنية للترحيل والتواريخ المستهدفة.\nث. وضع خط أساس لاحتساب نسبة تبني الحوسبة السحابية الحالية بناًء على حجم الموارد (البنية التحتية، المنصات، التطبيقات) المستضافة على البيئات السحابية ومقارنتها بحجم الموارد المستضافة على البيئات الداخلية.\nج. تحديد نسبة مستهدفة للتحول إلى الحوسبة السحابية بحيث تصل نسبة الموارد التقنية المستضافة على البيئات السحابية إلى (60%) كحد أدنى بنهاية عام (2026م)، و(70%) بحلول عام (2027م).\nمتطلبات على جميع الجهات الحكومية"],
  ["5.13.2-3", "تحديد قائمة بمشاريع تنفيذ خطة التحول السحابي لسنة (2026م –2027م)، بحسب الآلية الآتية:", "أ. قائمة المشاريع المرتبطة بتنفيذ خطة تبني الحوسبة السحابية.\nب. وصف لنطاق العمل بشكل عام لكل مشروع بحيث يوضح فيه الأهداف والمخرجات.\nت. الإطار الزمني لتنفيذ كافة المشاريع المرتبطة بتنفيذ خطة تبني الحوسبة السحابية.\nث. إجمالي ميزانيات المشاريع المرتبطة بتنفيذ خطة التبني السحابي.\nج. إعداد دراسة جدوى مالية وتشغيلية لأعباء العمل المستضافة على البيئة التقليدية لنقلها للبيئة السحابية للمشاريع التي سيتم تنفيذها عام (2026م –2027م)، بحيث تشمل على دراسات وتحليل لـ (الوضع الحالي للبنية التحتية والخدمات، تكاليف الترحيل والتشغيل المستقبلي على السحابة، والفوائد والعوائد المتوقعة مثل \"خفض التكاليف\" و\"تحسين الأداء\"، وخيارات الترحيل الجزئي أو الكلي أو الإبقاء على الوضع الحالي، والمخاطر المحتملة وإجراءات التخفيف).\nمتطلبات على جميع الجهات الحكومية باستثناء الجهات الأمنية والعسكرية"],
  ["5.13.2-4", "تنفيذ خطة تبني الحوسبة السحابية وإعداد تقارير الإنجاز بما يشمل:", "أ. حالة تقدم مستهدف رفع نسبة التبني السحابي وترحيل التطبيقات والخدمات.\nب. حالة تقدم تنفيذ المشاريع المرتبطة بخطة تبني الحوسبة السحابية.\nمتطلبات على جميع الجهات الحكومية باستثناء الجهات الأمنية والعسكرية"],
  ["5.13.2-5", "دراسة وتحليل مخاطر خطة تبني الحوسبة السحابية وإصدار القرارات والإجراءات التصحيحية.", "متطلبات على جميع الجهات الحكومية باستثناء الجهات الأمنية والعسكرية"],
  ["5.13.2-6", "تحديث بيانات استبانة \"حصر الاحتياج الحكومي للخدمات السحابية\" عبر منصة \"رقمي\" (page-external/login-https://digitalcircuitregistration.dga.gov.sa/ords/r/cloud_survey/survey).", "متطلبات على جميع الجهات الحكومية باستثناء الجهات الأمنية والعسكرية"],
  ["5.13.3", "تفعيل بيئة الحوسبة السحابية", "الهدف: تفعيل ومراقبة بيئة الحوسبة السحابية بما يضمن ترشيد التكلفة والاستهلاك.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البندان (1) و(18).\n• تعميم الديوان الملكي رقم (58071) وتاريخ 9/8/1445 هـ، البند (ثانيًا).\n• تعميم هيئة الحكومة الرقمية رقم (2026) وتاريخ 14/9/1445 هـ، البند (ثانيًا).", "مستندات مطلوبة من جميع الجهات الحكومية:\n1) إرفاق ما يثبت التزام الجهة بمواءمة سياساتها وتنظيماتها مع السياسات والضوابط والتنظيمات الصادرة من هيئة الحكومة الرقمية والجهات ذات العلاقة بالحوسبة السحابية.\n2) إرفاق العينات الكافية من شاشات الأدوات والأنظمة السحابية المستخدمة لتحسين الأداء وضمان استمرارية الأعمال وترشيد التكاليف ومتابعة المخاطر وفق متطلبات تطبيق هذا المعيار.\nمستندات مطلوبة من جميع الجهات الحكومية باستثناء الجهات الأمنية والعسكرية:\n3) إرفاق عينات من تقارير المراقبة الدورية المتعلقة بالاستخدام وإدارة المخاطر في بيئة الحوسبة السحابية بما يشمل دراستها وتحليلها، واتخاذ القرارات التصحيحية وفق متطلبات تطبيق هذا المعيار.\n4) إرفاق الوثائق التي توضح عقود الحوسبة السحابية من خارج الاتفاقية الإطارية (في حال وجود مشتريات من خارج الاتفاقية الإطارية) وأوامر الشراء من الاتفاقية الإطارية للحوسبة السحابية وفق متطلبات تطبيق هذا المعيار."],
  ["5.13.3-1", "مواءمة سياسات وتنظيمات الجهة مع السياسات والضوابط والتنظيمات الصادرة من هيئة الحكومة الرقمية والجهات ذات العلاقة بالحوسبة السحابية.", "متطلبات على جميع الجهات الحكومية"],
  ["5.13.3-2", "استخدام الأدوات والأنظمة السحابية لتحسين الأداء وضمان استمرارية الأعمال وترشيد التكاليف ومتابعة المخاطر بما يشمل:", "أ. أدوات مراقبة الأداء، والإنفاق على بيئة الحوسبة السحابية.\nب. أدوات إدارة المخاطر والحماية مثل: أدوات حماية الشبكة، وأدوات حماية الموارد، وأدوات حماية الوصول مثل:)VPN( وMFA().\nت. أدوات إدارة وصول وصلاحيات المستخدمين للبيئة السحابية، مثل:(توزيع أدوار المستخدمين, وسياسات وآليات الوصول والاستخدام).\nث. أدوات النسخ الاحتياطي والتعافي من الكوارث للأنظمة والبيانات.\nمتطلبات على جميع الجهات الحكومية"],
  ["5.13.3-3", "المراقبة الدورية للاستخدام والإنفاق وإدارة المخاطر في بيئة الحوسبة السحابية ودراستها وتحليلها ووضع الإجراءات التصحيحية بناء على النتائج، بما يشمل:", "أ. مراقبة استهلاك الموارد التقنية وقياس استخدام وحدات المعالجة (CPU)، والذاكرة (RAM)، والتخزين، وحركة الشبكة.\nب. مراقبة استخدام الخدمات السحابية وتوضيح عدد الخدمات النشطة والمستخدمة فعليًا من مزود الخدمة السحابي (مثل: قواعد البيانات، والحاويات وغيرها).\nت. مراقبة الأمن والامتثال وتوضيح مدى تطبيق سياسات الحماية داخل البيئة السحابية.\nث. إعداد التقارير الدورية المتعلقة بمراقبة الإنفاق والتكاليف في بيئة الحوسبة السحابية بما يعكس نسبة التبني المحققة لعام (2025م) ودراستها وتحليلها متضمنا حجم الإنفاق المحقق.\nمتطلبات على جميع الجهات الحكومية باستثناء الجهات الأمنية والعسكرية"],
  ["5.13.3-4", "حصر العقود من خارج الاتفاقية الإطارية إن وجدت، وأوامر الشراء من الاتفاقية الإطارية (السوق الإلكتروني على منصة اعتماد) للحوسبة السحابية موضحًا فيها الآتي:", "أ. الرقم المرجعي للعقود وأوامر الشراء.\nب. قيمة العقود وأوامر الشراء.\nت. مزود الخدمة المتعاقد.\nث. نوع الخدمات في العقود وأوامر الشراء.\nمتطلبات على جميع الجهات الحكومية باستثناء الجهات الأمنية والعسكرية"],
  ["P6", "الحكومة الشاملة"],
  ["5.14", "الأنظمة والخدمات المشتركة", "يشمل المحور معايير ومتطلبات تطبيق الأنظمة الإلكترونية والخدمات المقدمة من جهات حكومية؛ لتقديم خدمات وحلول حكومية مشتركة، يمكن الارتباط بها والاستفادة منها."],
  ["5.14.1", "التخطيط للارتباط بالأنظمة والخدمات المشتركة", "الهدف: الارتباط بالأنظمة والخدمات التي تقدمها الجهات الحكومية الأخرى، وتعزيز استخدام الجهات الحكومية، للحلول التقنية والبنى التحتية المشتركة.\n\nالنطاق: جميع الجهات الحكومية\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم هيئة الحكومة الرقمية رقم (1339) وتاريخ 15/11/1444هـ.\n• تعميم هيئة الحكومة الرقمية رقم (1711) وتاريخ 18/7/1447هـ.", "مستندات مطلوبة من جميع الجهات الحكومية:\n1) إرفاق التقارير التي توضح دراسة وتحليل الأنظمة والخدمات الحكومية الأخرى وتحديد احتياجات الجهة من البيانات والوظائف بشكل دوري.\n2) إرفاق خطة معتمدة للارتباط بالأنظمة والخدمات المشتركة تثبت التزام الجهة بدراسة وتحليل الأنظمة والخدمات الحكومية التي ترغب بالارتباط بها، والتخطيط لعملية الارتباط وفق متطلبات تطبيق هذا المعيار.\nمستندات مطلوبة من الجهات الحكومية المعنية والمحدَّدة في الملحق رقم (7.6):\n3) إرفاق وثيقة خطة تفعيل واستخدام تطبيق التراسل الفوري وفق متطلبات تطبيق هذا المعيار."],
  ["5.14.1-1", "دراسة وتحليل الأنظمة والخدمات الحكومية الأخرى وتحديد احتياجات الجهة من البيانات والوظائف بشكل دوري.", "متطلبات على جميع الجهات الحكومية"],
  ["5.14.1-2", "إعداد خطة الارتباط بالأنظمة والخدمات المشتركة وتحديثها بحيث تشمل الآتي:", "أ. قائمة بالأنظمة والخدمات المشتركة التي تم الارتباط بها، والتي سيتم الارتباط بها مستقبلًا.\nب. أهداف الجهة من عملية الارتباط بكل نظام أو خدمة.\nت. الخدمات التي سيتم تقديمها أو الاستفادة منها من خلال عملية الارتباط.\nث. مجاميع البيانات التي يمكن الاستفادة منها من عملية الارتباط.\nج. المسؤول عن عملية الارتباط سواء كان شخصًا أو لجنًة أو وحدة إدارية.\nح. الجدول الزمني لعملية الارتباط.\nخ. آلية لمتابعة تنفيذ خطة الارتباط ومؤشرات الأداء المخصصة لمتابعة عملية الارتباط.\nمتطلبات على جميع الجهات الحكومية"],
  ["5.14.1-3", "إعداد خطة لتفعيل واستخدام تطبيق التراسل الفوري الآمن الموحد لمنسوبي الجهة الحكومية لأغراض التواصل الحكومي.", "متطلبات على الجهات الحكومية المعنية والمحدَّدة في الملحق رقم (7.6)"],
  ["5.14.2", "تنفيذ الارتباط بالأنظمة والخدمات المشتركة", "الهدف: التأكد من تنفيذ الارتباط بالمنصات الحكومية المشتركة، وتعظيم الاستفادة منها، وتفعيل الموارد التقنية المشتركة في المنصات والتطبيقات الحكومية، لتقديم تجربة ميسرة للمستفيدين من الخدمات الرقمية الحكومية.\n\nالنطاق: تطبيق المتطلبات التالية (1)،(2)،(4)،(5)،(6) على جميع الجهات الحكومية، ويُستثَنى البنك المركزي السعودي من المتطلبين (4) و (5).\nتطبيق المتطلب رقم (3) على الجهات المحددة في الملحق (7.6.1).\nتطبيق المتطلبات من (7) إلى (10) على المنصات التالية:\nمنصات وزارة المالية: منصة الدفع الإلكتروني (تحصيل)، منصة الدفع الإلكتروني (سداد)، البوابة الإلكترونية الموحدة للمشتريات الحكومية (اعتماد).\nمنصات الهيئة السعودية للبيانات والذكاء الاصطناعي: منصة قناة التكامل الحكومية (GSB)، منصة الشبكة الحكومية الآمنة (GSN)، منصة سوق البيانات، منصة السحابة الحكومية (G- Cloud).\nمنصة الديوان العام للمحاسبة: منصة الرقابة الإلكترونية (شامل).\nمنصة وزارة الداخلية: منصة النفاذ الوطني الموحد (نفاذ).\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• الأمر السامي رقم (57231) وتاريخ 10/11/1439 هـ، البندان (ثالثًا) و(سابعًا).\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البندان (12) و(14).\n• قرار مجلس الوزراء رقم (555) وتاريخ 23/9/1440 هـ، الفقرة (2) من البند (تاسعًا).\n• تعميم هيئة الحكومة الرقمية رقم (378) وتاريخ 2/6/1444 هـ.\n• تعميم هيئة الحكومة الرقمية رقم (1339) وتاريخ 15/11/1444هـ.\n• تعميم الهيئة السعودية للبيانات والذكاء الاصطناعي رقم (2/1489) وتاريخ 17/2/1447هـ.", "مستندات مطلوبة من جميع الجهات الحكومية:\n1) إرفاق التقارير الدورية التي توضح تنفيذ خطط الارتباط وفق الآليات والجداول الزمنية المعتمدة.\n2) لا يتطلب إرفاق مستند إثبات، وسيتم التحقق داخليا من ارتباط الجهة بخدمات النفاذ الوطني الموحد “نفاذ”.\n3) لا يتطلب إرفاق مستند إثبات، وسيتم التحقق داخليا من تفعيل خدمة الدفع الإلكتروني للخدمات الرقمية المقدَّمة للمستفيدين.\n4) إرفاق (3) عينات وصور شاشات حديثة تثبت استفادة الجهة من الخدمات المتوافرة في البوابة الإلكترونية الموحدة للمشتريات الحكومية “اعتماد“.\n5) لا يتطلب إرفاق مستند إثبات، وسيتم التحقق من خلال قوائم الالتزام التي تصدر من الديوان العام للمحاسبة.\n6) إرفاق عينة حديثة من التقارير الدورية المتعلقة بمتابعة الارتباط بكل خدمة/ نظام، وفق متطلبات تطبيق هذا المعيار.\nمستندات مطلوبة من وزارة المالية، الهيئة السعودية للبيانات والذكاء الاصطناعي، الديوان العام للمحاسبة، وزارة الداخلية:\n7) إرفاق نسخة من التعليمات حول إجراءات الاستفادة من الأنظمة والخدمات المشتركة وفق متطلبات تطبيق هذا المعيار.\n8) إرفاق آلية استقبال طلبات الارتباط والاستفادة من الأنظمة والخدمات المشتركة وفق متطلبات تطبيق هذا المعيار.\n9) إرفاق نسخة من اتفاقية الاستخدام وفق متطلبات تطبيق هذا المعيار.\n10) إرفاق نسخ من اتفاقيات مستوى الخدمة (SLA) وفق متطلبات تطبيق هذا المعيار."],
  ["5.14.2-1", "تنفيذ خطط الارتباط وفق الآليات والجداول الزمنية المعتمدة وإصدار تقارير بذلك.", "متطلبات على جميع الجهات الحكومية"],
  ["5.14.2-2", "تفعيل المورد التقني المشترك لخدمة النفاذ الوطني الموحد في جميع المنصات والتطبيقات الحكومية التي تقدم خدمات رقمية، وحصر الاستفادة من خدمات الهوية الرقمية للأفراد عبر منظومة النفاذ الوطني الموحد.", "متطلبات على جميع الجهات الحكومية"],
  ["5.14.2-3", "تفعيل المورد التقني المشترك لخدمة الدفع الإلكتروني المقدَّمة من وزارة المالية في جميع المنصات والتطبيقات الحكومية التي تقدم خدمات رقمية تتطلب دفع مقابل مالي أو رسوم لتنفيذ الخدمة، وتمكين الدفع بالبطاقات البنكية من منصات الجهة الحكومية مباشرة.", "متطلبات على جميع الجهات الحكومية"],
  ["5.14.2-4", "الاستفادة من الخدمات المتوفرة في البوابة الإلكترونية الموحدة للمشتريات الحكومية \"اعتماد\".", "متطلبات على جميع الجهات الحكومية"],
  ["5.14.2-5", "الارتباط بمنظومة الرقابة الإلكترونية بالديوان العام للمحاسبة “شامل”.", "متطلبات على جميع الجهات الحكومية"],
  ["5.14.2-6", "إصدار التقارير الدورية لمتابعة الارتباط بكل خدمة/ نظام، بما يشمل كحد أدنى الآتي:", "أ. حجم البيانات المتبادلة.\nب. تحليل أوقات ذروة الاستخدام.\nت. عدد العمليات المنفذة والمرفوضة.\nث. حالات تذاكر الدعم المرفوعة.\nمتطلبات على جميع الجهات الحكومية"],
  ["5.14.2-7", "نشر تعليمات واضحة حول إجراءات الاستفادة من الأنظمة والخدمات المشتركة على منصاتها الرقمية، على أن تتضمن - بحد أدنى- الآتي:", "أ. أهلية الاستخدام واشتراطات ومتطلبات الارتباط والاستفادة من المنصة.\nب. إجراءات تقديم طلبات الارتباط والاستفادة من المنصة.\nمتطلبات على وزارة المالية، الهيئة السعودية للبيانات والذكاء الاصطناعي، الديوان العام للمحاسبة، وزارة الداخلية"],
  ["5.14.2-8", "تحديد آلية استقبال طلبات الارتباط والاستفادة من الأنظمة والخدمات المشتركة، واتخاذ القرار بشأن تلك الطلبات ضمن إطار زمني لا يزيد عن عشرة أيام عمل من تاريخ تقديم الطلب، مع الالتزام بالآتي:", "أ. أن تكون آلية استقبال طلبات الارتباط مؤتمتة.\nب. توفير الدعم الفني اللازم للجهة الحكومية المستفيدة من خلال أكثر من قناة اتصال إلى حين استكمال الارتباط والاستفادة من المنصة في حال قبول الطلب.\nت. اعتماد تكليف مسؤول النظام المرشح من الجهة الحكومية المستفيدة للربط خلال الفترة المحددة.\nث. إبلاغ الجهة الحكومية المستفيدة بمسببات قرار الرفض خلال الفترة المحددة، وذلك في حال عدم قبول طلب الارتباط ضمن إطار زمني يتم الاتفاق عليه بين الطرفين.\nج. تحديد المدة الزمنية اللازمة للرد على الاستفسارات الداخلية وطلبات الدعم من موظفي الجهة الحكومية المستفيدة.\nمتطلبات على وزارة المالية، الهيئة السعودية للبيانات والذكاء الاصطناعي، الديوان العام للمحاسبة، وزارة الداخلية"],
  ["5.14.2-9", "إدراج اتفاقية الاستخدام متضمنة ما يترتب على إساءة استخدام النظم والموارد المعلوماتية والروابط الإلكترونية للأنظمة واللوائح ذات العلاقة.", "متطلبات على وزارة المالية، الهيئة السعودية للبيانات والذكاء الاصطناعي، الديوان العام للمحاسبة، وزارة الداخلية"],
  ["5.14.2-10", "إعداد اتفاقيات مستوى الخدمة (SLA) لضمان توافر النظام على مدار الساعة واستدامة وتوافر الخدمة؛ من خلال أكثر من قناة إلكترونية؛ لتزويد الجهات الحكومية المستفيدة بالخدمة، وإعداد وثائق إجراءات التشغيل لجميع العمليات، وتفصيل اتفاقيات مستوى الخدمات الخاصة بخدمات الدعم على المنصة.", "متطلبات على وزارة المالية، الهيئة السعودية للبيانات والذكاء الاصطناعي، الديوان العام للمحاسبة، وزارة الداخلية"],
  ["5.14.3", "المتابعة المستمرة للأنظمة والخدمات المشتركة", "الهدف: متابعة عمليات الارتباط بالأنظمة والخدمات المشتركة، ومراقبة الأداء، وإجراء تدقيق دوري حول مدى مطابقتها للمواصفات والتنظيمات الصادرة عن الهيئة.\n\nالنطاق: تطبيق المتطلبات من (1) إلى (3) على جميع الجهات الحكومية.\nتطبيق المتطلبات من (4) إلى (11) على المنصات الآتية:\nمنصات وزارة المالية: منصة الدفع الإلكتروني (تحصيل)، منصة الدفع الإلكتروني (سداد)، البوابة الإلكترونية الموحدة للمشتريات الحكومية (اعتماد). منصات الهيئة السعودية للبيانات والذكاء الاصطناعي: منصة قناة التكامل الحكومية (GSB)، منصة الشبكة الحكومية الآمنة (GSN)، منصة سوق البيانات، منصة السحابة الحكومية (G- Cloud).\nمنصة الديوان العام للمحاسبة: منصة الرقابة الإلكترونية (شامل).\nمنصة وزارة الداخلية: منصة النفاذ الوطني الموحد (نفاذ).\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم هيئة الحكومة الرقمية رقم (1339) وتاريخ 15/11/1444هـ.", "مستندات مطلوبة من جميع الجهات الحكومية:\n1) إرفاق الوثائق الحديثة التي توضح دراسة وتحليل التقارير الدورية، ومدى تحقق أهداف الجهة من عمليات الارتباط التي تّمت، ومدى الاستفادة من البيانات المشتركة.\n2) إرفاق التقارير التي توضح المتابعة المستمرة للأنظمة والخدمات الجديدة وفق متطلبات تطبيق هذا المعيار.\n3) إرفاق العينات الحديثة من محاضر الاجتماعات والقرارات التي اتخذتها الجهة بناء على التقارير الدورية.\nمستندات مطلوبة من وزارة المالية، الهيئة السعودية للبيانات والذكاء الاصطناعي، الديوان العام للمحاسبة، وزارة الداخلية:\n4) إرفاق الهيكل التنظيمي ووصف المهام للإدارة المكلفة بالتدقيق والمتابعة على أداء الأنظمة والخدمات المشتركة.\n5) إرفاق النموذج التشغيلي لإدارة وتنظيم أعمال الأنظمة والخدمات المشتركة وفق متطلبات تطبيق هذا المعيار.\n6) إرفاق الوثائق والعينات من التقارير ومحاضر الاجتماعات والقرارات التي تثبت أن الجهة تتابع بيانات الاستخدام، وفق متطلبات تطبيق هذا المعيار.\n7) إرفاق آلية التدقيق والمتابعة التي توضح تقييم وظائف الأنظمة والخدمات المشتركة وحالات استخدامها، وقياس مدى الالتزام بهذه المعايير.\n8) إرفاق ما يثبت القيام بالحملات الترويجية للتعريف بالأنظمة والخدمات المشتركة.\n9) إرفاق البرامج التدريبية التي تقوم بها الجهات المالكة لفائدة الجهات المستفيدة.\n10) إرفاق ما يثبت تقديم خدمات الدعم الفني للجهات الحكومية المستفيدة فيما يخص استخدام وتشغيل الأنظمة والخدمات المشتركة.\n11) إرفاق نسخة من خارطة طريق تطوير الأنظمة والخدمات المشتركة، وتحسين رضا مستخدميها."],
  ["5.14.3-1", "دراسة وتحليل التقارير الدورية ومدى تحقق أهداف الجهة من عمليات الارتباط التي تمَّت ومدى الاستفادة من البيانات المشتركة.", "متطلبات على جميع الجهات الحكومية"],
  ["5.14.3-2", "المتابعة المستمرة للأنظمة والخدمات الجديدة للتأّكد من أّن البنية التحتية وجميع الخدمات المرتبطة بالأنظمة والخدمات المشتركة مبنية بما يضمن استمرارية تشغيلها.", "متطلبات على جميع الجهات الحكومية"],
  ["5.14.3-3", "اتخاذ القرارات المناسبة بناء على التقارير الدورية المتعلقة بالأنظمة والخدمات المشتركة.", "متطلبات على جميع الجهات الحكومية"],
  ["5.14.3-4", "تحديد إدارة ضمن الهيكل التنظيمي للجهة،تَكّلف بالتدقيق والمتابعة على أداء الأنظمة والخدمات المشتركة.", "متطلبات على وزارة المالية، الهيئة السعودية للبيانات والذكاء الاصطناعي، الديوان العام للمحاسبة، وزارة الداخلية"],
  ["5.14.3-5", "تطوير نموذج تشغيلي لإدارة وتنظيم أعمال الأنظمة والخدمات المشتركة، والتي تشمل الأدوار والمسؤوليات ونموذج الحوكمة وإجراءات العمل.", "متطلبات على وزارة المالية، الهيئة السعودية للبيانات والذكاء الاصطناعي، الديوان العام للمحاسبة، وزارة الداخلية"],
  ["5.14.3-6", "متابعة بيانات الاستخدام وفقًا لمنهجية شاملة تحددها الجهة المسؤولة، واستخلاص النتائج والمرئيات من تلك البيانات والاستفادة منها.", "متطلبات على وزارة المالية، الهيئة السعودية للبيانات والذكاء الاصطناعي، الديوان العام للمحاسبة، وزارة الداخلية"],
  ["5.14.3-7", "تطوير آلية تدقيق ومتابعة لتقييم وظائف الأنظمة والخدمات المشتركة وحالات استخدامها وقياس مدى الالتزام بهذه المعايير.", "متطلبات على وزارة المالية، الهيئة السعودية للبيانات والذكاء الاصطناعي، الديوان العام للمحاسبة، وزارة الداخلية"],
  ["5.14.3-8", "تنفيذ حملات ترويجية للتعريف بالأنظمة والخدمات المشتركة.", "متطلبات على وزارة المالية، الهيئة السعودية للبيانات والذكاء الاصطناعي، الديوان العام للمحاسبة، وزارة الداخلية"],
  ["5.14.3-9", "توفير البرامج التدريبية والأدوات اللازمة لمسؤول النظام المكل فَّ من قبل الجهة الحكومية المستفيدة.", "متطلبات على وزارة المالية، الهيئة السعودية للبيانات والذكاء الاصطناعي، الديوان العام للمحاسبة، وزارة الداخلية"],
  ["5.14.3-10", "توفير خدمات الدعم الفني للجهات الحكومية المستفيدة لتقديم الدعم فيما يخص استخدام وتشغيل الأنظمة والخدمات المشتركة.", "متطلبات على وزارة المالية، الهيئة السعودية للبيانات والذكاء الاصطناعي، الديوان العام للمحاسبة، وزارة الداخلية"],
  ["5.14.3-11", "إعداد خارطة طريق سنوية لتطوير الأنظمة والخدمات المشتركة وتحسين رضا مستخدميها.", "متطلبات على وزارة المالية، الهيئة السعودية للبيانات والذكاء الاصطناعي، الديوان العام للمحاسبة، وزارة الداخلية"],
  ["5.14.4", "تفعيل خدمات الثقة الرقمية", "الهدف: رفع الموثوقية في التعاملات الرقمية من خلال توثيق التعاملات والإجراءات بخدمات الثقة الرقمية.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• نظام التعاملات الإلكترونية الصادر بالمرسوم الملكي رقم (م/18) وتاريخ 8/3/1428هـ وتعديلاته اللاحقة ولائحته التنفيذية.\n• الأمر السامي رقم (41990) وتاريخ 11/10/1435هـ.\n• الأمر السامي رقم (57231) وتاريخ 10/11/1439هـ، البند (رابعًا).\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البند (15).\n• قرار مجلس الوزراء رقم (555) وتاريخ 23/9/1440 هـ، الفقرة (2) من البند (سابعًا).", "1) إرفاق نسخة من عقد قائم لتفعيل خدمات الثقة الرقمية مع جهة مرخصة بتقديم هذه الخدمات.\n2) إرفاق (3) عينات غير مدمجة لكل نوع خدمة، موثقة رقمًّيا صادرة من الخدمة الرقمية وقابلة للتحقق بصيغة (PDF) أو (XML) وفق متطلبات تطبيق هذا المعيار.\n3) إرفاق تقارير حديثة من النظام، تثبت تفعيل خدمات الثقة الرقمية وفق متطلبات تطبيق هذا المعيار."],
  ["5.14.4-1", "التعاقد مع جهة مرخصة لتقديم خدمات الثقة الرقمية."],
  ["5.14.4-2", "التفعيل الفعلي لخدمات الثقة الرقمية لجميع أعمال وخدمات الجهة بما يشمل المستفيد الداخلي والخارجي."],
  ["5.14.4-3", "تقديم بيانات الخدمة الإلكترونية التي تم تفعيل خدمات الثقة الرقمية بها، بحيث تشمل ما يأتي:", "أ. نوع خدمة الثقة الرقمية المستخدمة.\nب. وصف الخدمة الرقمية.\nت. فئة المستفيدين من الخدمة.\nث. عدد العمليات لكل خدمة بما يتوافق مع نوع الخدمة وفئة المستفيدين منها."],
  ["5.15", "المنصات الرقمية", "يشمل المحور معايير ومتطلبات حوكمة وتسجيل منصات الحكومة الرقمية وتوحيدها ودمجها، بالإضافة إلى حوكمة وتسجيل النطاقات الحكومية، وذلك لتعزيز تطبيق مفهوم الحكومة الشاملة."],
  ["5.15.1", "حوكمة وتسجيل المنصات الحكومية الرقمية", "الهدف: الالتزام بتسجيل المنصات الحكومية الرقمية القائمة للجهة والحصول على الموافقات المسبقة من هيئة الحكومة الرقمية للمنصات الجديدة قبل إطلاقها وتحديث بياناتها بشكل دوري؛ بهدف تنظيم وحوكمة المنصات الحكومية الرقمية وتفادي الازدواجية والتكرار في تقديم الخدمات الحكومية.\n\nالنطاق: جميع الجهات الحكومية\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• الأمر السامي رقم (11904) وتاريخ 5/3/1437 هـ.\n• تعميم هيئة الحكومة الرقمية رقم (1/42/5589) وتاريخ 7/11/1442 هـ.\n• تعميم هيئة الحكومة الرقمية الصادر برقم (955) وتاريخ 28/1/1443 هـ.\n• تعميم هيئة الحكومة الرقمية رقم (257) وتاريخ 8/4/1444 هـ.\n• تعميم هيئة الحكومة الرقمية رقم (2026) وتاريخ 14/9/1445 هـ، البندان (أولًا) و(ثالثًا).\n• تعميم هيئة الحكومة الرقمية رقم (518) وتاريخ 30/2/1446هـ.\n• تعميم هيئة الحكومة الرقمية رقم (287) وتاريخ 3/3/1445هـ.", "1) لا يتطلب إرفاق مستند إثبات، وسيتم التحقق داخليًا من منصة \"رقمي\".\n2) لا يتطلب إرفاق مستند إثبات، وسيتم التحقق داخليًا من منصة \"رقمي\".\n3) لا يتطلب إرفاق مستند إثبات، وسيتم التحقق داخليًا من منصة \"رقمي\"."],
  ["5.15.1-1", "حصول الجهة على موافقة مسبقة من هيئة الحكومة الرقمية قبل إنشاء أو إطلاق المنصات الخارجية أو الداخلية، سواء كانت بنطاق رئيسي أو فرعي."],
  ["5.15.1-2", "حصر وتسجيل جميع منصات الجهة الخارجية والداخلية، بالنطاقات الرئيسية والفرعية، ومنصات الجهات التابعة لها- إن وجدت-، لدى هيئة الحكومة الرقمية عبر منصة \"رقمي\"."],
  ["5.15.1-3", "التحقق بشكل دوري من تحديث بيانات جميع منصات الجهة المسجلة في منصة \"رقمي\"، مع ضمان الحصول على شهادة منصة فعّالة."],
  ["5.15.2", "توحيد ودمج منصات الجهة", "الهدف: توحيد ودمج المنصات الخاصة بالجهة ضمن خطة عمل القطاع، والتعاون مع حامل المشعل في القطاع من أجل تقديم رحلة ميسرة وموحدة للمستفيدين.\n\nالنطاق: الجهات المحدَّدة في الملحق رقم (7.6)، في القائمة (أ) و(ب) و(ج) بحسب ما هو مبين في هذه البطاقة.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• الأمر السامي رقم (11904) وتاريخ 5/3/1437 هـ.\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البند (16).\n• تعميم هيئة الحكومة الرقمية رقم (1/42/5589) وتاريخ 7/11/1442 هـ.\n• تعميم هيئة الحكومة الرقمية رقم (955) وتاريخ 28/1/1443 هـ.\n• تعميم هيئة الحكومة الرقمية رقم (257) وتاريخ 8/4/1444 هـ.\n• تعميم هيئة الحكومة الرقمية رقم (2026) وتاريخ 14/9/1445 هـ، البند (ثالثًا).", "مستندات مطلوبة من الجهات المحّددة في القائمة (أ) في الملحق رقم (7.6):(جهات حاملة للمشعل للقطاع):\n1) إرفاق الخطة التنفيذية لتوحيد ودمج المنصات الخاصة بالقطاع والمعتمدة من قبل هيئة الحكومة الرقمية.\n2) إرفاق ما يثبت موافقة هيئة الحكومة الرقمية على الخطة.\n3) لا يتطلب إرفاق مستند إثبات، وسيتم التحقق داخليا من إطلاق المنصة القطاعية الموحدة.\n4) إرفاق ما يثبت استكمال تنفيذ الخطة ونقل الخدمات والجهات التابعة لها إلى المنصة القطاعية الموحدة.\nمستندات مطلوبة من الجهات المحّددة في القائمة (ب) في الملحق رقم (7.6):(جهات تابعة لحامل مشعل القطاع):\n5) إرفاق ما يثبت استكمال العمل مع حامل المشعل وتنفيذ الخطة ونقل الخدمات إلى المنصة القطاعية الموحدة.\nمستندات مطلوبة من الجهات المحّددة في القائمة (ج) في الملحق رقم (7.6):(جهات ليست تابعة لحامل مشعل):\n6) إرفاق الخطة التنفيذية لتوحيد ودمج المنصات الخاصة بالجهة وفق متطلبات تطبيق هذا المعيار.\n7) إرفاق مايثبت موافقة هيئة الحكومة الرقمية على الخطة.\n8) إرفاق ما يثبت استكمال أعمال توحيد ودمج الخدمات المقدمة من الجهة ضمن منصة موحدة وبناء على ما تم اعتماده من هيئة الحكومة الرقمية"],
  ["5.15.2-1", "إعداد خطة تنفيذية لتوحيد ودمج المنصات الخاصة بالقطاع ضمن منصة قطاعية موحدة، التي توضح قائمة المنصات التي سُتدَمج والخدمات التي سُتنَقل مع توضيح تاريخ اكتمال أعمال الدمج.", "متطلبات على الجهات المحّددة في القائمة (أ) في الملحق رقم (7.6):(جهات حاملة للمشعل للقطاع)"],
  ["5.15.2-2", "الحصول على موافقة هيئة الحكومة الرقمية على خطة توحيد ودمج المنصات ضمن المنصة القطاعية الموحدة.", "متطلبات على الجهات المحّددة في القائمة (أ) في الملحق رقم (7.6):(جهات حاملة للمشعل للقطاع)"],
  ["5.15.2-3", "إطلاق المنصة القطاعية الموحدة والمعتمدة من قبل هيئة الحكومة الرقمية.", "متطلبات على الجهات المحّددة في القائمة (أ) في الملحق رقم (7.6):(جهات حاملة للمشعل للقطاع)"],
  ["5.15.2-4", "استكمال تنفيذ الخطة ونقل خدمات الجهة والجهات التابعة لها إلى المنصة القطاعية الموحدة.", "متطلبات على الجهات المحّددة في القائمة (أ) في الملحق رقم (7.6):(جهات حاملة للمشعل للقطاع)"],
  ["5.15.2-5", "استكمال العمل مع حامل المشعل على تضمين خدمات الجهة في المنصة القطاعية وتحديث خطة توحيد ودمج المنصات وتنفيذها.", "متطلبات على الجهات المحّددة في القائمة (ب) في الملحق رقم (7.6):(جهات تابعة لحامل مشعل القطاع)"],
  ["5.15.2-6", "إعداد الخطة التنفيذية وتحديثها؛ لتوحيد ودمج المنصات الخاصة بالجهة ضمن منصة موحدة بحسب طبيعة المستفيد.", "متطلبات على الجهات المحّددة في القائمة (ج) في الملحق رقم (7.6):(جهات ليست تابعة لحامل مشعل)"],
  ["5.15.2-7", "الحصول على موافقة هيئة الحكومة الرقمية على خطة الجهة لتوحيد ودمج المنصات ضمن منصة موحدة.", "متطلبات على الجهات المحّددة في القائمة (ج) في الملحق رقم (7.6):(جهات ليست تابعة لحامل مشعل)"],
  ["5.15.2-8", "استكمال أعمال الدمج والتوحيد لكافة الخدمات المقدمة من الجهة ضمن منصة موحدة بحسب طبيعة المستفيد بناًء على ما تم اعتماده من هيئة الحكومة الرقمية.", "متطلبات على الجهات المحّددة في القائمة (ج) في الملحق رقم (7.6):(جهات ليست تابعة لحامل مشعل)"],
  ["5.15.3", "حوكمة وتسجيل النطاقات الحكومية الرقمية", "الهدف: تنظيم استخدام النطاقات الحكومية وتوحيد الهوية الرقمية للجهات وفق ضوابط هيئة الحكومة الرقمية، مع الحد من تعدد النطاقات؛ لضمان سلامة الهيكل التنظيمي للنطاقات الحكومية.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• المرسوم الملكي رقم (م/106) وتاريخ 2/11/1443هـ، الصادر بالموافقة على نظام الاتصالات وتقنية المعلومات، ولائحته التنفيذية، واللوائح والقواعد الخاصة بالتسجيل المتفرعة عنه.\n• قرار مجلس الوزراء رقم (555) وتاريخ 23/9/1440 هـ، الفقرة (1) من البند (ثانيًا).\n• تعميم هيئة الحكومة الرقمية رقم (518) وتاريخ 3/2/1446هـ.\n• تعميم هيئة الحكومة الرقمية الصادر برقم (955) وتاريخ 28/1/1443 هـ.\n• تعميم هيئة الحكومة الرقمية رقم (2026) وتاريخ 14/9/1445 هـ، الفقرة (3) من البند (ثالثًا).", "1) لا يتطلب إرفاق مستند إثبات، وسيتم التحقق داخليا من ضوابط تسجيل النطاقات.\n2) لا يتطلب إرفاق مستند إثبات، وسيتم التحقق داخليا من عدد نطاقات الجهة.\n3) لا يتطلب إرفاق مستند إثبات، وسيتم التحقق داخليا من منصة \"رقمي\".\n4) لا يتطلب إرفاق مستند إثبات، وسيتم التحقق داخليا من إغلاق النطاقات غير النشطة.\n5) إرفاق ما يثبت تبني الإصدار السادس من بروتوكول الإنترنت (6IPv)، وتفعيل خاصية الإمتداد الآمن (DNSSEC)، وسيتم التحقق داخليًا من خلال قوائم التحقق داخل الهيئة."],
  ["5.15.3-1", "تسجيل أسماء نطاقات المواقع الإلكترونية الخاصة بالجهة، وفق ضوابط تسجيل وإدارة النطاقات والمنصات والخدمات الحكومية الرقمية الصادرة من هيئة الحكومة الرقمية."],
  ["5.15.3-2", "التزام الجهة باستعمال نطاق موحد ولا يسمح للجهة بحجز نطاقات متعددة إلا عند وجود مبررات وافقت عليها هيئة الحكومة الرقمية."],
  ["5.15.3-3", "التزام الجهة بالنطاق الرئيسي بالتفريع المعتمد لما ورد في الضوابط مع الحصول على شهادة تسجيل منصة للنطاق في منصة \"رقمي\"."],
  ["5.15.3-4", "إغلاق وحذف النطاقات غير النشطة المحجوزة للجهة التي لا يتم استخدامها."],
  ["5.15.3-5", "تبني الإصدار السادس من بروتوكول الإنترنت (6IPv)، وتفعيل خاصية الامتداد الآمن لنظام أسماء النطاقات )DNSSEC(؛ لحماية النطاقات والتقليل من المخاطر والهجمات الإلكترونية."],
  ["5.15.4", "نظام التصميم الوطني الموّحد (كود المنصات)", "الهدف: دعم توفير تجربة رقمية موحدة وسلسة لجميع فئات المستفيدين بما يضمن توافق واجهات المواقع والمنصات الحكومية مع الإرشادات الموحدة، وأفضل الممارسات الموضحة في \"كود المنصات\".\n\nالنطاق: الجهات الحكومية المعنية والمحدَّدة في الملحق رقم (7.6).\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البندان (1) و (18).\n• تعميم هيئة الحكومة الرقمية رقم (1676) وتاريخ 12/5/1446 هـ.", "1) لا يتطلب إرفاق مستندات إثبات، وسيتم التحقق من القوائم الداخلية في الهيئة."],
  ["5.15.4-1", "تطبيق متطلبات نظام التصميم الوطني الموّحد (كود المنصات) في جميع المنصات والتطبيقات والمواقع الإلكترونية التابعة للجهة."],
  ["5.15.4-2", "تنفيذ متطلبات إصدار شهادة الجودة الصادرة من هيئة الحكومة الرقمية."],
  ["P7", "القنوات والخدمات"],
  ["5.16", "جودة الخدمات الرقمية", "يشمل المحور معايير ومتطلبات تطبيق الأطر والنماذج التي تضمن تشغيل أنواع الخدمات الرقمية كافة، ومتابعتها ومراقبتها بصورة فعّالة."],
  ["5.16.1", "وضع آلية لقياس جودة الخدمات الرقمية", "الهدف: وضع معايير شاملة لقياس جودة الخدمات الرقمية من الناحية التقنية والتشغيلية أثناء تأدية الخدمات بناء على البيانات والتحليلات التنبؤية.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البند (5).\n• تعميم الديوان الملكي رقم (58071) وتاريخ 9/8/1445 هـ، البند (ثانيًا).", "1) إرفاق دراسة قياس جودة الخدمات الرقمية وفق متطلبات تطبيق هذا المعيار."],
  ["5.16.1-1", "إعداد دراسة لقياس جودة الخدمات الرقمية على أن تشمل ما يأتي:", "أ. تحديد معايير وإطار عمل لجودة الخدمات الرقمية لتقييمها أثناء تقديم الخدمات بشكل دوري وفق هذه المعايير.\nب. اعتماد المؤشرات التي تقيس المعايير الُمختارة، على أن تكون تلك المؤشرات قابلة للقياس رقمًّيا في مجملها.\nت. تحديد آلية وضع مستهدفات مستويات التشغيل والخدمة وآلية قياسها."],
  ["5.16.2", "استخدام النظم الرقمية لقياس جودة الخدمات الرقمية", "الهدف: الاستفادة من الأنظمة الرقمية في مراقبة جودة الخدمات الرقمية بشكل فعَّال وفوري واتخاذ القرارات المناسبة حولها.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البندان (1) و(18).\n• تعميم الديوان الملكي رقم (58071) وتاريخ 9/8/1445 هـ، البند (ثانيًا).", "1) إرفاق عينات وصور شاشات حديثة للنظم المستخدمة في قياس جودة الخدمات.\n2) إرفاق (5) عينات حديثة من شاشات المراقبة اللحظية للمؤشرات المحددة، وتوضيح صلاحيات استخدامها.\n3) إرفاق (3) عينات حديثة من التقارير الدورية لمتابعة جودة الخدمات الرقمية.\n4) إرفاق ما يثبت مشاركة التقارير مع لجان الحوكمة المرتبطة بإدارة الخدمات وجودتها.\n5) إرفاق (3) عينات من القرارات ومحاضر الاجتماعات التي تثبت تفعيل آلية مراقبة جودة الخدمات واتخاذ القرارات المناسبة."],
  ["5.16.2-1", "تطوير النظم والأدوات الرقمية التي تقيس جودة الخدمات الرقمية وفقًا للمؤشرات والمعايير المعتمدة لديها."],
  ["5.16.2-2", "تطوير شاشات المراقبة اللحظية للمؤشرات المحددة، وإعطاء الصلاحية لمديري المنتجات/ التطبيقات للمراقبة اللحظية."],
  ["5.16.2-3", "إصدار التقارير الدورية الخاصة بمتابعة جودة الخدمات الرقمية."],
  ["5.16.2-4", "مشاركة التقارير مع لجان الحوكمة المرتبطة بإدارة الخدمات وجودتها، ومناقشة النتائج بشكل دوري."],
  ["5.16.2-5", "اتخاذ الإجراءات والقرارات اللازمة لتحسين الخدمات بناًء على التقارير والنتائج المرفوعة للجان المختصة وفقًا لآلية الحوكمة المتبعة."],
  ["5.16.3", "تحقيق التكامل في إدارة جودة الخدمات", "الهدف: ربط إجراءات جودة الخدمات الرقمية بالإدارات والأنظمة ذات العلاقة.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البندان (1) و(18).\n• تعميم الديوان الملكي رقم (58071) وتاريخ 9/8/1445 هـ، البند (ثانيًا).", "1) إرفاق وثيقة توضح الربط بين سياسات وإجراءات جودة الخدمات الرقمية مع سياسات وإجراءات استمرارية الأعمال.\n2) إرفاق (3) عينات من القرارات التصحيحية المشتركة بين إدارة جودة الخدمات الرقمية والإدارات الأخرى.\n3) إرفاق (3) عينات من الدراسات التي أُجريت على تقارير تجربة المستخدم، ورضا المستفيد.\n4) إرفاق (3) عينات من الأدوات الرقمية المستخدمة للربط مع الجهات ذات العلاقة."],
  ["5.16.3-1", "ربط خطط وممارسات الجودة بسياسات استمرارية الأعمال وفقًا لإطار الحوكمة المعتمد."],
  ["5.16.3-2", "ربط التقارير والأعمال التصحيحية بممارسات إدارة البنية التحتية وفقًا لإطار الحوكمة المعتمد."],
  ["5.16.3-3", "الاستفادة من تقارير وممارسات تجربة المستخدم في تحسين جودة الخدمات."],
  ["5.16.3-4", "تطوير آليات لربط قياسات جودة الخدمات؛ تمهيدًا لربطها مع الجهات ذات العلاقة."],
  ["5.16.4", "تطوير الخدمات ذات الأولوية", "الهدف: دراسة وتحديد الخدمات الرقمية ذات الأولوية ورفع مستوى نضجها.\n\nالنطاق: جميع الجهات الحكومية\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البندان (1) و(18).", "مستندات مطلوبة من جميع الجهات الحكومية:\n1) إرفاق وثيقة حصر الخدمات الحكومية الرقمية الأكثر طلبا في الجهة وفق متطلبات تطبيق هذا المعيار.\nمستندات مطلوبة من الجهات الحكومية المعنية والمحدَّدة في الملحق رقم (7.6):\n2) لا يتطلب إرفاق مستند إثبات، وسيتم التحقق داخليا من منصة \"رقمي\".\n3) إرفاق التقارير التي توضح مستوى النضج والتكامل للخدمات ذات الأولوية.\n4) إرفاق عينة حديثة لكل خدمة من الخدمات ذات الأولوية توضح الإتاحة على جميع القنوات الممكنة، وتوظيف التقنيات الناشئة قدر الإمكان في تقديم الخدمة.\n5) إرفاق التقارير التي توضح قياس معدلات استخدام الخدمات ذات الأولوية، وفق متطلبات تطبيق هذا المعيار."],
  ["5.16.4-1", "حصر الخدمات الحكومية الرقمية الأكثر طلبًا في الجهة (الأولوية للخدمات الخارجية)، بحيث يشمل الحصر للخدمات المعايير الآتية:", "أ. فئات المستفيدين.\nب. عدد المستفيدين.\nت. عدد العمليات (حجم الاستخدام).\nث. تكامل الخدمة مع جهات حكومية أخرى.\nج. طريقة تقديم الخدمة.\nمتطلبات على جميع الجهات الحكومية"],
  ["5.16.4-2", "تلتزم الجهة بتوفير كافة المحتويات التوضيحية والإرشادية للخدمات ذات الأولوية في منصة \"رقمي\"، والتي تشمل الفيديوهات التوضيحية، وأدلة المستخدم، والكلمات الدلالية، والخدمات ذات الصلة، مع ضمان إتاحتها باللغتين العربية والإنجليزية ضمن القسم المخصص لكل خدمة.", "متطلبات على الجهات الحكومية المعنية والمحدَّدة في الملحق رقم (7.6)"],
  ["5.16.4-3", "تطوير الخدمة ذات الأولوية لبلوغ أعلى مستوى ممكن من النضج والتكامل.", "متطلبات على الجهات الحكومية المعنية والمحدَّدة في الملحق رقم (7.6)"],
  ["5.16.4-4", "إتاحة الخدمة ذات الأولوية على جميع القنوات الممكنة وتوظيف التقنيات الناشئة قدر الإمكان في تقديم الخدمة.", "متطلبات على الجهات الحكومية المعنية والمحدَّدة في الملحق رقم (7.6)"],
  ["5.16.4-5", "حصر وقياس مؤشرات الأداء التشغيلية لكافة الخدمات ذات الأولوية، مع الالتزام بالنطاق الزمني المحدد للبيانات من بداية يناير (2025م) حتى نهاية ديسمبر (2026م)، بحيث تشمل ما يأتي:", "أ. اسم الخدمة.\nب. اسم تطبيق الجوال (إن وجد).\nت. عدد المعاملات الإجمالية للخدمة (عبر كافة القنوات)، موضحة عدد المعاملات عبر البوابة وعبر التطبيق.\nث. عدد الشكاوى المرسلة عبر كافة القنوات، وعدد الشكاوى التي تمت معالجتها.\nج. عدد مرات تحميل التطبيق الكلية منذ إطلاق التطبيق (التطبيق الذي يتضمن خدمات ذات أولوية).\nح. العدد الكلي للمستفيدين المسجلين على الخدمة.دات مطلوبة من جميع الجهات الحكومية\nمتطلبات على الجهات الحكومية المعنية والمحدَّدة في الملحق رقم (7.6)"],
  ["5.17", "القنوات والخدمات الرقمية", "يتضـمن المحور جميع القنوات التي يمكن للجهة تقديم الخدمات عن طريقها بالتوافق مع تحديد القنوات الملائمة لفئات المسـتفيدين وإلمامهم بالتقنية."],
  ["5.17.1", "التخطيط لإتاحة وتحسين الخدمات من خلال القنوات الرقمية", "الهدف: تحسين إتاحة الخدمات الحالية التي تُقدَّم من خلال القنوات الرقمية، وأتمتة الخدمات غير المؤتمتة، ووضع الخطط اللازمة لذلك.\n\nالنطاق: جميع الجهات الحكومية\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• نظام حقوق الأشخاص ذوي الإعاقة الصادر بالمرسوم الملكي رقم (م/27) وتاريخ 11/2/1445 هـ.\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البندان (1) و(18).\n• تعميم الديوان الملكي رقم (58071) وتاريخ 9/8/1445 هـ، البندان (ثانيًا) و(سادسًا).\n• تعميم هيئة الحكومة الرقمية رقم (2602) وتاريخ 25/11/1445 هـ.\n• تعميم هيئة الحكومة الرقمية رقم (2026) وتاريخ 14/9/1445 هـ، الفقرة (4) من البند (ثالثًا).", "مستندات مطلوبة من جميع الجهات الحكومية:\n1) لا يتطلب إرفاق مستند إثبات، وسيتم التحقق من حصر وتسجيل جميع الخدمات الحكومية غير المؤتمتة من خلال منصة \"رقمي\".\n2) إرفاق خطة محدثة ومعتمدة لإتاحة الخدمات للمستفيدين، وفق متطلبات تطبيق هذا المعيار.\nمستندات مطلوبة من الجهات الحكومية المعنية والمحدَّدة في الملحق رقم (7.6):\n3) لا يتطلب إرفاق مستند إثبات، وسيتم التحقق داخليًا من رفع الخطة التنفيذية لخدمات التطبيقات على بوابة توكلنا."],
  ["5.17.1-1", "حصر وتسجيل جميع الخدمات الحكومية غير المؤتمتة لدى الجهة على منصة \"رقمي\"(خدمة تسجيل الخدمات غير المؤتمتة)، وتحديث بياناتها بشكل مستمر.", "متطلبات على جميع الجهات الحكومية"],
  ["5.17.1-2", "إعداد وتحديث خطة لإتاحة الخدمات لجميع المستفيدين من خلال القنوات الرقمية المناسبة (شاملة لمركز الاتصال) بحيث تشمل ما يأتي:", "أ. قائمة بالخدمات الرقمية التي تقدمها الجهة، أو التي سيتم إطلاقها من خلال القنوات الرقمية.\nب. تحديد القنوات الرقمية المناسبة لإطلاق كل خدمة من الخدمات بما فيها القنوات البديلة الموجَّهة للأشخاص ذوي الإعاقة وكبار السن، إن لم تمكنهم القنوات الحالية من الوصول إلى جميع الخدمات الحكومية، الجدول الزمني لإطلاق هذه الخدمات.\nت. مؤشرات الأداء المعتمدة لقياس أداء كل خدمة من هذه الخدمات من خلال القنوات الرقمية (مقاييس أداء الأعمال التي تفيد الإدارات المسؤولة).\nمتطلبات على جميع الجهات الحكومية"],
  ["5.17.1-3", "إعداد ورفع الخطة التنفيذية للحزمة الثالثة المقرر إطلاقها في 1/7/2026م؛ لإتاحة خدمات التطبيقات الحكومية عن طريق بوابة توكلنا، بحيث تكون مستوفية للتعميم الصادر بهذا الشأن.", "متطلبات على الجهات الحكومية المعنية والمحدَّدة في الملحق رقم (7.6)"],
  ["5.17.2", "تنفيذ خطط إتاحة الخدمات على القنوات الرقمية وتحسينها", "الهدف: متابعة تحسين وإتاحة الخدمات عبر القنوات الرقمية المناسبة، وآليات متابعة تفاعل المستفيدين معها، بما يشمل أتمتة جميع الخدمات والإجراءات المقدَّمة من الجهات الحكومية للمستفيد الخارجي (أفراد، أعمال، حكومي)، سواًء أكانت الخدمات غير الرقمية أم المقدَّمة عن طريق الفروع.\n\nالنطاق: جميع الجهات الحكومية\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• نظام حقوق الأشخاص ذوي الإعاقة الصادر بالمرسوم الملكي رقم (م/27) وتاريخ 11/2/1445 هـ الفقرة (2) من المادة الثانية، والمادة الرابعة عشر، والفصل العاشر من لائحته التنفيذية.\n• الأمر السامي رقم (17850) وتاريخ 16/3/1441 هـ، البند (ثانيًا).\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البند (4).\n• تعميم الديوان الملكي رقم (58071) وتاريخ 9/8/1445هـ، الفقرة (سادسًا).\n• قرار مجلس الوزراء رقم (40) وتاريخ 27/2/1427 هـ، البند (15).\n• تعميم هيئة الحكومة الرقمية رقم (2602) وتاريخ 25/11/1445 هـ، الفقرتان (2) و(3).\n• تعميم هيئة الحكومة الرقمية رقم (257) وتاريخ 8/4/1444هـ.\n• تعميم هيئة الحكومة الرقمية رقم (287) وتاريخ 3/3/1445هـ.\n• تعميم هيئة الحكومة الرقمية رقم (1/42/5589) وتاريخ 07/11/1442هـ.\n• تعميم هيئة الحكومة الرقمية رقم (2026) وتاريخ 14/9/1445 هـ، الفقرة (4) من البند (ثالثًا).", "مستندات مطلوبة من جميع الجهات الحكومية:\n1) لا يتطلب إرفاق مستند إثبات، وسيتم التحقق من إطلاق الخدمات الحكومية غير المؤتمتة من خلال منصة \"رقمي\".\n2) إرفاق التقارير الدورية التي توضح متابعة تنفيذ الخطة التنفيذية لإتاحة الخدمات للمستفيدين.\n3) إرفاق الرابط الإلكتروني لدليل الخدمات الشامل service catalogue() وفق متطلبات تطبيق هذا المعيار.\n4) إرفاق ما يثبت إتاحة الخدمات الرقمية لجميع شرائح المستفيدين مثل (صور الشاشات وروابط فيديوهات)، بما يضمن إمكانية وصول الأشخاص ذوي الإعاقة وكبار السن لها، وفق متطلبات تطبيق هذا المعيار.\n5) لا يتطلب ارفاق مستند اثبات وسيتم التحقق داخليًا.\n6) إرفاق تقارير حديثة تثبت ربط الخدمات الرقمية بنظم قياس رضا المستفيدين، وآلية إتاحة بياناتها وإحصاءاتها.\n7) إرفاق العينات الكافية من التقارير الدورية لمؤشرات أداء الخدمات الرقمية وفق متطلبات تطبيق هذا المعيار.\n8) إرفاق الدراسة التحليلية للخدمات، و (3) عينات حديثة من محاضر الاجتماعات والقرارات التصحيحية، وفق متطلبات تطبيق هذا المعيار.\n9) تقديم نسخة حديثة من صفحات التقرير السنوي للجهة تظهر الإحصائيات عما قامت به في شأن إتاحة وتحسين الخدمات، وفق متطلبات تطبيق هذا المعيار.\nمستندات مطلوبة من الجهات الحكومية المعنية والمحدَّدة في الملحق رقم (7.6):\n10) لا يتطلب إرفاق مستند إثبات، وسيتم التحقق داخليًا من تقارير إطلاق الخدمات في \"توكلنا\"."],
  ["5.17.2-1", "إطلاق الخدمات الحكومية غير المؤتمتة المسجلة من خلال منصة \"رقمي\"(خدمة تسجيل الخدمات غير المؤتمتة) وفق التواريخ المستهدفة، مع تأكيد الإطلاق من خلال المنصة، على ألا يتجاوز موعد إطلاق جميع الخدمات تاريخ 31/12/2026م.", "متطلبات على جميع الجهات الحكومية"],
  ["5.17.2-2", "تنفيذ خطة إتاحة الخدمات عبر القنوات الرقمية (شاملة لمركز الاتصال).", "متطلبات على جميع الجهات الحكومية"],
  ["5.17.2-3", "إعداد دليل شامل للخدمات على منصة الجهة، يقدم معلومات واضحة حول الخدمات الرقمية بحيث تتواءم مع كافة الحقول المطلوبة في النسيج الرقمي، مع مراعاة توفير المحتوى باللغتين العربية والإنجليزية، واعتماد مسميات واضحة وذات معنى للخدمات، دون استخدام الاختصارات التقنية أو العلامات التجارية أو الأسماء التسويقية.", "متطلبات على جميع الجهات الحكومية"],
  ["5.17.2-4", "إتاحة الخدمات الرقمية لجميع شرائح المستفيدين، وضمان وصول الأشخاص ذوي الإعاقة وكبار السن لها.", "متطلبات على جميع الجهات الحكومية"],
  ["5.17.2-5", "حصر وتسجيل كافة الخدمات الرقمية ومعلوماتها في الخدمة المخصصة لذلك على منصة \"رقمي\" وتحديثها بشكل مستمر وبما يشمل الخدمات المقدمة عبر التطبيقات الحكومية.", "متطلبات على جميع الجهات الحكومية"],
  ["5.17.2-6", "ربط الخدمات الرقمية بنظم قياس رضا المستفيدين بشكل آلي، وتجهيز آلية لإتاحة بياناتها وإحصاءاتها؛ تمهيدًا لإتاحتها للجهات ذات العلاقة بشكل رقمي.", "متطلبات على جميع الجهات الحكومية"],
  ["5.17.2-7", "متابعة الخدمات التي تم إطلاقها، وإصدار التقارير الدورية عن مؤشرات الأداء المعتمدة لكل خدمة من الخدمات، وفي كل قناة من قنوات مركز الاتصال (الصوت، البريد، المحادثات الفورية، الفيديو للصم).", "متطلبات على جميع الجهات الحكومية"],
  ["5.17.2-8", "دراسة وتحليل الخدمات بشكل مستمر ومدى إمكانية تقديمها من خلال مختلف القنوات الإلكترونية، واتخاذ الخطوات اللازمة لتحسين الخدمات وزيادة الاستفادة من القنوات الإلكترونية.", "متطلبات على جميع الجهات الحكومية"],
  ["5.17.2-9", "تضمين إحصائيات في التقارير السنوية للجهة عما قامت به في شأن إتاحة وتحسين الخدمات، بحيث تشمل ما يأتي:", "أ. الوقت المستغرق لإنجاز الخدمات للمستفيدين.\nب. رضا المستفيدين عن الخدمات الرقمية المقدَّمة.\nمتطلبات على جميع الجهات الحكومية"],
  ["5.17.2-10", "إتاحة خدمات التطبيقات على تطبيق \"توكلنا\"، بحيث تكون مستوفية للتعميم الصادر بهذا الشأن.", "متطلبات على الجهات الحكومية المعنية والمحدَّدة في الملحق رقم (7.6)"],
  ["5.17.3", "تبني الخدمات الرقمية الاستباقية للمستفيد الداخلي", "الهدف: تقديم الخدمات الداخلية لمنســوبي الجهة بشــكل اســتباقي اعتمادا على تكامل الانظمة الداخلية، بما يقلل الحاجة لتقديم الطلبات أو تعبئة النماذج، ويرفع كفاءة الاجراءات الداخلية، ويحسـن تجربة الموظف، ويسـهم في تسريع انجاز الخدمات.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البنود (1) و(4) و(5) و(18).", "1) إرفاق ما يثبت تقديم الخدمات بشكل استباقي للمستفيد الداخلي، وفق متطلبات تطبيق هذا المعيار.\n2) إرفاق ما يثبت تقديم (10) من الخدمات الرقمية بدون نماذج للمستفيد الداخلي، وفق متطلبات تطبيق هذا المعيار.\n3) إرفاق التقارير التي توضح تبني الخدمات الاستباقية، ونسب الخدمات بدون نماذج إلى إجمالي الخدمات المقدمة للمستفيد الداخلي، وفق متطلبات تطبيق هذا المعيار."],
  ["5.17.3-1", "تقديم الخدمات الرقمية للمستفيد الداخلي بشكل استباقي خلال دورة قياس (2026م) بما يشمل:", "أ. خدمات تهيئة الموظف الجديد: إصدار بطاقة الموظف، إنشاء البريد الإلكتروني الرسمي، منح الصلاحيات على الأنظمة، إصدار تصريح المركبة، وتوفير أجهزة الحاسب الآلي وملحقاتها.\nب. خدمات مرتبطة بالمسار الوظيفي: طلب الإجازات، التدريب أو الترشيح للدورات التدريبية، طلب الترقية، وطلبات البدلات (الانتداب، النقل، وغيرها).\nت. خدمات مرتبطة بإنهاء التعاقد الوظيفي (طلب تقاعد، طلب إنهاء خدمة، إخلاء طرف)."],
  ["5.17.3-2", "تقديم (10) من الخدمات الرقمية الداخلية بدون نماذج (Pre-filled)، من خلال استرجاع البيانات تلقائيًا من الأنظمة ذات العلاقة بالإعتماد على مبدأ \"طلب البيانات لمرة واحدة\"، وعرض ملخص للمستفيد الداخلي للموافقة فقط، خلال دورة قياس (2026م)."],
  ["5.17.3-3", "متابعة تحسين تقديم الخدمات الداخلية، وإصدار تقارير توضح تبني الخدمات الاستباقية، ونسب الخدمات بدون نماذج إلى إجمالي الخدمات المقدمة للمستفيد الداخلي بما يشمل قياس مؤشرات الأداء، ومعدلات إتمام الخدمات، وزمن الاستجابة لجميع الخدمات في جميع القنوات."],
  ["5.17.4", "تبني الخدمات الرقمية الاستباقية للمستفيد الخارجي", "الهدف: تحسين تجربة المستفيد الخارجي من خلال تفعيل نماذج الخدمات الاستباقية، وتطبيق مبدأ \"طلب البيانات لمرة واحدة\" لتقديم تلك الخدمات، مع ضمان استدامة الأداء من خلال الرصد والمتابعة الدورية.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البنود (1) و(4) و(5) و(18).", "1) إرفاق ما يثبت تقديم الخدمات بشكل استباقي للمستفيد الخارجي، وفق متطلبات تطبيق هذا المعيار.\n2) إرفاق ما يثبت تقديم (30%) من الخدمات الرقمية المقدمة للمستفيد الخارجي بدون نماذج، وفق متطلبات تطبيق هذا المعيار.\n3) إرفاق التقارير التي توضح نسب تبني الخدمات الاستباقية، والخدمات بدون نماذج إلى إجمالي الخدمات المقدمة للمستفيد الخارجي، وفق متطلبات تطبيق هذا المعيار."],
  ["5.17.4-1", "تقديم (30%) أو (10) خدمات رقمية -أيهما أقل- من إجمالي الخدمات الرقمية التي تقدمها الجهة للمستفيد الخارجي بشكل استباقي خلال دورة قياس (2026م)."],
  ["5.17.4-2", "تقديم ما لا يقل عن (30%) من إجمالي الخدمات الرقمية المقدمة للمستفيد الخارجي بدون نماذج (Pre- filled)، من خلال استرجاع البيانات تلقائيًا من الأنظمة ذات العلاقة بالإعتماد على مبدأ \"طلب البيانات لمرة واحدة\"، وعرض ملخص للمستفيد للموافقة فقط."],
  ["5.17.4-3", "متابعة تحسين تقديم الخدمات الرقمية للمستفيد الخارجي، وإصدار تقارير توضح نسب تبني الخدمات الاستباقية، والخدمات بدون نماذج إلى إجمالي الخدمات المقدمة للمستفيد الخارجي بما يشمل قياس مؤشرات الأداء، ومعدلات إتمام الخدمات، وزمن الاستجابة لجميع الخدمات في جميع القنوات."],
  ["5.17.5", "تكامل واتساق قنوات تقديم الخدمة", "الهدف: تحقيق التكامل بين مختلف القنوات الرقمية التي تقدم الخدمات للمستفيدين.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البندان (1) و(18).\n• تعميم الديوان الملكي رقم (58071) وتاريخ 9/8/1445 هـ، البندان (ثانيًا) و(سادسًا).", "1) إرفاق (3) عينات حديثة توضح التكامل بين قنوات تقديم الخدمة وتقديم الخدمة نفسها بأكثر من قناة.\n2) إرفاق (3) عينات حديثة توضح إتاحة الخدمات بشكل متسق عبر قنوات متعددة وملاءمتها لجميع شرائح المستخدمين.\n3) لا يتطلب إرفاق مستند إثبات، ويتم متابعة التزام الجهات الحكومية مباشرًة من هيئة الحكومية الرقمية حسب التقارير الدورية التي تصدرها الهيئة وبما يتوافق مع \"ضوابط تطوير جودة المحتوى الرقمي للمواقع والمنصات الحكومية الرقمية لتحسين ظهورها على محركات البحث\".\n4) إرفاق العينات الكافية التي توضح عملية الربط والتكامل بين مراكز رعاية المستفيدين ونظم إدارة علاقات المستفيدين."],
  ["5.17.5-1", "التكامل بين قنوات تقديم الخدمة بما يمِّكن المستفيد من تنفيذ خدماته دون انقطاع من خلال مختلف القنوات المستخدمة لتقديم الخدمة نفسها."],
  ["5.17.5-2", "إتاحة الخدمات بشكل متسق عبر قنوات متعددة وفقًا لدراسة ملاءمة القنوات لشرائح المستخدمين ومدى إلمامهم بالتقنية."],
  ["5.17.5-3", "إتاحة الوصول لمواقع وبوابات الجهة من مختلف الأجهزة والمتصفحات وفقًا لمبدأ التصميم (RWD)."],
  ["5.17.5-4", "تضمين مراكز رعاية المستفيدين كقنوات تقديم الخدمة وربطها بنظم إدارة علاقات المستفيدين."],
  ["P8", "مركزية المستفيد"],
  ["5.18", "مشاركة المستفيد", "يضمن محور مشاركة المستفيد تعزيز دور المستفيد وتحويله إلى شريك فاعل في تطوير الخدمات الحكومية الرقمية وتحسينها عن طريق التعّرف على مرئياته وأفكاره حول تجربة حصوله على تلك الخدمات، الذي يُساعد الجهات الحكومية في فهم تجارب المستفيدين."],
  ["5.18.1", "إتاحة القنوات وطرح موضوعات وفرص المشاركة الإلكترونية", "الهدف: تفعيل المشاركة الإلكترونية من خلال إتاحة قنوات وموضوعات للمستفيدين لمشاركة مرئياتهم وملاحظاتهم ومقترحاتهم، والاستفادة من مشاركات المستفيدين في عملية صنع القرار وإطلاق الخدمات وتحسينها.\n\nالنطاق: تطبيق المتطلبات (1)،(4)،(5)،(6) على جميع الجهات الحكومية.\nتطبيق المتطلبات (2)،(3) على جميع الجهات الحكومية باستثناء الجهات المحددة في الملحق (7.6.1).\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (70701) وتاريخ 13/11/1443 هـ..\n• تعميم هيئة الحكومة الرقمية رقم (311) وتاريخ 16/3/1445 هـ.", "1) إرفاق وثيقة حديثة لجميع القنوات التي أتاحتها الجهة لمشاركة المستفيدين، وفق متطلبات تطبيق هذا المعيار.\n2) لا يتطلب إرفاق مستند إثبات، وسيتم التحقق داخليًا من نشر الاستشارات العامة على منصة \"تفاعل\".\n3) لا يتطلب إرفاق مستند إثبات، وسيتم التحقق داخليًا من نشر مبادرات التطوير المشترك والابتكار على منصة \"تفاعل\".\n4) إرفاق الآلية المعتمدة لدى الجهة، للاستفادة من مشاركات المستفيدين وفق متطلبات تطبيق هذا المعيار.\n5) إرفاق عينة عن كل ربع من الإشعارات الصادرة للمستفيدين من كل قناة، تشمل الوقت المطلوب للرد على الملاحظة أو المقترح.\n6) لا يتطلب إرفاق مستند إثبات، ويتم متابعة التزام الجهات الحكومية مباشرًة من هيئة الحكومية الرقمية حسب التقارير الدورية التي تصدرها الهيئة وبما يتوافق مع \"ضوابط تطوير جودة المحتوى الرقمي للمواقع والمنصات الحكومية الرقمية لتحسين ظهورها على محركات البحث\"."],
  ["5.18.1-1", "حصر القنوات الإلكترونية اللازمة والملائمة للمستفيدين، التي تمكنهم من مشاركة آرائهم وملحوظاتهم ومقترحاتهم حول الخدمات المقدمة؛ بما يشمل عرض قنوات التواصل الاجتماعي والتطبيق الرسمي."],
  ["5.18.1-2", "نشر استشارات عامة متعلقة بالجهة عبر منصة \"تفاعل\" بشكل ربعي، على أن تشمل كل استشارة مراحل: الطرح، والتمكين،وعرض النتائج."],
  ["5.18.1-3", "نشر مبادرات للتطوير المشترك والابتكار المتعلقة بالخدمات والمنصات والتطبيقات عبر منصة \"تفاعل\" بشكل ربعي، على أن تشمل كل مبادرة مراحل: الطرح، والتمكين، وعرض النتائج."],
  ["5.18.1-4", "وضع آلية معتمدة للاستفادة من آراء ومشاركات المستفيدين تشمل تطوير مسار عمل (work flow diagram) ونقاط الاتصال واتخاذ القرار، لمعالجة ملحوظاتهم ومقترحاتهم وفقًا للتصنيفات المختلفة ومؤشرات الأداء."],
  ["5.18.1-5", "تحديد مؤشرات أداء للرد على الملحوظات وإشعار المستفيد بالوقت المطلوب لدراسة الملحوظة أو المقترح."],
  ["5.18.1-6", "تطوير الموقع الإلكتروني للجهة ليتضمن أدوات تقنية تمّكن مختلف شرائح المستفيدين من المشاركة بفاعلية، بما يشمل تخصيص قسم مخصص للمشاركة الإلكترونية، وتمكين سهولة المشاركة عبر وسائل التواصل الاجتماعي، وبما يدعم تطبيق \"ضوابط المشاركة الإلكترونية\"."],
  ["5.18.2", "متابعة مشاركات المستفيدين", "الهدف: متابعة القنوات المخصصة لمشاركة المستفيدين بشكل مستمر ورصد الآراء والاستجابة لملحوظاتهم.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم هيئة الحكومة الرقمية رقم (311) وتاريخ 16/3/1445 هـ.\n• تعميم هيئة الحكومة الرقمية رقم (2026) وتاريخ 14/9/1445 هـ، البند (رابعًا).", "مستندات مطلوبة من جميع الجهات الحكومية:\n1) إرفاق عينات حديثة تثبت المتابعة الدورية لمشاركات المستفيدين من جميع القنوات، وتوضح عمليات الرصد للآراء، والمشاركات، والشكاوى، والمقترحات (لوحات بيانات أو تقارير لحظية \"Real-Time\").\n2) إرفاق عّينة عن كّل ربع من كل قناة، توضح إشعار المستفيد برقم مرجعي للملاحظة أو المقترح ونتائج الدراسة في الإشعار.\n3) إرفاق مايثبت الإعلان عن خدمة \"بلاغ رقمي\" من خلال إحدى القنوات الرسمية المعتمدة لدى الجهة، وسيتم التحقق من تفعيل خدمة \"بلاغ رقمي\" داخليًا.\nمستندات مطلوبة من الجهات الحكومية المعنية والمحدَّدة في الملحق رقم (7.6).:\n4) لا يتطلب إرفاق مستند إثبات، وسيتم التحقق داخليًا من معالجة البلاغات الرقمية.(سُيحتَسب الالتزام بهذا المتطلب لكامل مراحل دورة قياس)."],
  ["5.18.2-1", "المتابعة المستمرة والدورية لمشاركات المستفيدين ورصد جميع الآراء، والمشاركات، والشكاوى، والمقترحات من جميع القنوات.", "متطلبات على جميع الجهات الحكومية"],
  ["5.18.2-2", "إشعار المستفيد من خلال النظام برقم مرجعي للملاحظة أو المقترح أو الشكوى ونتائج الدراسة.", "متطلبات على جميع الجهات الحكومية"],
  ["5.18.2-3", "تفعيل خدمة \"بلاغ رقمي\" لدى الجهة الحكومية والإعلان عنها من خلال إحدى القنوات الرسمية المعتمدة لدى الجهة الحكومية.", "متطلبات على جميع الجهات الحكومية"],
  ["5.18.2-4", "معالجـــة البلاغـــات الرقميـــة المقدَّمـــة مـــن هيئـــة الحكومـــة الرقميـــة وفقـــًا لاتفاقيـــة مســـتوى الخدمــة، علــى ألا تتجــاوز نســبة البلاغــات المصــعدة عبــر خدمــة الــبلاغ الرقمــي (7%) مــن إجمــالي البلاغات الواردة للجهة في المستوى الأول خلال دورة القياس.", "متطلبات على الجهات الحكومية المعنية والمحّددة في الملحق رقم (7.6)."],
  ["5.18.3", "الاستفادة من مشاركات المستفيدين ونشرها", "الهدف: عرض نتائج المشاركة الإلكترونية، والاستفادة من مشاركات المستفيدين في عملية صنع القرار وإطلاق الخدمات وتحسينها.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم هيئة الحكومة الرقمية رقم (311) وتاريخ 16/3/1445 هـ.", "1) إرفاق (4) عينات حديثة (عّينة عن كّل ربع) تثبت تشجيع المستفيدين على المشاركة في جميع مراحل تصميم الخدمات الحكومية الرقمية.\n2) إرفاق (4) عينات حديثة (عّينة عن كّل ربع) من التقارير الدورية.\n3) إرفاق (4) عينات حديثة (عّينة عن كّل ربع) تثبت الاستفادة من المشاركات المقدَّمة من المستفيدين."],
  ["5.18.3-1", "إشراك المستفيدين في جميع مراحل تصميم الخدمات الحكومية الرقمية (جمع المتطلبات، التصميم، والإطلاق التجريبي، والتشغيل والتحسين)."],
  ["5.18.3-2", "إصدار التقارير الدورية الواردة من جميع القنوات المخصصة لمشاركات المستفيدين."],
  ["5.18.3-3", "الاستفادة من المشاركات المقدَّمة من المستفيدين في عملية تطوير وتحسين الخدمات المقدَّمة واتخاذ القرارات اللازمة بناًء على هذه الآراء والخبرات."],
  ["5.18.4", "توظيف التقنيات الناشئة لتعزيز مشاركة المستفيد", "الهدف: اسـتخدام التقنيات الناشـئة في تحليل طلبات ومشـاركات المسـتفيدين، وتنفيذ الخدمات، واسـتخلاص الأنماط والمؤشرات الدلالية منها، وتحويلها إلى تحسينات وقرارات استباقية قابلة للقياس والتنفيذ.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البندان (1) و(18).", "1) إرفاق ما يثبت توظيف التقنيات الناشئة في تحليل طلبات المستفيدين بأساليب تفاعلية متطورة، وتنفيذ الخدمات آليًا بشكل كامل أو جزئي، وفق متطلبات تطبيق هذا المعيار.\n2) إرفاق تقارير حديثة من الأدوات الرقمية، توضح نسبة تقديم الخدمات للمستفيدين وفق متطلبات تطبيق هذا المعيار.\n3) إرفاق ما يثبت استخدام التقنيات الناشئة في تحليل مشاركات المستفيدين، وفق متطلبات تطبيق هذا المعيار.\n4) إرفاق ما يثبت ربط التحسينات الاستباقية بنتائج تحليل مشاركات المستفيدين الصادرة من التقنيات الناشئة المستخدمة."],
  ["5.18.4-1", "توظيف التقنيات الناشئة في تحليل طلبات المستفيدين بأساليب تفاعلية متطورة، وتوظيفها في دعم اتخاذ القرار، وتنفيذ الخدمات آليًا بشكل كامل أو جزئي."],
  ["5.18.4-2", "إصدار تقارير آلية من الأدوات الرقمية التفاعلية، توضح نسبة تقديم الخدمات للمستفيدين عبر هذه الأدوات، متضمنة عدد الخدمات، ومعدلات إتمام الخدمة، وزمن الاستجابة."],
  ["5.18.4-3", "استخدام التقنيات الناشئة في تحليل مشاركات المستفيدين، واستخلاص الأنماط المتكررة، وتوليد توصيات تحسين قابلة للتنفيذ، وربط نتائج التحليل بدورة اتخاذ القرار والتحسين المستمر للخدمات الرقمية."],
  ["5.18.4-4", "تطبيق التحسينات الاستباقية استنادًا إلى الأنماط المتكررة في مشاركات المستفيدين."],
  ["5.19", "تعزيز العلاقة مع المستفيد", "يعمل المحور على تطبيق نهج واضح لعملية إدارة التواصل مع المستفيدين والتسويق لخدمات الجهة باستخدام وسائل وطرق حديثة لتحسين إجراءات دعم العلاقة مع المستفيدين في الجهة الحكومية وتعزيزها."],
  ["5.19.1", "تطوير برنامج تعزيز العلاقة مع المستفيد", "الهدف: تطوير البرامج المتعلقة بتعزيز العلاقة مع المستفيدين من الخدمات وأساليب التسويق المناسبة للخدمات والمنتجات الرقمية.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• الأمر السامي رقم (47746) وتاريخ 29/6/1445 هـ.\n• تعميم الديوان الملكي رقم (39175) وتاريخ 4/6/1444 هـ الفقرة (أولًا).\n• قرار مجلس الوزراء رقم (555) وتاريخ 23/9/1440 هـ، البند (ثامنًا).", "مستندات مطلوبة من جميع الجهات الحكومية:\n1) إرفاق وثيقة محدثة للبرنامج المعتمد لتعزيز العلاقة مع المستفيد، الذي يثبت التزام الجهة بمتطلبات تطبيق هذا المعيار.\n2) إرفاق عينة من التنظيمات والضوابط المتعلقة بالمشاركة في وسائل التواصل الاجتماعي، وما يثبت مشاركتها مع المنسوبين.\nمستندات مطلوبة من الجهات الحكومية المعنية والمحدَّدة في الملحق رقم (7.6).:\n3) إرفاق ما يثبت التنسيق مع برنامج السعودية الرقمية وفق متطلبات تطبيق هذا المعيار.\n4) لا يتطلب إرفاق مستند اثبات وسيتم التحقق داخليا.(سُيحتَسب الالتزام بهذا المتطلب لكامل مراحل دورة قياس)."],
  ["5.19.1-1", "وضع برنامج معتمد لتسويق خدمات الجهة وتعزيز علاقتها مع المستفيدين بمختلف تصنيفاتهم بحيث يراعي نوعية القنوات التي تقدم الخدمات من خلالها، ويتضمن البرنامج الخاص بتعزيز العلاقة مع المستفيد النقاط الآتية:", "أ. قائمة الخدمات التي تهدف الجهة لتسويقها، آخذًا بالاعتبار الخدمات الرقمية ذات الأولوية.\nب. الفئات المستهدفة من خطة تعزيز العلاقة وتسويق الخدمات.\nت. القنوات الإلكترونية المستخدمة في عمليات التسويق وتعزيز العلاقة.\nث. الوسائل والفعاليات التي سيتم القيام بها، بهدف التسويق وتعزيز العلاقة مع المستفيد.\nج. الجدول الزمني المعتمد لإقامة هذه الفعاليات.\nح. مؤشرات الأداء التي سيتم من خلالها قياس مدى نجاح هذه الفعاليات.\nخ. التقارير الدورية التي سيتم إصدارها عن هذه الفعاليات.\nمتطلبات على جميع الجهات الحكومية"],
  ["5.19.1-2", "تطبيق الضوابط المتعلقة بوسائل التواصل الاجتماعي التي أصدرتها وزارة الإعلام والجهات ذات العلاقة.", "متطلبات على جميع الجهات الحكومية"],
  ["5.19.1-3", "التنسيق مع برنامج السعودية الرقمية في هيئة الحكومة الرقمية من خلال البريد الإلكتروني أو الموقع الإلكتروني للبرنامج أو المخاطبات الرسمية قبل إقامة الجهة أو مشاركتها في أي فعاليات أو مؤتمرات أو معارض ذات العلاقة بالحكومة الرقمية أو التحول الرقمي سواء على المستوى المحلي أو الدولي وذلك حسب التنسيق بين الجهة وبرنامج السعودية الرقمية.", "متطلبات على الجهات الحكومية المعنية والمحّددة في الملحق رقم (7.6)."],
  ["5.19.1-4", "التفاعل من خلال المشاركة في الفعاليات، أو المؤتمرات، أو المعارض التي ينظمها برنامج السعودية الرقمية، سواًء أكانت في أجنحة، أو ورش عمل، أو جلسات حوارية، أو إطلاقات منتجات رقمية جديدة، أو متحدثين في الفعاليات الحضورية أو المرئية أو تزويد البرنامج بأرقام ومنجزات رقمية خاصة بالجهة.", "متطلبات على الجهات الحكومية المعنية والمحّددة في الملحق رقم (7.6)."],
  ["5.19.2", "تنفيذ برنامج تعزيز العلاقة مع المستفيد", "الهدف: تنفيذ البرامج المعتمدة لتعزيز العلاقة مع المستفيد عبر مختلف القنوات الرقمية والوسائل المناسبة.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البند (13).", "1) إرفاق التقارير الحديثة والصور الكافية التي تثبت أن الجهة قامت بتنفيذ البرامج المعتمدة، لتعزيز العلاقة مع المستفيد بما يشمل جميع المنتجات والمنصات سواء للأفراد أو الجهات.\n2) إرفاق التقارير الدورية التي تقيس مدى نجاح برامج تعزيز العلاقة مع المستفيد في تحقيق المستهدفات، وتوضح نسب الإنجاز.\n3) إرفاق دراسة تحليل التقارير الدورية الناتجة عن تنفيذ برامج تعزيز العلاقة مع المستفيد، ومحاضر الاجتماعات التي توضح اتخاذ القرارات التي تسهم في تطوير البرامج التسويقية."],
  ["5.19.2-1", "تنفيذ البرامج والحملات والأنشطة التسويقية المعتمدة، لرفع وعي المستفيدين بالخدمات الرقمية للجهة وطرق الحصول عليها عبر مختلف القنوات."],
  ["5.19.2-2", "استخدام الأدوات الرقمية في رصد وقياس مؤشرات الأداء المعتمدة التي تقيس مستهدفات برنامج تعزيز العلاقة مع المستفيد ومدى تحقيقها للأهداف المأمولة، وقياس مدى التقدم في تنفيذ هذه البرامج."],
  ["5.19.2-3", "دراسة وتحليل التقارير الدورية الناتجة عن تنفيذ برنامج تعزيز العلاقة مع المستفيد والاستفادة منها في تطوير أنشطتها التسويقية، وتحسين مستوى خدماتها المقدَّمة واتخاذ القرارات المناسبة في هذا الصدد."],
  ["5.19.3", "التعاون في مجال تعزيز العلاقة مع المستفيد", "الهدف: تحقيق التعاون والتكامل مع الجهات الحكومية الأخرى فيما يتعلق بتعزيز العلاقة مع المستفيد.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البندان (1) و(18).", "1) إرفاق الوثائق الحديثة التي توضح السياسات والآليات التي تم تطويرها لتنظيم التعاون بين الجهات الحكومية في مجال تسويق الخدمات المشتركة وفق متطلبات تطبيق هذا المعيار.\n2) إرفاق الوثائق الحديثة والعينات الكافية من التقارير ومحاضر الاجتماعات والقرارات التي تثبت أن الجهة قامت بحملات تسويقية مشتركة مع الجهات الحكومية المرتبطة معها في الخدمات التي تقدمها."],
  ["5.19.3-1", "وضع سياسات وآليات لتنظيم التعاون بين الجهات الحكومية في مجال تسويق الخدمات المشتركة بما يشمل :", "أ. تحديد المسؤوليات والأدوار لكل جهة لضمان التنسيق الفّعال.\nب. تشكيل لجان أو فرق عمل مشتركة للإشراف على تنفيذ حملات تسويقية مشتركة."],
  ["5.19.3-2", "القيام بحملات تسويقية مشتركة مع الجهات الحكومية المرتبطة معها في الخدمات التي تقدمها، وتضمين هذه الأنشطة ضمن برامج تعزيز العلاقة مع المستفيد."],
  ["5.20", "تجربة المستفيد", "يضمن المحور تفاعل المستفيد مع الجهة الحكومية في جميع مراحل تقديم الخدمة؛ وذلك عن طريق اعتماد مبادئ التصميم الإبداعي والتفاعلي والمرئي، وسهولة الوصول والاستخدام، لضمان استدامة العلاقة واستمراريتها."],
  ["5.20.1", "وضع أسس مركزية المستفيد", "الهدف: وضع أسس مركزية المستفيد لضمان الاستخدام الأمثل للخدمات الحكومية الرقمية وتبِّنيها من قَِبل المستفيدين.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البندان (1) و(18).\n• تعميم هيئة الحكومة الرقمية رقم (2026) وتاريخ 14/9/1445 هـ، البند (ثالثًا).", "1) إرفاق السياسات الممكنة لتبِّني مفهوم مركزية المستفيد وما يثبت نشرها وفق متطلبات تطبيق هذا المعيار.\n2) إرفاق إستراتيجية تقديم الخدمات الرقمية التي تراعي مفهوم مركزية المستفيد، وفق متطلبات تطبيق هذا المعيار."],
  ["5.20.1-1", "وضع السياسات الممكنة لتبِّني مفهوم مركزية المستفيد في تقديم الخدمات الحكومية الرقمية، مثل سياسة »الوصول إلى المعلومات والخدمات الحكومية الرقمية«، وسياسة »المشاركة الإلكترونية« ونشرها في القنوات التي يتم من خلالها تقديم الخدمات الحكومية الرقمية مع مراعاة شموليتها ووضوح صياغتها وطريقة عرضها."],
  ["5.20.1-2", "وضع إستراتيجية لتقديم الخدمات الرقمية تراعي مفهوم مركزية المستفيد، ووضع ما يتطلبه تنفيذ الإستراتيجية من خطط أو برامج وآليات لمتابعة التنفيذ."],
  ["5.20.2", "تحديد رؤية الجهة لتجربة المستفيد", "الهدف: تحديد رؤية واضحة لتجربة المستفيد الرقمية.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• نظام حقوق الأشخاص ذوي الإعاقة الصادر بالمرسوم الملكي رقم (م/27) وتاريخ 11/2/1445 هـ.\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البندان (1) و(18).\n• تعميم هيئة الحكومة الرقمية رقم (2026) وتاريخ 14/9/1445 هـ، البند (ثالثًا).", "1) إرفاق وثيقة معتمدة تحدد رؤية الجهة لتجربة المستفيد وفق متطلبات تطبيق هذا المعيار.\n2) إرفاق ما يثبت تحديد المؤشرات المعتمدة المرتبطة بقياس وتحسين تجربة المستفيد، وآليات قياسها وفق متطلبات تطبيق هذا المعيار."],
  ["5.20.2-1", "وجود رؤية لدى الجهة لقياس وتحسين تجربة المستفيد بحيث تشمل جميع المستفيدين، والخدمات، والإجراءات."],
  ["5.20.2-2", "تحديد مؤشرات الأداء المرتبطة بقياس وتحسين تجربة المستفيد وآليات قياسها، بحيث تشمل ما يأتي:", "أ. سهولة الوصول للخدمة.\nب. تطابق مستوى الخدمة في جميع القنوات.\nت. شمولية الخدمة وإتاحة وصولها لجميع الفئات بما يشمل الأشخاص ذوي الإعاقة وكبار السن، من خلال توفر خيارات الوصول مثل دعم اللغات المختلفة، وخدمات قراءة الشاشة للأشخاص ذوي الإعاقة، ومدى توافق الخدمة مع المعايير الدولية لإمكانية الوصول.\nث. مدى الاهتمام بالمحتوى.\nج. سهولة الاستخدام.\nح. أهمية الخدمة ومدى الاستفادة للمستفيد.\nخ. الموثوقية.\nد. الكفاءة."],
  ["5.20.3", "دراسة تجربة المستفيد لتحسينها", "الهدف: دراسة تجربة المستفيد بغرض العمل على تحسينها، ووضع المستهدفات القياسية لذلك.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البندان (1) و(18).\n• تعميم هيئة الحكومة الرقمية رقم (2026) وتاريخ 14/9/1445 هـ، البند (ثالثًا).", "1) إرفاق دراسة حديثة ومعتمدة لتجربة المستفيد الرقمية، وفق متطلبات تطبيق هذا المعيار."],
  ["5.20.3-1", "إعداد دراسة لتجربة المستفيد الرقمية بهدف التحسين بحيث تشمل:", "أ. أهداف عملية التحسين بناًء على دراسة تجربة المستفيد وتقييم الرضا.\nب. قائمة الأدوات التي تستخدم لقياس تجربة المستفيد بما يشمل استخدام التقنيات الناشئة في قياس مؤشرات الأداء المرتبطة بقياس وتحسين تجربة المستفيد .\nت. منهجيات قياس أثر تطبيق ممارسات مركزية المستفيد وتطوير تجربة المستفيد."],
  ["5.20.4", "تطبيق الأدوات الرقمية الخاصة بقياس ومتابعة تجربة المستفيد", "الهدف: تطبيق الأدوات الرقمية في عملية قياس ومتابعة تجربة المستفيد.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البندان (1) و(18).\n• تعميم هيئة الحكومة الرقمية رقم (2026) وتاريخ 14/9/1445 هـ، البند (ثالثًا).", "1) إرفاق عينات حديثة وكافية من التقارير وشاشات الأدوات المستخدمة في قياس تجربة المستفيد وسلوكه أثناء تأدية الخدمة، ومتابعة مؤشرات الأداء، والتي تثبت التزام الجهة بتطبيق الأدوات الرقمية الخاصة بقياس ومتابعة تجربة المستفيد (علمًا أن الاستبيانات لا تحقق الهدف من المتطلب).\n2) إرفاق ما يثبت دراسة وتحليل التقارير الناتجة من الأدوات والتقنيات الرقمية المستخدمة في قياس تجربة المستفيد، والاستفادة منها في تحسين الخدمات.\n3) إرفاق التقارير الحديثة التي توضح المقارنات للخدمات المحسنة قبل وبعد التحسين وفقًا لمؤشرات أداء قياس تجربة المستفيد المعتمدة."],
  ["5.20.4-1", "توظيف الأدوات والتقنيات الرقمية اللازمة التي تضمن قياس تجربة المستفيد وسلوكه أثناء تأدية الخدمة بشكل مباشر أو غير مباشر بحيث تشمل:", "أ. أدوات لمتابعة مؤشرات الأداء التي سبق إعدادها.\nب. الأدوات التي تسمح بقياس وتحليل تفاعل المستفيد مع تلك الخدمات."],
  ["5.20.4-2", "دراسة وتحليل التقارير الناتجة من الأدوات والتقنيات الرقمية المستخدمة في قياس تجربة المستفيد والاستفادة منها في تحسين الخدمات."],
  ["5.20.4-3", "المقارنات وفقًا لمؤشرات أداء قياس تجربة المستفيد المعتمدة للخدمات المحسنة قبل وبعد التحسين."],
  ["5.20.5", "تطبيق مفهوم رحلات الحياة", "الهدف: تعريف رحلات الحياة بالتعاون مع حامل المشعل في القطاع من أجل تقديم رحلة ميسرة وموحدة للمستفيدين، على أن تضم الرحلة عددًا من الخدمات الرقمية والإجراءات المقدَّمة من قبل جهة واحدة أو أكثر، لتحقيق رحلة حياة متكاملة وموحدة من منظور المستفيد.\n\nالنطاق: الجهات المحدَّدة في الملحق رقم (7.6)، في القائمة (أ) و(ب) و(ج) بحسب ما هو مبين في هذه البطاقة.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البند (16).\n• تعميم هيئة الحكومة الرقمية رقم (2026) وتاريخ 14/9/1445 هـ، البند (ثالثًا).", "مستندات مطلوبة من الجهات المحّددة في القائمة (أ)+(ج) في الملحق رقم (7.6):\n1) إرفاق نموذج حصر رحلات الحياة وفق متطلبات تطبيق هذا المعيار.\n2) إرفاق نموذج رسم الوضع الراهن والمستهدف المعتمد لرحلات الحياة، وفق متطلبات تطبيق هذا المعيار.\n3) إرفاق ما يثبت إطلاق )3( رحلات خلال عام (2026م)، على أن تتضمن إحداهم على الأقل توظيف تقنيات الذكاء الاصطناعي، مع تضمين رابط المنصة التي نشرت فيها الرحلات.\nمستندات مطلوبة من الجهات المحّددة في القائمة (ب) في الملحق رقم (7.6):(جهات تابعة لحامل مشعل القطاع):\n4) إرفاق النموذج المعتمد لموافقة حامل المشعل في تعاون الجهة لرسم التصور المستقبلي لرحلات الحياة للمستفيدين، مع توضيح الخدمات والإجراءات التابعة للجهة ضمن رحلات القطاع."],
  ["5.20.5-1", "حصر وتعريف كافة رحلات حياة المستفيدين المقدمة لمختلف الفئات في القطاع/الجهة، مع تحديد الرحلات ذات الأولوية التي سيتم إطلاقها خلال سنة (2026م) على أن لا تقل عن (3) رحلات.", "متطلبات على الجهات المحّددة في القائمة (أ)+(ج) في الملحق رقم (7.6)"],
  ["5.20.5-2", "رسم الوضع الراهن والمستقبلي للرحلات ذات الأولوية بما يتوافق مع الحصر المعتمد، وتوضيح نقاط اتصال المستفيد، والذي يشمل الخدمات والإجراءات المقدَّمة من الجهات المالكة لها.", "متطلبات على الجهات المحّددة في القائمة (أ)+(ج) في الملحق رقم (7.6)"],
  ["5.20.5-3", "إطلاق (3) رحلات خلال عام (2026م)، على أن تتضمن إحداهم على الأقل توظيف تقنيات الذكاء الاصطناعي.", "متطلبات على الجهات المحّددة في القائمة (أ)+(ج) في الملحق رقم (7.6)"],
  ["5.20.5-4", "المواءمة مع حامل المشعل في رسم رحلات القطاع وتضمين الخدمات والإجراءات التابعة للجهة.", "متطلبات على الجهات المحّددة في القائمة (ب) في الملحق رقم (7.6):(جهات تابعة لحامل مشعل القطاع)"],
  ["P9", "كفاءة المواقع وجودة المحتوى الرقمي"],
  ["5.21", "الكفاءة الفنية للمواقع الإلكترونية", "يتضمن المحور المعايير والمتطلبات اللازمة لتحسين الظهور على محركات البحث وتعزيز موثوقية أمن الموقع الإلكتروني للجهة."],
  ["5.21.1", "موثوقية وأمن الموقع الإلكتروني للجهة", "الهدف: تعزيز موثوقية الموقع الإلكتروني للجهة عن طريق تحسين النطاق والاستضافة عبر تطبيق أفضل الممارسات التقنية، وضمان الأمان الرقمي وذلك وفقًا للتنظيمات ذات العلاقة.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البندان (1) و(18).\n• تعميم هيئة الحكومة الرقمية رقم (325) وتاريخ 23/1/1446هـ.", "1) لا يتطلب إرفاق مستند إثبات، ويتم متابعة التزام الجهات الحكومية مباشرًة من هيئة الحكومية الرقمية حسب التقارير الدورية التي تصدرها الهيئة وبما يتواءم مع \"ضوابط تطوير جودة المحتوى الرقمي للمواقع والمنصات الحكومية الرقمية لتحسين ظهورها على محركات البحث\"."],
  ["5.21.1-1", "ضمان موثوقية نطاق الموقع الإلكتروني، عن طريق الالتزام بالآتي:", "أ. تقليل الأخطاء والتحذيرات المكتشفة في الصفحات.\nب. ضمان التوجيه التلقائي للمستخدمين إلى النسخة المناسبة وفق لغتهم أو موقعهم الجغرافي."],
  ["5.21.1-2", "تفعيل شهادة الأمان (SSL)، والتأكد من سلامة بروتوكولات جميع صفحات الموقع بحيث تعمل ضمن الاتصال الآمن (HTTPS)."],
  ["5.21.2", "كفاءة الموقع الإلكتروني وتحسين ظهوره على محركات البحث", "الهدف: تعزيز جودة الموقع الإلكتروني للجهة عن طريق تحسين الأداء الفني، والظهور في النتائج الأولى لمحركات البحث عبر تطبيق أفضل الممارسات التقنية وذلك وفقًا للتنظيمات ذات العلاقة.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البندان (1) و.)18(\n• تعميم هيئة الحكومة الرقمية رقم (325) وتاريخ 23/1/1446هـ.", "1) لا يتطلب إرفاق مستند إثبات، ويتم متابعة التزام الجهات الحكومية مباشرًة من هيئة الحكومية الرقمية حسب التقارير الدورية التي تصدرها الهيئة وبما يتواءم مع \"ضوابط تطوير جودة المحتوى الرقمي للمواقع والمنصات الحكومية الرقمية لتحسين ظهورها على محركات البحث\"."],
  ["5.21.2-1", "تطوير مستوى جودة الموقع الإلكتروني من الجانب التقني، وذلك عن طريق مراقبة الأداء وتحسين مؤشرات التصفح، وتقليل حجم الصفحات، وضمان قابلية الزحف (Crawl) إلى الموقع الإلكتروني، والالتزام بالاشتراطات التقنية."],
  ["5.21.2-2", "تحسين ظهور الموقع الإلكتروني في محركات البحث عبر تهيئة الموقع الإلكتروني عن طريق اختيار الكلمات المفتاحية المناسبة، وضمان وجود خريطة الموقع، واستعراض الروابط بصورة واضحة، وصياغة عناوين مختصرة، إضافًة إلى توفير صفحة تعريفية بالجهة على منصات موثوقة مثل ويكيبيديا وخرائط (Google)."],
  ["5.22", "جودة المحتوى الرقمي", "يتضمن المحور المعايير والمتطلبات اللازمة لرفع جودة المحتوى الرقمي للمواقع الإلكترونية للجهة."],
  ["5.22.1", "القيمة المضافة للمحتوى الرقمي", "الهدف: مُشاركة المعلومات العامة وتعزيز الشفافية في جميع القطاعات الحكومية.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البندان (1) و(18).\n• قرار مجلس الوزراء رقم (40) وتاريخ 27/2/1427 هـ، البند (15).\n• قرار مجلس الوزراء رقم (555) وتاريخ 23/9/1440 هـ، الفقرة (2) من البند (ثانيًا).\n• تعميم هيئة الحكومة الرقمية رقم (325) وتاريخ 23/1/1446هـ.", "1) لا يتطلب إرفاق مستند إثبات، ويتم متابعة التزام الجهات الحكومية مباشرًة من هيئة الحكومية الرقمية حسب التقارير الدورية التي تصدرها الهيئة وبما يتواءم مع \"ضوابط تطوير جودة المحتوى الرقمي للمواقع والمنصات الحكومية الرقمية لتحسين ظهورها على محركات البحث\"."],
  ["5.22.1-1", "توافر المعلومات اللازمة للجهة على موقعها الإلكتروني، وتشمل ما يأتي:", "أ. المرجعية الإدارية للأجهزة الحكومية غير المستقلة.\nب. أرقام الاتصال، والبريد الإلكتروني، والعنوان الوطني، وأي وسيلة إلكترونية إضافية، للتواصل مع المستفيدين من خدمات الجهة الحكومية.\nت. إشعار حماية بيان الخصوصية، وحقوق الملكية، وبيان إخلاء المسؤولية شاملًا عدم تحّمل الجهة لأي مسؤولية نظامية عن استخدام البيانات أو المعلومات المنشورة في مواقعها الإلكترونية.\nث. اتفاقية الاستخدام متضمنة ما يترتب على إساءة استخدام النظم والموارد المعلوماتية والبوابة الإلكترونية للأنظمة واللوائح ذات العلاقة.\nج. أبرز الخدمات والفعاليات في مجال عملها.\nح. التعريف الشامل للبرامج والمبادرات المتعلقة برؤية المملكة 2030، وعرض الإنجازات التي جرى تنفيذها وتوضيح التابعة للرؤية.\nخ. شعار الرؤية ورابط مباشر لها.\nد. نسخة حديثة من المعلومات اللازمة للخدمات المقدَّمة للمستفيدين ومراعاة الطابع الزمني، وحقوق الطبع لتحديث الموقع ومدة التحديث.\nذ. معلومات حسابات شبكات التواصل الاجتماعي الخاصة بها.\nر. مراعاة دعم تعدد اللغات مع الحفاظ على ثبات المحتوى والمعنى عند التبديل بينها."],
  ["5.22.1-2", "نشر الأنظمة واللوائح ذات العلاقة بعمل الجهة."],
  ["5.22.1-3", "نشر معلومات عامة عن الجهة الحكومية ونشأتها ومهامها ورؤيتها ورسالتها وأهدافها والأنظمة والسياسات ذات العلاقة بمجال إشرافها والهيكل التنظيمي ومعلومات القيادات العليا مع إبراز الفرص المهنية والوظيفية المتاحة ضمن نطاق عملها."],
  ["5.22.1-4", "نشر روابط للمواقع الخاصة بأي مؤسسات/ وكالات حكومية وطنية/ محلية ذات العلاقة بعمل الجهة."],
  ["5.22.1-5", "إتاحة المحتوى على الموقع بأسلوب تفاعلي عن طريق:", "أ. تضمين مقاطع الفيديو والرسوم المعلوماتية التوضيحية وغيرها.\nب. عدم استخدام صور النص.\nت. عدم تكرار المحتوى.\nث. ضمان خلو الموقع من الصفحات الخالية من المحتوى.\nج. يكون شعار الجهة متوفرًا بخاصية الرجوع للصفحة الرئيسية."],
  ["5.22.2", "الجودة التحريرية للمحتوى الرقمي", "الهدف: ضمان إتاحة موقع إلكتروني شامل وتفاعلي يمّكن جميع فئات المستخدمين، بما فيهم ذوو الإعاقة وكبار السن، من الوصول السهل إلى محتوى ميسر وقابل للاستخدام.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (6262) وتاريخ 26/1/1445 هـ، البندان (1) و(18).\n• تعميم هيئة الحكومة الرقمية رقم (325) وتاريخ 23/1/1446هـ.", "1) لا يتطلب إرفاق مستند إثبات، ويتم متابعة التزام الجهات الحكومية مباشرًة من هيئة الحكومية الرقمية حسب التقارير الدورية التي تصدرها الهيئة وبما يتواءم مع \"ضوابط تطوير جودة المحتوى الرقمي للمواقع والمنصات الحكومية الرقمية لتحسين ظهورها على محركات البحث\"."],
  ["5.22.2-1", "ضمان تنظيم المحتوى من خلال الالتزام بالآتي:", "أ. تيسير التنقل بين العناوين والفقرات.\nب. التأكد من أن الصور والأشكال المستخدمة معبرة بصورة واضحة وأن تكون ذات جودة."],
  ["5.22.2-2", "الالتزام باشتراطات إنتاج وتدقيق المحتوى في المواقع الإلكترونية، بما يشمل:", "أ. خلو النصوص من الأخطاء الإملائية واللغوية.\nب. استخدام المصطلحات والاختصارات بصورة مناسبة وواضحة.\nت. توحيد النبرة التحريرية."],
  ["5.22.2-3", "التأكد من تناسق وتناغم الترويسة والتذييل في كافة الصفحات للموقع الإلكتروني للجهة مع ثبات الروابط المهمة بما يشمل:", "أ. السياسات.\nب. اتصل بنا.\nت. خدمة العملاء.\nث. الأسئلة الأكثر شيوعًا."],
  ["P10", "البحث والابتكار"],
  ["5.23", "الابتكار المؤسسي", "يتضمن المحور الممارسات والإجراءات التي تُمِّكن الجهة لرفع جاهزيتها نحو تبِّني الابتكار واستدامة البيئة الابتكارية في مجال الحكومة الرقمية."],
  ["5.23.1", "تبِّني الابتكار كتوجه إستراتيجي", "الهدف: تعزيز مفهوم الابتكار في الإستراتيجيات المختلفة للجهات الحكومية بما يشمل إستراتيجية التحول الرقمي الخاصة بالجهة، والذي يضمن وجود توجه إستراتيجي لدى الجهة لتفعيل وتبِّني الابتكار.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (58071) وتاريخ 9/8/1445 هـ، البند (خامسًا).", "1) إرفاق إستراتيجية التحول الرقمي بحيث تتضمن البحث والابتكار وفق متطلبات تطبيق هذا المعيار.\n2) إرفاق الوثائق التي توضح مبادرات ومشاريع البحث والابتكار، ومؤشرات الأداء وفق متطلبات تطبيق هذا المعيار.\n3) إرفاق اتفاقية تعاون معتمدة مع جهات ومراكز ومختبرات البحث والتطوير والابتكار الوطنية أو الدولية وفق متطلبات تطبيق هذا المعيار."],
  ["5.23.1-1", "تضمين البحث والابتكار كأحد العناصر في إستراتيجية التحول الرقمي للجهة، وتحديد مجالات الابتكار، ووضع الأهداف والمؤشرات الإستراتيجية لتفعيل مفهوم البحث والابتكار ومواءمتها مع الأهداف الإستراتيجية للجهة."],
  ["5.23.1-2", "تحديد مبادرات ومشاريع الابتكار الرقمي، ومواءمتها مع الأولويات والمستهدفات الإستراتيجية للجهة، ومؤشرات الأداء التي تقيس نجاح تنفيذ هذه المبادرات والمشاريع."],
  ["5.23.1-3", "التعاون مع جهات ومراكز ومختبرات البحث والتطوير والابتكار الوطنية أو الدولية المتخصصة، بما يضمن الاستفادة من الخبرات والممكنات لتفعيل الابتكار بالجهة وتطبيق الحلول الابتكارية."],
  ["5.23.2", "تطبيق منهجيات الابتكار", "الهدف: تبني منهجيات ومفاهيم الابتكار بما يضمن تطوير واستدامة البيئة الابتكارية، ويساهم في ابتكار منتجات، وخدمات، وحلول ابتكارية، واستدامتها من خلال إشراك مختلف شرائح المستفيدين والمختصين.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (58071) وتاريخ 9/8/1445 هـ، البند (خامسًا).", "1) إرفاق خطة سنوية متكاملة لتنفيذ الفعاليات الابتكارية وفق متطلبات تطبيق هذا المعيار.\n2) إرفاق الوثائق المحدَّثة التي تثبت تبِّني أطر ومنهجيات الابتكار مثل التصميم الإبداعي، وما يثبت عقد ما لا يقل عن (جلستين) للعصف الذهني لمعالجة التحديات وتوليد الأفكار وفق متطلبات تطبيق هذا المعيار .\n3) إرفاق الوثائق المحدَّثة التي تثبت تبِّني منهجية الابتكار المفتوح في الجهة وفق متطلبات تطبيق هذا المعيار.\n4) إرفاق الوثائق المحدثة التي توضح تفعيل التعاون مع الجهات والمراكز والشركات المتخصصة من خلال اتفاقيات التعاون في البحث والابتكار وفق متطلبات تطبيق هذا المعيار ."],
  ["5.23.2-1", "إعداد خطة سنوية متكاملة لتنفيذ الفعاليات الابتكارية، تتضمن الأهداف والمخرجات المتوقعة وآلية المتابعة والتقييم لكل فعالية، بما يضمن استدامة تطبيق الابتكار في الجهة."],
  ["5.23.2-2", "تبني منهجيات الابتكار وتفعيلها من قبل منسوبي الجهة مثل التصميم الإبداعي وعقد جلسات العصف الذهني لمعالجة التحديات وتوليد الأفكار في الجهة بما يشمل:", "أ. المنهجيات المستخدمة وطرق تطبيقها على مخرج واحد على الأقل.\nب. المشاركون في تطبيق المنهجيات المستخدمة.\nت. التحديات التي جرى تحديدها في الجلسات والحلول المقترحة، وتوثيقها ضمن سجل أو قاعدة بيانات محدثة.\nث. النماذج الأولية المطّورة )Prototypes( أثناء الفعاليات، مع توثيق مراحل التطوير والنتائج المتحققة.\nج. المشاريع المنفَّذة بناًء على الأفكار الناتجة، ومتابعة مؤشرات أدائها، وقياس أثرها على التحول الرقمي والخدمات المقدمة للمستفيدين."],
  ["5.23.2-3", "تبِّني منهجية الابتكار المفتوح وإشراك المستفيدين بمختلف شرائحهم للمساهمة في تصميم الحلول والخدمات، من خلال فعاليات الابتكار المفتوح مثل الهاكاثونات والمسابقات والورش المتخصصة، بما يشمل:", "أ. الطرق والأساليب والفعاليات المستخدمة مثل الهاكاثونات أو المسابقات أو الورش المتخصصة (الأولوية للهاكاثونات التي تتم بالشراكة مع الجهات والمراكز المختصة بمثل هذه الفعاليات).\nب. التحديات التي تم مناقشتها في فعاليات الابتكار المفتوح والحلول المقترحة، وتوثيقها ضمن سجل أو قاعدة بيانات محدثة. ت.(3) عينات على الأقل توثق إقامة كل فعالية.\nث. أعداد وفئات المشاركين في الفعاليات.\nج. عينات من الشهادات التي مُِنحت للمشاركين، وقوائم المشاريع الفائزة.\nح. النماذج الأولية المطّورة )Prototypes( أثناء الفعاليات، مع توثيق مراحل التطوير والنتائج المتحققة.\nخ. المشاريع التي تم تنفيذها بناًء على الأفكار التي تم التوصل إليها خلال الفعاليات، مع قياس أثرها على التحول الرقمي والخدمات المقدمة للمستفيدين."],
  ["5.23.2-4", "تفعيل التعاون مع الجهات والمراكز والشركات المتخصصة في البحث والابتكار بحيث يشمل ما يأتي:", "أ. عقد اجتماعات دورية (بحد أدنى اجتماعات ربعية) لمتابعة تفعيل اتفاقيات التعاون مع الجهات والمراكز والمختبرات والشركات المتخصصة في البحث والابتكار بما يتناسب مع مراحل التنفيذ والمخرجات المتوقعة.\nب. تحديد مخرجات التعاون وتوثيقها، مثل الدراسات البحثية، نقل المعرفة، تطوير النماذج الأولية أو إثبات المفهوم وفقًا لما نصت عليه اتفاقيات التعاون في مجال البحث والابتكار.\nت. إصدار التقارير الدورية التي توضح التقدم المحرز، وتشمل ما تم إنجازه وفقًا لاتفاقيات التعاون.\nث. دراسة وتحليل التقارير الدورية وإصدار قرارات وإجراءات تصحيحية بناًء على نتائج التقارير الدورية للمتابعة."],
  ["5.23.3", "حوكمة وتفعيل الابتكار", "الهدف: وضع إطار أو آلية خاصة لحوكمة الابتكار في التحول الرقمي يهدف إلى متابعة تنفيذ مبادرات الابتكار، وضمان تحقيق المستهدفات واستدامة الحلول والمنتجات، وحفظ حقوق الجهات وملكيتها الفكرية لمنتجاتها الابتكارية.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (58071) وتاريخ 9/8/1445 هـ، البند (خامسًا).", "1) إرفاق هيكل الوحدة الإدارية أو اللجنة ضمن الهيكل الإداري للجهة وتحديد الأدوار والمسؤوليات المناطة بها.\n2) إرفاق الوثائق المحدَّثة التي تثبت تفعيل الوحدة الإدارية /اللجنة المختصة وفق متطلبات تطبيق هذا المعيار .\n3) إرفاق تقارير إنجاز حديثة للفعاليات والأنشطة التي سبق تنفيذها لنشر ثقافة الابتكار بما لا يقل عن (3) فعاليات وفق متطلبات تطبيق هذا المعيار.\n4) إرفاق إطار أو آلية معتمدة لإدارة الابتكار الرقمي وفق متطلبات تطبيق هذا المعيار.\n5) إرفاق عينات حديثة من الشاشات التي توضح أتمتة تلِّقي المقترحات الابتكارية، والملاحظات على الحلول الابتكارية من مختلف شرائح المستفيدين."],
  ["5.23.3-1", "تشكيل وحدة إدارية أو لجنة لتحفيز وتبِّني الابتكار ومفاهيمه داخل الجهة، وتحديد أدوارها ومسؤولياتها."],
  ["5.23.3-2", "تفعيل الوحدة الإدارية /اللجنة واعتماد إجراءاتها وعملياتها مع الإدارات واللجان ذات العلاقة، بحيث تشمل ما يأتي :", "أ. تحديد عمليات وإجراءات الوحدة/اللجنة، وتطوير بطاقات لتوثيقها، واعتمادها من المسؤول الأول في الجهة أو من ينوب عنه.\nب. اعتماد سياسات داعمة لتنظيم وتشجيع الابتكار داخل الجهة.\nت. وجود آلية لمراجعة الأفكار والمشاريع قبل التنفيذ، لضمان جدواها وقابليتها للتطبيق.\nث. إعداد بطاقات مبادرات ومشاريع الابتكار الرقمي بالجهة.\nج. إصدار تقارير الأداء الدورية لمبادرات ومشاريع الابتكار الرقمي توضح نسبة الإنجاز في مراحل التنفيذ بناء على مؤشرات الأداء المعتمدة.\nح. دراسة التقارير الدورية وإصدار قرارات وإجراءات تصحيحية بناًء على نتائج الدراسة."],
  ["5.23.3-3", "تنظيم فعاليات وأنشطة لنشر بيئة وثقافة الابتكار في الجهة، عبر التدريب وورش زيادة الوعي والمعرفة."],
  ["5.23.3-4", "تطوير آلية لإدارة الابتكار الرقمي، توضح الرحلة الكاملة وتبين الإجراءات التي تتخذها الجهة، لضمان استدامة الخروج بأفكار إبداعية وانتقالها من الفكرة والتصميم إلى التطوير والتنفيذ."],
  ["5.23.3-5", "إنشاء آليات لتلِّقي المقترحات الابتكارية، والملاحظات على الحلول الابتكارية المطوَّرة."],
  ["5.24", "الحلول الابتكارية", "يشمل المحور معايير ومتطلبات لتطوير وتنفيذ الحلول الابتكارية لتحقيق القيمة المضافة، وقياس الأثر لاستدامة الحلول الابتكارية ومتابعة تحسينها بشكل مستمر في مجال الحكومة الرقمية."],
  ["5.24.1", "حصر وتطوير الحلول الابتكارية وتطبيقها", "الهدف: حصر المبادرات والحلول الابتكارية لدى الجهة، وتصميم حلول ابتكارية تحِّقق مفهوم التحّول الرقمي وتنفيذها على أرض الواقع بما يمِّكن من تحقيق قيمة مضافة للجهة وللمستفيد.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (58071) وتاريخ 9/8/1445 هـ، البند (خامسًا).", "1) إرفاق وثيقة حصر جميع المبادرات والحلول الابتكارية المطبقة والقابلة للتطبيق وفق متطلبات تطبيق هذا المعيار.(فيما يخص الجهات المحددة في الملحق (7.6) يتم التقييم بناء على نتيجة الجهة في عنصر الابتكار بدافع تقني ضمن مؤشر جاهزية تبني التقنيات الناشئة، علمًا أنه يمكن إرفاق وثيقة حصر محدثة وفق متطلبات تطبيق هذا المعيار).\n2) إرفاق نموذج واحد لحل ابتكاري وفق متطلبات تطبيق هذا المعيار."],
  ["5.24.1-1", "حصر جميع المبادرات والحلول الابتكارية المطبقة والقابلة للتطبيق، والمتوافقة مع مجالات تركيز وأولويات الجهة الاستراتيجية، على أن تشمل الآتي:", "أ. اسم الحل أو الفكرة ووصفها، مع تكلفة التنفيذ ومدة الإنجاز، وتاريخ الإطلاق إن وُجد.\nب. الفئات المستهدفة، وأعداد المستفيدين.\nت. التقنيات الناشئة المستخدمة أو المخطط استخدامها في التطوير.\nث. الأثر المحقق أو المتوقع على الجهة والمستفيدين، بما يشمل تخفيض التكاليف.\nج. المرحلة الحالية للمبادرة أو الحل (مفهوم، نموذج عمل، إثبات المفهوم، نسخة تجريبية، التشغيل).\nح. نسبة رضا المستفيدين."],
  ["5.24.1-2", "تصميم وتنفيذ الحل الابتكاري وتطبيقه، مع الالتزام بما يأتي:", "أ. وصف مختصر للمشكلة أو التحدي الذي يعالجه الحل المقدم، مع بيان الأثر المتوقع قبل التطبيق، وشرح موجز لكيفية معالجة المشكلة عن طريق الحل الابتكاري، وتوضيح النتائج المحققة بعد التنفيذ.\nب. أن يكون الحل الابتكاري مستخدمًا منذ فترة لا تقل عن 6 أشهر ولا تزيد عن 5 سنوات، وليس في مرحلة التخطيط أو التصميم أو التجريب.\nت. ألاَّيكون الحل الابتكاري قد تم تقديمه في الدورات السابقة لقياس إلا إذا طرأ عليه تطور كبير، على أن يتم توضيح ذلك.\nث. أن تكون فكرة الحل الابتكاري مبنيًة على منهجيات الابتكار، مع تحديد مصدرها.\nج. ربط الحل الابتكاري بالأهداف الإستراتيجية العامة للجهة وخططها للتحول الرقمي بما يضمن توافقه مع رؤيتها ومستهدفاتها الرئيسية.\nح. استخدام التقنيات الناشئة والحديثة في تطوير الحل الابتكاري.\nخ. توضيح جميع البيانات والمعلومات التفصيلية عن الحل الابتكاري والتقنيات والمفاهيم المستخدمة في تصميمه وبنائه.\nد. إعداد تقارير تفصيلية توضح مراحل تنفيذ الحل وتطبيقه، مع تحديد الشريحة المستفيدة منه."],
  ["5.24.2", "قياس الأثر من تطبيق الحلول الابتكارية", "الهدف: تقييــم النتائــج والآثــار المحققة من تنفيذ الحلول الابتكارية، وتوضيح القيمة المضافة، والتحسين المستمر للحلول الابتكارية.\n\nالنطاق: جميع الجهات الحكومية.\n\nالأنظمة والأوامر والقرارات والتعاميم المرتبطة:\n• تعميم الديوان الملكي رقم (58071) وتاريخ 9/8/1445 هـ، البند (خامسًا).", "1) إرفاق المنهجية المستخدمة في قياس أثر الحلول الابتكارية قبل تنفيذ الحل وبعده وفق متطلبات تطبيق هذا المعيار.\n2) إرفاق تقرير للأثر الناتج عن تطبيق الحل الابتكاري وفق متطلبات تطبيق هذا المعيار.\n3) إرفاق الوثائق التي تثبت استدامة الحل الابتكاري المقدَّم، وفق متطلبات تطبيق هذا المعيار.\n4) إرفاق الوثائق التي تثبت حصول الحل الابتكاري على جوائز محلية، أو إقليمية، أو دولية."],
  ["5.24.2-1", "تطوير منهجية لقياس الأثر من تطبيق الحلول الابتكارية تفصل الفئات المستهدفة، وتتبن ىَّ تحليل البيانات بفعالية، وتحِّدد أصناف الآثار المتوقعة (اقتصادية، اجتماعية، مالية، وظيفية،..) سواء كانت إيجابيًة أو سلبية، قبل وبعد تنفيذ الحل."],
  ["5.24.2-2", "تقييم الآثار المحققة من تطبيق الحل الابتكاري المقدَّم في المعيار السابق، بحيث تشمل ما يأتي:", "أ. الأثر على المستفيدين (يتضمن شرائح المستفيدين ونسب التحقق والدراسات ومنهجيات إحصائها).\nب. الأثر المالي (يتضمن تقليل التكاليف وتحقيق العوائد، بالإضافة إلى استغلال وتحسين الموارد).\nت. الأثر على الجهة (يتضمن نماذج الأعمال وتحسين الأداء وتحقيق الكفاءة التشغيلية)."],
  ["5.24.2-3", "استدامة الحل الابتكاري المقدم، من خلال تقديم قيمة طويلة الأمد دون الحاجة إلى تغييرات جذرية مستمرة، وإرفاق دراسات ومقارنات للوضع السابق قبل وبعد تطبيق الحل."],
  ["5.24.2-4", "حصول الحل الابتكاري المقدَّم على جوائز محلية أو إقليمية أو دولية."],
];

export const QIYAS_V5_LEVELS: HierarchyLevel[] = [
  { id: "lv-1", en: "Perspective", ar: "المنظور", pattern: "P#", assessed: "rollup" },
  { id: "lv-2", en: "Axis", ar: "المحور", pattern: "5.#", assessed: "rollup" },
  { id: "lv-3", en: "Standard", ar: "المعيار", pattern: "5.#.#", assessed: "accepted" },
  { id: "lv-4", en: "Implementation requirement", ar: "متطلب التطبيق", pattern: "5.#.#-#", assessed: "ai_reviewer" },
];

const levelOf = (code: string) => (code.startsWith("P") ? "lv-1" : code.includes("-") ? "lv-4" : code.split(".").length === 2 ? "lv-2" : "lv-3");
const parentOf = (code: string, perspective: string) => {
  if (code.startsWith("P")) return undefined;
  if (code.includes("-")) return code.slice(0, code.lastIndexOf("-"));
  const parts = code.split(".");
  return parts.length === 2 ? perspective : parts.slice(0, 2).join(".");
};

/** Perspective › axis › standard › implementation requirement. Standards carry the objective, scope, regulations and evidence documents. */
export const QIYAS_V5_REQUIREMENTS: FrameworkRequirement[] = (() => {
  let perspective = "";
  return ROWS.map(([code, ar, textAr, evidenceAr]) => {
    if (code.startsWith("P")) perspective = code;
    const r: FrameworkRequirement = { code, level: levelOf(code), title: "", titleAr: ar, source: "DGA-1-2-1-111 V5.0" };
    const parent = parentOf(code, perspective);
    if (parent) r.parent = parent;
    if (textAr) r.textAr = textAr;
    if (evidenceAr) r.evidenceAr = evidenceAr;
    return r;
  });
})();
